        assertTrue(hasAllSameLowValue, filename + " must test all entries equal to 1");
        assertTrue(hasMultipleSeparatedGaps, filename + " must test multiple separated gaps");
        assertTrue(hasReversedAllPresent, filename + " must test an unsorted array with no missing values");
