    private static void assertGenerateParenthesesTestCoverage(JsonArray tests, String filename) {
        Set<Integer> missingN = new HashSet<>(Set.of(1, 2, 3, 4, 5));

        for (int i = 0; i < tests.size(); i++) {
            JsonObject test = requireObject(tests.get(i), filename + " tests[" + i + "]");
            String input = compactOutsideDoubleQuotedText(
                    requireString(test, "input", filename + " tests[" + i + "]"));
            Matcher matcher = Pattern.compile("n=(\\d+)").matcher(input);
            if (!matcher.matches()) {
                continue;
            }

            int n = Integer.parseInt(matcher.group(1));
            if (!missingN.contains(n)) {
                continue;
            }

            String output = requireString(test, "output", filename + " tests[" + i + "]");
            Set<String> actual = parseStringArrayOutput(output, filename + " tests[" + i + "] output");
            if (actual.equals(expectedGenerateParentheses(n))) {
                missingN.remove(n);
            }
        }

        assertTrue(missingN.isEmpty(),
                filename + " must test Generate Parentheses with complete Catalan output sets for n=1, n=2, "
                        + "n=3, n=4, and n=5; missing or incorrect n values " + missingN);
    }

    private static Set<String> parseStringArrayOutput(String output, String context) {
        JsonElement parsed = JsonParser.parseString(output);
        assertTrue(parsed.isJsonArray(), context + " should be a JSON array of strings");
        JsonArray array = parsed.getAsJsonArray();
        Set<String> values = new HashSet<>();
        for (int i = 0; i < array.size(); i++) {
            JsonElement element = array.get(i);
            assertTrue(element.isJsonPrimitive() && element.getAsJsonPrimitive().isString(),
                    context + "[" + i + "] should be a string");
            assertTrue(values.add(element.getAsString()),
                    context + " should not repeat generated parenthesis string: " + element.getAsString());
        }
        return values;
    }

