    private static Set<String> expectedGenerateParentheses(int n) {
        Set<String> result = new HashSet<>();
        generateExpectedParentheses(n, 0, 0, new StringBuilder(), result);
        return result;
    }

    private static void generateExpectedParentheses(
            int n, int open, int close, StringBuilder path, Set<String> result) {
        if (path.length() == 2 * n) {
            result.add(path.toString());
            return;
        }
        if (open < n) {
            path.append('(');
            generateExpectedParentheses(n, open + 1, close, path, result);
            path.deleteCharAt(path.length() - 1);
        }
        if (close < open) {
            path.append(')');
            generateExpectedParentheses(n, open, close + 1, path, result);
            path.deleteCharAt(path.length() - 1);
        }
    }

    private static String compactOutsideDoubleQuotedText(String text) {
        StringBuilder compact = new StringBuilder();
        boolean inString = false;
        boolean escaped = false;
        for (int i = 0; i < text.length(); i++) {
            char c = text.charAt(i);
            if (inString) {
                compact.append(c);
                if (escaped) {
                    escaped = false;
                } else if (c == '\\') {
                    escaped = true;
                } else if (c == '"') {
                    inString = false;
                }
            } else if (c == '"') {
                inString = true;
                compact.append(c);
            } else if (!Character.isWhitespace(c)) {
                compact.append(c);
            }
        }
        return compact.toString();
    }

    private static void assertDiagramMetadata(JsonArray diagrams, String filename) {
        assertFalse(diagrams.isEmpty(), filename + " diagrams should be omitted instead of empty");

        Set<String> ids = new HashSet<>();
        Set<String> files = new HashSet<>();
        for (int i = 0; i < diagrams.size(); i++) {
            JsonObject diagram = requireObject(diagrams.get(i), filename + " diagrams[" + i + "]");
            String id = requireNonBlankString(diagram, "id", filename + " diagrams[" + i + "]");
            String file = requireNonBlankString(diagram, "file", filename + " diagrams[" + i + "]");
            String caption = requireNonBlankString(diagram, "caption", filename + " diagrams[" + i + "]");

            assertTrue(ids.add(id), filename + " repeats diagram id: " + id);
            assertTrue(files.add(file), filename + " repeats diagram file: " + file);
            assertTrue(DIAGRAM_FILE.matcher(file).matches(),
                    filename + " diagram file should be a normalized problem PNG: " + file);
            assertTrue(Files.exists(QUESTION_BANK.resolve("images").resolve(file)),
                    filename + " diagram file is missing: " + file);
            assertFalse(DISALLOWED_PROMPT_DIAGRAM_FILES.contains(file),
                    filename + " should not reference known answer/result diagram file: " + file);
            assertFalse(RESULT_OR_SOLUTION_DIAGRAM.matcher(file).matches(),
                    filename + " should not reference output/result diagram file: " + file);
            // An explicitly identified example state or rule illustration may show
            // a valid outcome. A blanket ban on words such as "after" hides the
            // operation timing that makes design-class diagrams understandable.
            if (RESULT_OR_SOLUTION_DIAGRAM.matcher(caption).matches()) {
                assertTrue(Pattern.compile("(?i).*(example|illustrat|rule).*").matcher(caption).matches(),
                        filename + " diagram outcomes must identify their example or rule context: " + caption);
            }
            assertFalse(SOLUTION_HINT_CAPTION.matcher(caption).matches(),
                    filename + " diagram caption should avoid solution-technique hints: " + caption);
        }
    }

    private static JsonObject readObject(Path path) throws IOException {
        JsonElement parsed = JsonParser.parseString(Files.readString(path, StandardCharsets.UTF_8));
        return requireObject(parsed, path.toString());
    }

    private static void assertManifestEntryMatches(Path path, Map<String, JsonObject> manifestByName) throws IOException {
        String name = relativeManifestName(path);
        JsonObject entry = manifestByName.get(name);
        assertNotNull(entry, "manifest is missing entry for " + name);

        byte[] manifestBytes = readManifestBytes(path);
        assertEquals(requireNonBlankString(entry, "hash", "manifest " + name),
                sha256(manifestBytes), "manifest hash mismatch for " + name);
        assertEquals(requireInt(entry, "size", "manifest " + name),
                manifestBytes.length, "manifest size mismatch for " + name);
    }

    private static CatalogIndex readCatalogIndex(JsonObject catalog) {
        requireNonBlankString(catalog, "version", "catalog");
        JsonArray tracks = requireArray(catalog, "tracks", "catalog");
        assertFalse(tracks.isEmpty(), "catalog should define at least one track");

        Set<String> trackIds = new HashSet<>();
        Set<String> tags = new HashSet<>();
        Map<String, Set<String>> trackTags = new HashMap<>();

        for (int i = 0; i < tracks.size(); i++) {
            JsonObject track = requireObject(tracks.get(i), "catalog tracks[" + i + "]");
            String id = requireNonBlankString(track, "id", "catalog tracks[" + i + "]");
            requireNonBlankString(track, "name", "catalog tracks[" + i + "]");
            assertTrue(trackIds.add(id), "catalog repeats track id: " + id);

            JsonArray tagArray = requireArray(track, "tags", "catalog tracks[" + i + "]");
            assertFalse(tagArray.isEmpty(), "catalog track should include at least one tag: " + id);
            Set<String> currentTrackTags = new HashSet<>();
            for (int j = 0; j < tagArray.size(); j++) {
                assertTrue(tagArray.get(j).isJsonPrimitive() && tagArray.get(j).getAsJsonPrimitive().isString(),
                        "catalog tracks[" + i + "] tags[" + j + "] should be a string");
                String tag = tagArray.get(j).getAsString();
                assertFalse(tag.isBlank(), "catalog track tag should not be blank: " + id);
                assertTrue(currentTrackTags.add(tag), "catalog repeats tag within track " + id + ": " + tag);
                assertTrue(tags.add(tag), "catalog tag should belong to exactly one track: " + tag);
            }
            trackTags.put(id, currentTrackTags);
        }

        return new CatalogIndex(tags, trackTags);
    }

    private static JsonObject requireObject(JsonElement element, String context) {
        assertTrue(element != null && element.isJsonObject(), context + " should be a JSON object");
        return element.getAsJsonObject();
    }

    private static JsonArray requireArray(JsonObject object, String field, String context) {
        assertTrue(object.has(field) && object.get(field).isJsonArray(), context + " should have array field '" + field + "'");
        return object.getAsJsonArray(field);
    }

    private static String requireNonBlankString(JsonObject object, String field, String context) {
        String value = requireString(object, field, context);
        assertFalse(value.isBlank(), context + " field '" + field + "' should not be blank");
        return value;
    }

    private static String requireString(JsonObject object, String field, String context) {
        assertTrue(object.has(field)
                        && object.get(field).isJsonPrimitive()
                        && object.get(field).getAsJsonPrimitive().isString(),
                context + " should have string field '" + field + "'");
        return object.get(field).getAsString();
    }

    private static int requireInt(JsonObject object, String field, String context) {
        assertTrue(object.has(field)
                        && object.get(field).isJsonPrimitive()
                        && object.get(field).getAsJsonPrimitive().isNumber(),
                context + " should have numeric field '" + field + "'");
        return object.get(field).getAsInt();
    }

    private static void assertSolutionComplexityMetadata(JsonObject solution, String description, String context) {
        boolean markdownComplexity = description.contains("## Complexity Analysis")
                && description.contains("Time Complexity")
                && description.contains("Space Complexity");
        String timeComplexity = optionalString(solution, "timeComplexity", context);
        String spaceComplexity = optionalString(solution, "spaceComplexity", context);
        boolean fieldComplexity = timeComplexity != null && spaceComplexity != null;

        assertTrue(markdownComplexity || fieldComplexity,
                context + " should include explicit time and space complexity metadata");
        if (timeComplexity != null || spaceComplexity != null) {
            assertTrue(timeComplexity != null && spaceComplexity != null,
                    context + " should provide timeComplexity and spaceComplexity together");
            assertTrue(COMPLEXITY_NOTATION.matcher(timeComplexity).matches(),
                    context + " timeComplexity should use Big-O notation: " + timeComplexity);
            assertTrue(COMPLEXITY_NOTATION.matcher(spaceComplexity).matches(),
                    context + " spaceComplexity should use Big-O notation: " + spaceComplexity);
        }
    }

    private static void assertReviewedSolutionTeachingSections(String description, String context) {
        assertTrue(description.contains("## Approach"),
                context + " should include a dedicated Approach section after textbook review");
        assertTrue(description.contains("## Key Insight"),
                context + " should include a dedicated Key Insight section after textbook review");
    }

    private static void assertProductExceptSelfReferenceSolutionRespectsPrompt(
            JsonObject solution, String description, String code, String context) {
        String timeComplexity = optionalString(solution, "timeComplexity", context);
        String complexityText = description + "\n" + (timeComplexity == null ? "" : timeComplexity);
        assertTrue(complexityText.contains("O(n)"),
                context + " must document the O(n) time required by Product of Array Except Self");
        assertFalse(LINEAR_TIME_PROMPT_NON_LINEAR_COMPLEXITY.matcher(complexityText).find(),
                context + " must not offer a non-linear reference solution for an O(n) prompt");

        String codeWithoutCommentsOrLiterals = stripJavaCommentsAndLiterals(code);
        assertFalse(JAVA_DIVISION_OPERATOR.matcher(codeWithoutCommentsOrLiterals).find(),
                context + " must not use division for Product of Array Except Self");
    }

