    private static void assertMajorityElementSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 4,
                filename + " should teach Boyer-Moore, counting, sorting, and divide-and-conquer routes");

        boolean hasBoyerMooreCancellation = false;
        boolean hasCountingBaseline = false;
        boolean hasSortingMedian = false;
        boolean hasDivideAndConquer = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String codeWithoutCommentsOrLiterals = stripJavaCommentsAndLiterals(code);

            boolean documentsConstantSpace = description.contains("Space Complexity: O(1)")
                    || "O(1)".equals(optionalString(solution, "spaceComplexity", filename + " solutions[" + i + "]"));
            hasBoyerMooreCancellation = hasBoyerMooreCancellation
                    || ((searchable.contains("boyer") || searchable.contains("moore") || searchable.contains("voting"))
                    && (searchable.contains("cancel") || searchable.contains("vote"))
                    && documentsConstantSpace
                    && codeWithoutCommentsOrLiterals.contains("count == 0"));
            hasCountingBaseline = hasCountingBaseline
                    || ((searchable.contains("hash") || searchable.contains("count"))
                    && codeWithoutCommentsOrLiterals.contains("getOrDefault"));
            hasSortingMedian = hasSortingMedian
                    || ((searchable.contains("sort") || searchable.contains("median"))
                    && JAVA_SORT_CALL.matcher(codeWithoutCommentsOrLiterals).find()
                    && codeWithoutCommentsOrLiterals.contains("nums.length / 2"));
            hasDivideAndConquer = hasDivideAndConquer
                    || (searchable.contains("divide") && searchable.contains("conquer")
                    && codeWithoutCommentsOrLiterals.contains("majority(")
                    && codeWithoutCommentsOrLiterals.contains("countInRange"));
        }

        assertTrue(hasBoyerMooreCancellation,
                filename + " must include Boyer-Moore with the cancellation/voting invariant and O(1) space");
        assertTrue(hasCountingBaseline, filename + " must include an explicit counting baseline");
        assertTrue(hasSortingMedian, filename + " must include the sorting-median proof route");
        assertTrue(hasDivideAndConquer, filename + " must include the classic divide-and-conquer route");
    }

