    private static void assertLongestIncreasingPathMatrixSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " should teach DFS memoization, topological BFS from local minima, value-sorted DP, "
                        + "reverse topological BFS from local maxima, and explicit-stack postorder DFS");

        boolean hasDfsMemoization = false;
        boolean hasTopologicalBfsFromMinima = false;
        boolean hasValueSortedDp = false;
        boolean hasReverseTopologicalBfsFromMaxima = false;
        boolean hasExplicitStackPostorderDfs = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String codeWithoutCommentsOrLiterals = stripJavaCommentsAndLiterals(code);
            String normalizedCode = normalizeCode(codeWithoutCommentsOrLiterals).toLowerCase(Locale.ROOT);

            hasDfsMemoization = hasDfsMemoization
                    || ((searchable.contains("dfs") && searchable.contains("memo"))
                    && normalizedCode.contains("int[][]memo=newint[m][n]")
                    && normalizedCode.contains("answer=math.max(answer,dfs(matrix,memo,row,col))")
                    && normalizedCode.contains("if(memo[row][col]!=0)")
                    && normalizedCode.contains("matrix[nextrow][nextcol]>matrix[row][col]")
                    && normalizedCode.contains("best=math.max(best,1+dfs(matrix,memo,nextrow,nextcol))")
                    && normalizedCode.contains("memo[row][col]=best"));
            hasTopologicalBfsFromMinima = hasTopologicalBfsFromMinima
                    || ((searchable.contains("topological") || searchable.contains("local minima"))
                    && normalizedCode.contains("int[][]indegree=newint[m][n]")
                    && normalizedCode.contains("matrix[nextrow][nextcol]>matrix[row][col]")
                    && normalizedCode.contains("indegree[nextrow][nextcol]++")
                    && normalizedCode.contains("java.util.arraydeque<int[]>queue=newjava.util.arraydeque<>()")
                    && normalizedCode.contains("if(indegree[row][col]==0)")
                    && normalizedCode.contains("while(!queue.isempty())")
                    && normalizedCode.contains("layers++")
                    && normalizedCode.contains("--indegree[nextrow][nextcol]==0")
                    && normalizedCode.contains("returnlayers"));
            hasValueSortedDp = hasValueSortedDp
                    || ((searchable.contains("value-sorted") || searchable.contains("sort"))
                    && normalizedCode.contains("int[][]cells=newint[m*n][3]")
                    && normalizedCode.contains("java.util.arrays.sort(cells")
                    && normalizedCode.contains("int[][]dp=newint[m][n]")
                    && normalizedCode.contains("for(int[]cell:cells)")
                    && normalizedCode.contains("matrix[nextrow][nextcol]<value")
                    && normalizedCode.contains("dp[row][col]=math.max(dp[row][col],dp[nextrow][nextcol]+1)")
                    && normalizedCode.contains("returnanswer"));
            hasReverseTopologicalBfsFromMaxima = hasReverseTopologicalBfsFromMaxima
                    || ((searchable.contains("reverse topological") || searchable.contains("local maxima"))
                    && normalizedCode.contains("int[][]outdegree=newint[m][n]")
                    && normalizedCode.contains("matrix[nextrow][nextcol]>matrix[row][col]")
                    && normalizedCode.contains("outdegree[row][col]++")
                    && normalizedCode.contains("if(outdegree[row][col]==0)")
                    && normalizedCode.contains("while(!queue.isempty())")
                    && normalizedCode.contains("matrix[nextrow][nextcol]<matrix[row][col]")
                    && normalizedCode.contains("--outdegree[nextrow][nextcol]==0")
                    && normalizedCode.contains("returnlayers"));
            hasExplicitStackPostorderDfs = hasExplicitStackPostorderDfs
                    || ((searchable.contains("explicit-stack") || searchable.contains("postorder"))
                    && normalizedCode.contains("java.util.arraydeque<int[]>stack=newjava.util.arraydeque<>()")
                    && normalizedCode.contains("stack.push(newint[]{row,col,0})")
                    && normalizedCode.contains("while(!stack.isempty())")
                    && normalizedCode.contains("int[]state=stack.peek()")
                    && normalizedCode.contains("if(state[2]==0)")
                    && normalizedCode.contains("state[2]=1")
                    && normalizedCode.contains("stack.push(newint[]{nextrow,nextcol,0})")
                    && normalizedCode.contains("memo[r][c]=best")
                    && normalizedCode.contains("stack.pop()"));
        }

        assertTrue(hasDfsMemoization,
                filename + " must include the DFS memoization route");
        assertTrue(hasTopologicalBfsFromMinima,
                filename + " must include the topological BFS from local minima route");
        assertTrue(hasValueSortedDp,
                filename + " must include the value-sorted DP route");
        assertTrue(hasReverseTopologicalBfsFromMaxima,
                filename + " must include the reverse topological BFS from local maxima route");
        assertTrue(hasExplicitStackPostorderDfs,
                filename + " must include the explicit-stack postorder DFS route");
    }

