    private static void assertPlusOneSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " should teach in-place carry, explicit carry propagation, trailing-nine suffix scan, "
                        + "sentinel result-array construction, and recursive carry propagation");

        boolean hasInPlaceCarry = false;
        boolean hasExplicitCarry = false;
        boolean hasTrailingNineSuffixScan = false;
        boolean hasSentinelResultArray = false;
        boolean hasRecursiveCarry = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String codeWithoutCommentsOrLiterals = stripJavaCommentsAndLiterals(code);
            String normalizedCode = normalizeCode(codeWithoutCommentsOrLiterals).toLowerCase(Locale.ROOT);

            hasInPlaceCarry = hasInPlaceCarry
                    || ((searchable.contains("in-place") || searchable.contains("right-to-left"))
                    && normalizedCode.contains("for(inti=digits.length-1;i>=0;i--)")
                    && normalizedCode.contains("if(digits[i]<9)")
                    && normalizedCode.contains("digits[i]++")
                    && normalizedCode.contains("returndigits")
                    && normalizedCode.contains("digits[i]=0")
                    && normalizedCode.contains("int[]result=newint[digits.length+1]")
                    && normalizedCode.contains("result[0]=1"));
            hasExplicitCarry = hasExplicitCarry
                    || ((searchable.contains("explicit") || searchable.contains("carry propagation"))
                    && normalizedCode.contains("intcarry=1")
                    && normalizedCode.contains("intsum=digits[i]+carry")
                    && normalizedCode.contains("digits[i]=sum%10")
                    && normalizedCode.contains("carry=sum/10")
                    && normalizedCode.contains("if(carry==0)")
                    && normalizedCode.contains("result[i+1]=digits[i]"));
            hasTrailingNineSuffixScan = hasTrailingNineSuffixScan
                    || ((searchable.contains("trailing") || searchable.contains("suffix"))
                    && normalizedCode.contains("intsplit=digits.length-1")
                    && normalizedCode.contains("while(split>=0&&digits[split]==9)")
                    && normalizedCode.contains("answer=digits.clone()")
                    && normalizedCode.contains("answer[split]++")
                    && normalizedCode.contains("answer[i]=0"));
            hasSentinelResultArray = hasSentinelResultArray
                    || ((searchable.contains("sentinel") || searchable.contains("result array"))
                    && normalizedCode.contains("int[]answer=newint[n+1]")
                    && normalizedCode.contains("answer[i+1]=sum%10")
                    && normalizedCode.contains("answer[0]=carry")
                    && (normalizedCode.contains("arrays.copyofrange(answer,1,answer.length)")
                    || normalizedCode.contains("java.util.arrays.copyofrange(answer,1,answer.length)")));
            hasRecursiveCarry = hasRecursiveCarry
                    || ((searchable.contains("recursive") || searchable.contains("recursion"))
                    && normalizedCode.contains("booleanoverflow=addone(digits,digits.length-1)")
                    && normalizedCode.contains("privatebooleanaddone(int[]digits,intindex)")
                    && normalizedCode.contains("if(index<0)")
                    && normalizedCode.contains("if(digits[index]<9)")
                    && normalizedCode.contains("digits[index]++")
                    && normalizedCode.contains("digits[index]=0")
                    && normalizedCode.contains("returnaddone(digits,index-1)"));
        }

        assertTrue(hasInPlaceCarry,
                filename + " must include the in-place right-to-left carry route");
        assertTrue(hasExplicitCarry,
                filename + " must include the explicit carry-propagation route");
        assertTrue(hasTrailingNineSuffixScan,
                filename + " must include the trailing-nine suffix-scan route");
        assertTrue(hasSentinelResultArray,
                filename + " must include the sentinel result-array route");
        assertTrue(hasRecursiveCarry,
                filename + " must include the recursive carry-propagation route");
    }

