    private static void assertPowXNSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " should teach low-to-high binary exponentiation, recursive half-power, binary powers "
                        + "table, high-to-low binary exponentiation, and explicit-stack divide and conquer");

        boolean hasRightToLeftBinary = false;
        boolean hasRecursiveHalfPower = false;
        boolean hasBinaryPowersTable = false;
        boolean hasLeftToRightBinary = false;
        boolean hasExplicitStackDivideConquer = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String codeWithoutCommentsOrLiterals = stripJavaCommentsAndLiterals(code);
            String normalizedCode = normalizeCode(codeWithoutCommentsOrLiterals).toLowerCase(Locale.ROOT);

            assertFalse(normalizedCode.contains("math.pow("),
                    filename + " Pow(x, n) reference solutions must implement exponentiation and must not call Math.pow");

            hasRightToLeftBinary = hasRightToLeftBinary
                    || ((searchable.contains("right-to-left") || searchable.contains("low bit"))
                    && normalizedCode.contains("longexponent=n")
                    && normalizedCode.contains("if(exponent<0)")
                    && normalizedCode.contains("x=1.0/x")
                    && normalizedCode.contains("exponent=-exponent")
                    && normalizedCode.contains("while(exponent>0)")
                    && normalizedCode.contains("(exponent&1l)==1l")
                    && normalizedCode.contains("answer*=x")
                    && normalizedCode.contains("x*=x")
                    && normalizedCode.contains("exponent>>=1"));
            hasRecursiveHalfPower = hasRecursiveHalfPower
                    || ((searchable.contains("recursive") || searchable.contains("half-power"))
                    && normalizedCode.contains("return1.0/power(x,-exponent)")
                    && normalizedCode.contains("returnpower(x,exponent)")
                    && normalizedCode.contains("privatedoublepower(doublebase,longexponent)")
                    && normalizedCode.contains("doublehalf=power(base,exponent/2)")
                    && normalizedCode.contains("doublesquared=half*half")
                    && normalizedCode.contains("returnexponent%2==0?squared:squared*base"));
            hasBinaryPowersTable = hasBinaryPowersTable
                    || ((searchable.contains("table") || searchable.contains("precompute"))
                    && normalizedCode.contains("list<double>powers=newarraylist<>()")
                    && normalizedCode.contains("powers.add(current)")
                    && normalizedCode.contains("current*=current")
                    && normalizedCode.contains("answer*=powers.get(bit)")
                    && normalizedCode.contains("returnnegative?1.0/answer:answer"));
            hasLeftToRightBinary = hasLeftToRightBinary
                    || ((searchable.contains("left-to-right") || searchable.contains("high-to-low"))
                    && normalizedCode.contains("long.numberofleadingzeros(exponent)")
                    && normalizedCode.contains("for(intbit=highestbit;bit>=0;bit--)")
                    && normalizedCode.contains("answer*=answer")
                    && normalizedCode.contains("((exponent>>bit)&1l)==1l")
                    && normalizedCode.contains("answer*=x")
                    && normalizedCode.contains("returnnegative?1.0/answer:answer"));
            hasExplicitStackDivideConquer = hasExplicitStackDivideConquer
                    || ((searchable.contains("stack") || searchable.contains("divide"))
                    && normalizedCode.contains("deque<long>stack=newarraydeque<>()")
                    && normalizedCode.contains("stack.push(exponent)")
                    && normalizedCode.contains("exponent/=2")
                    && normalizedCode.contains("while(!stack.isempty())")
                    && normalizedCode.contains("longvalue=stack.pop()")
                    && normalizedCode.contains("current*=current")
                    && normalizedCode.contains("returnnegative?1.0/current:current"));
        }

        assertTrue(hasRightToLeftBinary,
                filename + " must include the right-to-left binary exponentiation route");
        assertTrue(hasRecursiveHalfPower,
                filename + " must include the recursive half-power route");
        assertTrue(hasBinaryPowersTable,
                filename + " must include the binary powers-table route");
        assertTrue(hasLeftToRightBinary,
                filename + " must include the left-to-right binary exponentiation route");
        assertTrue(hasExplicitStackDivideConquer,
                filename + " must include the explicit-stack divide-and-conquer route");
    }

