    private static void assertDetectSquaresSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " should teach opposite-corner hashing, fixed grid lookup, column enumeration, "
                        + "row enumeration, and unique opposite-corner enumeration");

        boolean hasOppositeCornerHash = false;
        boolean hasFixedGrid = false;
        boolean hasColumnEnumeration = false;
        boolean hasRowEnumeration = false;
        boolean hasUniqueOppositeEnumeration = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String codeWithoutCommentsOrLiterals = stripJavaCommentsAndLiterals(code);
            String normalizedCode = normalizeCode(codeWithoutCommentsOrLiterals).toLowerCase(Locale.ROOT);

            hasOppositeCornerHash = hasOppositeCornerHash
                    || ((searchable.contains("opposite") || searchable.contains("diagonal"))
                    && normalizedCode.contains("map<long,integer>counts")
                    && normalizedCode.contains("list<int[]>points")
                    && normalizedCode.contains("points.add(newint[]{point[0],point[1]})")
                    && normalizedCode.contains("math.abs(px-x)!=math.abs(py-y)")
                    && normalizedCode.contains("counts.getordefault(key(px,y),0)*counts.getordefault(key(x,py),0)"));
            hasFixedGrid = hasFixedGrid
                    || ((searchable.contains("grid") || searchable.contains("coordinate"))
                    && normalizedCode.contains("int[][]grid=newint[1001][1001]")
                    && normalizedCode.contains("grid[point[0]][point[1]]++")
                    && normalizedCode.contains("list<int[]>points")
                    && normalizedCode.contains("grid[px][y]*grid[x][py]"));
            hasColumnEnumeration = hasColumnEnumeration
                    || ((searchable.contains("column") || searchable.contains("vertical"))
                    && normalizedCode.contains("map<integer,map<integer,integer>>columns")
                    && normalizedCode.contains("columns.computeifabsent(point[0]")
                    && normalizedCode.contains("map<integer,integer>samecolumn=columns.get(x)")
                    && normalizedCode.contains("answer+=verticalcount*countat(x+side,y)*countat(x+side,othery)")
                    && normalizedCode.contains("answer+=verticalcount*countat(x-side,y)*countat(x-side,othery)"));
            hasRowEnumeration = hasRowEnumeration
                    || ((searchable.contains("row") || searchable.contains("horizontal"))
                    && normalizedCode.contains("map<integer,map<integer,integer>>rows")
                    && normalizedCode.contains("rows.computeifabsent(point[1]")
                    && normalizedCode.contains("map<integer,integer>samerow=rows.get(y)")
                    && normalizedCode.contains("answer+=horizontalcount*countat(x,y+side)*countat(otherx,y+side)")
                    && normalizedCode.contains("answer+=horizontalcount*countat(x,y-side)*countat(otherx,y-side)"));
            hasUniqueOppositeEnumeration = hasUniqueOppositeEnumeration
                    || ((searchable.contains("unique") || searchable.contains("distinct"))
                    && normalizedCode.contains("set<long>uniquepoints")
                    && normalizedCode.contains("uniquepoints.add(encoded)")
                    && normalizedCode.contains("for(longencoded:uniquepoints)")
                    && normalizedCode.contains("intdiagonalcount=counts.get(encoded)")
                    && normalizedCode.contains("answer+=diagonalcount*counts.getordefault(key(px,y),0)*counts.getordefault(key(x,py),0)"));
        }

        assertTrue(hasOppositeCornerHash,
                filename + " must include the opposite-corner hash-map route");
        assertTrue(hasFixedGrid,
                filename + " must include the fixed-coordinate-grid route");
        assertTrue(hasColumnEnumeration,
                filename + " must include the column enumeration route");
        assertTrue(hasRowEnumeration,
                filename + " must include the row enumeration route");
        assertTrue(hasUniqueOppositeEnumeration,
                filename + " must include the unique opposite-corner enumeration route");
    }

