    private static void assertSingleNumberSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " should teach XOR pair cancellation, bit-count parity, HashSet toggling, "
                        + "frequency-map counting, and sorting with pair scan");

        boolean hasXorPairCancellation = false;
        boolean hasBitCountParity = false;
        boolean hasHashSetToggle = false;
        boolean hasFrequencyMap = false;
        boolean hasSortPairScan = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String codeWithoutCommentsOrLiterals = stripJavaCommentsAndLiterals(code);
            String normalizedCode = normalizeCode(codeWithoutCommentsOrLiterals).toLowerCase(Locale.ROOT);

            hasXorPairCancellation = hasXorPairCancellation
                    || ((searchable.contains("xor") || searchable.contains("pair cancellation"))
                    && normalizedCode.contains("intresult=0")
                    && normalizedCode.contains("for(intnum:nums)")
                    && normalizedCode.contains("result^=num")
                    && normalizedCode.contains("returnresult"));
            hasBitCountParity = hasBitCountParity
                    || ((searchable.contains("bit count") || searchable.contains("parity"))
                    && normalizedCode.contains("for(intbit=0;bit<32;bit++)")
                    && normalizedCode.contains("for(intnum:nums)")
                    && normalizedCode.contains("((num>>>bit)&1)==1")
                    && normalizedCode.contains("if((count&1)==1)")
                    && normalizedCode.contains("result|=(1<<bit)"));
            hasHashSetToggle = hasHashSetToggle
                    || ((searchable.contains("hashset") || searchable.contains("toggle"))
                    && normalizedCode.contains("set<integer>pending=newhashset<>()")
                    && normalizedCode.contains("if(!pending.add(num))")
                    && normalizedCode.contains("pending.remove(num)")
                    && normalizedCode.contains("returnpending.iterator().next()"));
            hasFrequencyMap = hasFrequencyMap
                    || ((searchable.contains("frequency") || searchable.contains("count"))
                    && normalizedCode.contains("map<integer,integer>frequencies=newhashmap<>()")
                    && normalizedCode.contains("frequencies.merge(num,1,integer::sum)")
                    && normalizedCode.contains("entry.getvalue()==1")
                    && normalizedCode.contains("returnentry.getkey()"));
            hasSortPairScan = hasSortPairScan
                    || ((searchable.contains("sort") || searchable.contains("pair scan"))
                    && normalizedCode.contains("arrays.sort(nums)")
                    && normalizedCode.contains("for(inti=0;i<nums.length-1;i+=2)")
                    && normalizedCode.contains("nums[i]!=nums[i+1]")
                    && normalizedCode.contains("returnnums[nums.length-1]"));
        }

        assertTrue(hasXorPairCancellation,
                filename + " must include the XOR pair-cancellation route");
        assertTrue(hasBitCountParity,
                filename + " must include the bit-count parity route");
        assertTrue(hasHashSetToggle,
                filename + " must include the HashSet toggle route");
        assertTrue(hasFrequencyMap,
                filename + " must include the frequency-map counting route");
        assertTrue(hasSortPairScan,
                filename + " must include the sorting pair-scan route");
    }

