    private static void assertNumberOf1BitsSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " should teach Brian Kernighan clearing, unsigned right-shift scan, moving mask scan, "
                        + "byte lookup table, and SWAR parallel bit count routes");

        boolean hasBrianKernighan = false;
        boolean hasUnsignedShiftScan = false;
        boolean hasMovingMask = false;
        boolean hasByteLookup = false;
        boolean hasSwar = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String codeWithoutCommentsOrLiterals = stripJavaCommentsAndLiterals(code);
            String normalizedCode = normalizeCode(codeWithoutCommentsOrLiterals).toLowerCase(Locale.ROOT);

            assertFalse(normalizedCode.contains("integer.bitcount("),
                    filename + " Number of 1 Bits reference solutions must implement bit counting and must not call Integer.bitCount");

            hasBrianKernighan = hasBrianKernighan
                    || ((searchable.contains("brian") || searchable.contains("kernighan")
                    || searchable.contains("lowest-bit"))
                    && normalizedCode.contains("while(n!=0)")
                    && normalizedCode.contains("n&=(n-1)")
                    && normalizedCode.contains("count++"));
            hasUnsignedShiftScan = hasUnsignedShiftScan
                    || ((searchable.contains("unsigned") || searchable.contains("right-shift"))
                    && normalizedCode.contains("for(inti=0;i<32;i++)")
                    && normalizedCode.contains("count+=n&1")
                    && normalizedCode.contains("n>>>=1"));
            hasMovingMask = hasMovingMask
                    || ((searchable.contains("mask") || searchable.contains("moving"))
                    && normalizedCode.contains("intmask=1")
                    && normalizedCode.contains("(n&mask)!=0")
                    && normalizedCode.contains("mask<<=1"));
            hasByteLookup = hasByteLookup
                    || ((searchable.contains("byte") || searchable.contains("lookup"))
                    && normalizedCode.contains("int[]byte_counts=buildtable()")
                    && normalizedCode.contains("int[]counts=newint[256]")
                    && normalizedCode.contains("counts[i]=counts[i>>1]+(i&1)")
                    && normalizedCode.contains("byte_counts[(n>>>24)&0xff]"));
            hasSwar = hasSwar
                    || (searchable.contains("swar")
                    && normalizedCode.contains("n=n-((n>>>1)&0x55555555)")
                    && normalizedCode.contains("(n&0x33333333)+((n>>>2)&0x33333333)")
                    && normalizedCode.contains("(n+(n>>>4))&0x0f0f0f0f")
                    && normalizedCode.contains("returnn&0x3f"));
        }

        assertTrue(hasBrianKernighan,
                filename + " must include the Brian Kernighan lowest-bit-clearing route");
        assertTrue(hasUnsignedShiftScan,
                filename + " must include the unsigned right-shift scan route");
        assertTrue(hasMovingMask,
                filename + " must include the moving-mask scan route");
        assertTrue(hasByteLookup,
                filename + " must include the byte lookup table route");
        assertTrue(hasSwar,
                filename + " must include the SWAR parallel bit count route");
    }

