    private static void assertReverseBitsSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " should teach bit-by-bit accumulation, mask-swap divide and conquer, byte lookup, "
                        + "opposite-mask assembly, and recursive half reversal routes");

        boolean hasBitByBitAccumulator = false;
        boolean hasMaskSwap = false;
        boolean hasByteLookup = false;
        boolean hasOppositeMask = false;
        boolean hasRecursiveHalf = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String codeWithoutCommentsOrLiterals = stripJavaCommentsAndLiterals(code);
            String normalizedCode = normalizeCode(codeWithoutCommentsOrLiterals).toLowerCase(Locale.ROOT);

            assertFalse(normalizedCode.contains("integer.reverse("),
                    filename + " Reverse Bits reference solutions must teach bit reversal and must not call Integer.reverse");

            hasBitByBitAccumulator = hasBitByBitAccumulator
                    || ((searchable.contains("bit-by-bit") || searchable.contains("accumulator"))
                    && normalizedCode.contains("for(inti=0;i<32;i++)")
                    && normalizedCode.contains("result=(result<<1)|(n&1)")
                    && normalizedCode.contains("n>>>=1"));
            hasMaskSwap = hasMaskSwap
                    || ((searchable.contains("mask") || searchable.contains("divide"))
                    && normalizedCode.contains("0x55555555")
                    && normalizedCode.contains("0x33333333")
                    && normalizedCode.contains("0x0f0f0f0f")
                    && normalizedCode.contains("0x00ff00ff")
                    && normalizedCode.contains("n=(n<<16)|(n>>>16)"));
            hasByteLookup = hasByteLookup
                    || ((searchable.contains("byte") || searchable.contains("lookup"))
                    && normalizedCode.contains("int[]byte_reverse=buildtable()")
                    && normalizedCode.contains("int[]table=newint[256]")
                    && normalizedCode.contains("byte_reverse[(n>>>24)&0xff]"));
            hasOppositeMask = hasOppositeMask
                    || ((searchable.contains("opposite") || searchable.contains("mask assembly"))
                    && normalizedCode.contains("intsourcemask=1")
                    && normalizedCode.contains("inttargetmask=1<<31")
                    && normalizedCode.contains("(n&sourcemask)!=0")
                    && normalizedCode.contains("result|=targetmask")
                    && normalizedCode.contains("targetmask>>>=1"));
            hasRecursiveHalf = hasRecursiveHalf
                    || ((searchable.contains("recursive") || searchable.contains("half reversal"))
                    && normalizedCode.contains("returnreverse(n,32)")
                    && normalizedCode.contains("inthalf=width>>>1")
                    && normalizedCode.contains("intmask=(1<<half)-1")
                    && normalizedCode.contains("return(reverse(low,half)<<half)|reverse(high,half)"));
        }

        assertTrue(hasBitByBitAccumulator,
                filename + " must include the bit-by-bit shift-accumulator route");
        assertTrue(hasMaskSwap,
                filename + " must include the mask-swap divide-and-conquer route");
        assertTrue(hasByteLookup,
                filename + " must include the byte lookup table route");
        assertTrue(hasOppositeMask,
                filename + " must include the opposite-mask assembly route");
        assertTrue(hasRecursiveHalf,
                filename + " must include the recursive half-reversal route");
    }

