    private static void assertSumOfTwoIntegersSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " should teach iterative half-adder, recursive half-adder, bitwise full adder, "
                        + "parallel prefix carry lookahead, and increment/decrement transfer routes");

        boolean hasIterativeHalfAdder = false;
        boolean hasRecursiveHalfAdder = false;
        boolean hasFullAdder = false;
        boolean hasParallelPrefix = false;
        boolean hasIncrementDecrementTransfer = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String codeWithoutCommentsOrLiterals = stripJavaCommentsAndLiterals(code);
            String normalizedCode = normalizeCode(codeWithoutCommentsOrLiterals).toLowerCase(Locale.ROOT);

            assertFalse(codeWithoutCommentsOrLiterals.contains("+") || codeWithoutCommentsOrLiterals.contains("-"),
                    filename + " Sum of Two Integers reference solutions must not use + or - operators");

            hasIterativeHalfAdder = hasIterativeHalfAdder
                    || ((searchable.contains("iterative") || searchable.contains("loop"))
                    && searchable.contains("half-adder")
                    && normalizedCode.contains("while(b!=0)")
                    && normalizedCode.contains("intcarry=(a&b)<<1")
                    && normalizedCode.contains("a=a^b")
                    && normalizedCode.contains("b=carry"));
            hasRecursiveHalfAdder = hasRecursiveHalfAdder
                    || (searchable.contains("recursive")
                    && searchable.contains("half-adder")
                    && normalizedCode.contains("if(b==0)")
                    && normalizedCode.contains("returngetsum(a^b,(a&b)<<1)"));
            hasFullAdder = hasFullAdder
                    || (searchable.contains("full adder")
                    && normalizedCode.contains("booleancarry=false")
                    && normalizedCode.contains("booleansumbit=bita^bitb^carry")
                    && normalizedCode.contains("carry=(bita&&bitb)||(bita&&carry)||(bitb&&carry)"));
            hasParallelPrefix = hasParallelPrefix
                    || ((searchable.contains("parallel prefix") || searchable.contains("lookahead"))
                    && normalizedCode.contains("intpartial=a^b")
                    && normalizedCode.contains("intpropagate=partial")
                    && normalizedCode.contains("intgenerate=a&b")
                    && normalizedCode.contains("for(intshift=1;shift<32;shift<<=1)")
                    && normalizedCode.contains("generate|=propagate&(generate<<shift)")
                    && normalizedCode.contains("propagate&=propagate<<shift")
                    && normalizedCode.contains("returnpartial^(generate<<1)"));
            hasIncrementDecrementTransfer = hasIncrementDecrementTransfer
                    || ((searchable.contains("increment") || searchable.contains("decrement")
                    || searchable.contains("transfer"))
                    && normalizedCode.contains("while(b>0)")
                    && normalizedCode.contains("a=increment(a)")
                    && normalizedCode.contains("b=decrement(b)")
                    && normalizedCode.contains("while(b<0)")
                    && normalizedCode.contains("a=decrement(a)")
                    && normalizedCode.contains("b=increment(b)")
                    && normalizedCode.contains("mask!=0&&(value&mask)!=0")
                    && normalizedCode.contains("mask!=0&&(value&mask)==0"));
        }

        assertTrue(hasIterativeHalfAdder,
                filename + " must include the iterative half-adder carry-loop route");
        assertTrue(hasRecursiveHalfAdder,
                filename + " must include the recursive half-adder recurrence route");
        assertTrue(hasFullAdder,
                filename + " must include the bitwise full-adder route");
        assertTrue(hasParallelPrefix,
                filename + " must include the parallel prefix carry-lookahead route");
        assertTrue(hasIncrementDecrementTransfer,
                filename + " must include the increment/decrement transfer baseline route");
    }

