    private static void assertReverseIntegerSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " should teach threshold guard, negative accumulator, string boundary comparison, "
                        + "digit-buffer boundary comparison, and post-update inverse check routes");

        boolean hasThresholdGuard = false;
        boolean hasNegativeAccumulator = false;
        boolean hasStringBoundaryComparison = false;
        boolean hasDigitBufferComparison = false;
        boolean hasPostUpdateInverseCheck = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String codeWithoutCommentsOrLiterals = stripJavaCommentsAndLiterals(code);
            String codeWords = codeWithoutCommentsOrLiterals.toLowerCase(Locale.ROOT);
            String normalizedCode = normalizeCode(codeWithoutCommentsOrLiterals).toLowerCase(Locale.ROOT);

            assertFalse(Pattern.compile("\\blong\\b").matcher(codeWords).find()
                            || codeWords.contains("parselong")
                            || codeWords.contains("biginteger"),
                    filename + " Reverse Integer reference solutions must not store or parse the reversed value "
                            + "with 64-bit or arbitrary-precision helpers");

            hasThresholdGuard = hasThresholdGuard
                    || ((searchable.contains("threshold") || searchable.contains("guard"))
                    && normalizedCode.contains("result>integer.max_value/10")
                    && normalizedCode.contains("result==integer.max_value/10&&digit>7")
                    && normalizedCode.contains("result<integer.min_value/10")
                    && normalizedCode.contains("result==integer.min_value/10&&digit<-8")
                    && normalizedCode.contains("result=result*10+digit"));
            hasNegativeAccumulator = hasNegativeAccumulator
                    || (searchable.contains("negative")
                    && normalizedCode.contains("x=-x")
                    && normalizedCode.contains("result<(integer.min_value-digit)/10")
                    && normalizedCode.contains("result=result*10+digit")
                    && normalizedCode.contains("return-result"));
            hasStringBoundaryComparison = hasStringBoundaryComparison
                    || ((searchable.contains("string") || searchable.contains("lexicographic"))
                    && normalizedCode.contains("newstringbuilder(digits).reverse().tostring()")
                    && normalizedCode.contains("reversed=reversed.substring(first)")
                    && normalizedCode.contains("reversed.compareto(limit)>0")
                    && normalizedCode.contains("result=negative?result*10-digit:result*10+digit"));
            hasDigitBufferComparison = hasDigitBufferComparison
                    || ((searchable.contains("digit buffer") || searchable.contains("boundary comparison"))
                    && normalizedCode.contains("int[]digits=newint[10]")
                    && normalizedCode.contains("math.abs(value%10)")
                    && normalizedCode.contains("int[]limit=negative?")
                    && normalizedCode.contains("digits[start+offset]")
                    && normalizedCode.contains("digit>limit[offset]"));
            hasPostUpdateInverseCheck = hasPostUpdateInverseCheck
                    || ((searchable.contains("inverse") || searchable.contains("post-update"))
                    && normalizedCode.contains("intnext=result*10+digit")
                    && normalizedCode.contains("if(next/10!=result)")
                    && normalizedCode.contains("result=next"));
        }

        assertTrue(hasThresholdGuard,
                filename + " must include the digit-pop threshold guard route");
        assertTrue(hasNegativeAccumulator,
                filename + " must include the negative accumulator boundary-guard route");
        assertTrue(hasStringBoundaryComparison,
                filename + " must include the string lexicographic boundary comparison route");
        assertTrue(hasDigitBufferComparison,
                filename + " must include the digit-buffer boundary comparison route");
        assertTrue(hasPostUpdateInverseCheck,
                filename + " must include the post-update inverse overflow-check route");
    }

