    private static void assertRomanToIntegerSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " should teach left-to-right lookahead, right-to-left previous maximum, "
                        + "previous-symbol correction, explicit subtractive-pair scanning, and normalization routes");

        boolean hasLeftToRightLookahead = false;
        boolean hasRightToLeftPrevious = false;
        boolean hasPreviousCorrection = false;
        boolean hasExplicitPairs = false;
        boolean hasNormalization = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String codeWithoutCommentsOrLiterals = stripJavaCommentsAndLiterals(code);
            String normalizedCode = normalizeCode(codeWithoutCommentsOrLiterals).toLowerCase(Locale.ROOT);
            String normalizedOriginalCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasLeftToRightLookahead = hasLeftToRightLookahead
                    || ((searchable.contains("lookahead") || searchable.contains("left-to-right"))
                    && normalizedCode.contains("i+1<s.length()")
                    && normalizedCode.contains("current<valueof(s.charat(i+1))")
                    && normalizedCode.contains("result-=current")
                    && normalizedCode.contains("result+=current"));
            hasRightToLeftPrevious = hasRightToLeftPrevious
                    || ((searchable.contains("right-to-left") || searchable.contains("previous maximum"))
                    && normalizedCode.contains("for(inti=s.length()-1;i>=0;i--)")
                    && normalizedCode.contains("if(current<previous)")
                    && normalizedCode.contains("result-=current")
                    && normalizedCode.contains("previous=current"));
            hasPreviousCorrection = hasPreviousCorrection
                    || ((searchable.contains("correction") || searchable.contains("previous-symbol"))
                    && normalizedCode.contains("total+=current")
                    && normalizedCode.contains("if(previous<current)")
                    && normalizedCode.contains("total-=2*previous")
                    && normalizedCode.contains("previous=current"));
            hasExplicitPairs = hasExplicitPairs
                    || ((searchable.contains("explicit") || searchable.contains("subtractive pair"))
                    && normalizedCode.contains("stringpair=s.substring(i,i+2)")
                    && normalizedOriginalCode.contains("pair.equals(\"iv\")")
                    && normalizedOriginalCode.contains("pair.equals(\"ix\")")
                    && normalizedOriginalCode.contains("pair.equals(\"xl\")")
                    && normalizedOriginalCode.contains("pair.equals(\"xc\")")
                    && normalizedOriginalCode.contains("pair.equals(\"cd\")")
                    && normalizedOriginalCode.contains("pair.equals(\"cm\")"));
            hasNormalization = hasNormalization
                    || ((searchable.contains("normalize") || searchable.contains("normalization"))
                    && normalizedOriginalCode.contains(".replace(\"cm\",\"dcccc\")")
                    && normalizedOriginalCode.contains(".replace(\"cd\",\"cccc\")")
                    && normalizedOriginalCode.contains(".replace(\"xc\",\"lxxxx\")")
                    && normalizedOriginalCode.contains(".replace(\"xl\",\"xxxx\")")
                    && normalizedOriginalCode.contains(".replace(\"ix\",\"viiii\")")
                    && normalizedOriginalCode.contains(".replace(\"iv\",\"iiii\")")
                    && normalizedCode.contains("total+=valueof(s.charat(i))"));
        }

        assertTrue(hasLeftToRightLookahead,
                filename + " must include the left-to-right lookahead route");
        assertTrue(hasRightToLeftPrevious,
                filename + " must include the right-to-left previous-maximum route");
        assertTrue(hasPreviousCorrection,
                filename + " must include the previous-symbol correction route");
        assertTrue(hasExplicitPairs,
                filename + " must include the explicit six subtractive-pair scan route");
        assertTrue(hasNormalization,
                filename + " must include the subtractive-form normalization route");
    }

