    private static void assertLongestCommonPrefixSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " should teach horizontal shrinking, vertical scanning, divide-and-conquer merging, "
                        + "binary search on prefix length, and trie single-branch walking");

        boolean hasHorizontalShrinking = false;
        boolean hasVerticalScan = false;
        boolean hasDivideAndConquer = false;
        boolean hasBinarySearch = false;
        boolean hasTrieWalk = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String codeWithoutCommentsOrLiterals = stripJavaCommentsAndLiterals(code);
            String normalizedCode = normalizeCode(codeWithoutCommentsOrLiterals).toLowerCase(Locale.ROOT);

            hasHorizontalShrinking = hasHorizontalShrinking
                    || ((searchable.contains("horizontal") || searchable.contains("shrinking"))
                    && normalizedCode.contains("while(!strs[i].startswith(prefix))")
                    && normalizedCode.contains("prefix=prefix.substring(0,prefix.length()-1)")
                    && normalizedCode.contains("prefix.isempty()"));
            hasVerticalScan = hasVerticalScan
                    || ((searchable.contains("vertical") || searchable.contains("character scan"))
                    && normalizedCode.contains("charexpected=first.charat(i)")
                    && normalizedCode.contains("i==strs[j].length()||strs[j].charat(i)!=expected")
                    && normalizedCode.contains("returnfirst.substring(0,i)"));
            hasDivideAndConquer = hasDivideAndConquer
                    || ((searchable.contains("divide") || searchable.contains("conquer"))
                    && normalizedCode.contains("intmid=left+(right-left)/2")
                    && normalizedCode.contains("longestcommonprefix(strs,left,mid)")
                    && normalizedCode.contains("longestcommonprefix(strs,mid+1,right)")
                    && normalizedCode.contains("returncommonprefix(leftprefix,rightprefix)"));
            hasBinarySearch = hasBinarySearch
                    || ((searchable.contains("binary") || searchable.contains("monotonic"))
                    && normalizedCode.contains("intmid=low+(high-low+1)/2")
                    && normalizedCode.contains("if(iscommonprefix(strs,mid))")
                    && normalizedCode.contains("high=mid-1")
                    && normalizedCode.contains("returnstrs[0].substring(0,low)"));
            hasTrieWalk = hasTrieWalk
                    || ((searchable.contains("trie") || searchable.contains("single-branch"))
                    && normalizedCode.contains("node[]children=newnode[26]")
                    && normalizedCode.contains("intchildcount")
                    && normalizedCode.contains("booleanterminal")
                    && normalizedCode.contains("while(node.childcount==1&&!node.terminal)")
                    && normalizedCode.contains("node.children[index]=newnode()")
                    && normalizedCode.contains("node.childcount++"));
        }

        assertTrue(hasHorizontalShrinking,
                filename + " must include the horizontal prefix-shrinking route");
        assertTrue(hasVerticalScan,
                filename + " must include the vertical character-scan route");
        assertTrue(hasDivideAndConquer,
                filename + " must include the divide-and-conquer merge route");
        assertTrue(hasBinarySearch,
                filename + " must include the binary-search-on-prefix-length route");
        assertTrue(hasTrieWalk,
                filename + " must include the trie single-branch walk route");
    }

