    private static void assertMaximumWidthRampSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " should teach monotonic candidate stack, prefix-min/suffix-max two pointers, "
                        + "sorted-index sweep, binary search on answer width, and brute-force pair enumeration");

        boolean hasMonotonicStack = false;
        boolean hasPrefixSuffixTwoPointers = false;
        boolean hasSortedSweep = false;
        boolean hasBinarySearchWidth = false;
        boolean hasBruteForce = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String codeWithoutCommentsOrLiterals = stripJavaCommentsAndLiterals(code);
            String normalizedCode = normalizeCode(codeWithoutCommentsOrLiterals).toLowerCase(Locale.ROOT);

            hasMonotonicStack = hasMonotonicStack
                    || ((searchable.contains("monotonic") || searchable.contains("stack"))
                    && normalizedCode.contains("deque<integer>stack=newarraydeque<>()")
                    && normalizedCode.contains("nums[i]<nums[stack.peek()]")
                    && normalizedCode.contains("for(intj=nums.length-1;j>=0;j--)")
                    && normalizedCode.contains("while(!stack.isempty()&&nums[stack.peek()]<=nums[j])")
                    && normalizedCode.contains("j-stack.pop()"));
            hasPrefixSuffixTwoPointers = hasPrefixSuffixTwoPointers
                    || ((searchable.contains("prefix") || searchable.contains("suffix") || searchable.contains("two pointer"))
                    && normalizedCode.contains("int[]leftmin=newint[n]")
                    && normalizedCode.contains("int[]rightmax=newint[n]")
                    && normalizedCode.contains("leftmin[i]=math.min(leftmin[i-1],nums[i])")
                    && normalizedCode.contains("rightmax[j]=math.max(rightmax[j+1],nums[j])")
                    && normalizedCode.contains("if(leftmin[i]<=rightmax[j])")
                    && normalizedCode.contains("j++")
                    && normalizedCode.contains("i++"));
            hasSortedSweep = hasSortedSweep
                    || ((searchable.contains("sorted") || searchable.contains("value order"))
                    && normalizedCode.contains("integer[]order=newinteger[nums.length]")
                    && normalizedCode.contains("arrays.sort(order")
                    && normalizedCode.contains("integer.compare(nums[a],nums[b])")
                    && normalizedCode.contains("best=math.max(best,index-minindex)")
                    && normalizedCode.contains("minindex=math.min(minindex,index)"));
            hasBinarySearchWidth = hasBinarySearchWidth
                    || ((searchable.contains("binary") || searchable.contains("answer width"))
                    && normalizedCode.contains("intmid=low+(high-low+1)/2")
                    && normalizedCode.contains("if(hasrampatleast(nums,mid))")
                    && normalizedCode.contains("high=mid-1")
                    && normalizedCode.contains("booleanhasrampatleast(int[]nums,intwidth)")
                    && normalizedCode.contains("intminleft=nums[0]")
                    && normalizedCode.contains("minleft=math.min(minleft,nums[j-width])")
                    && normalizedCode.contains("if(minleft<=nums[j])"));
            hasBruteForce = hasBruteForce
                    || ((searchable.contains("brute") || searchable.contains("enumeration"))
                    && normalizedCode.contains("for(inti=0;i<nums.length;i++)")
                    && normalizedCode.contains("for(intj=i+1;j<nums.length;j++)")
                    && normalizedCode.contains("if(nums[i]<=nums[j])")
                    && normalizedCode.contains("best=math.max(best,j-i)"));
        }

        assertTrue(hasMonotonicStack,
                filename + " must include the monotonic candidate-stack route");
        assertTrue(hasPrefixSuffixTwoPointers,
                filename + " must include the prefix-min/suffix-max two-pointer route");
        assertTrue(hasSortedSweep,
                filename + " must include the sorted-index sweep route");
        assertTrue(hasBinarySearchWidth,
                filename + " must include the binary-search-on-answer-width route");
        assertTrue(hasBruteForce,
                filename + " must include the brute-force pair-enumeration route");
    }

