    private static void assertImplementStrStrSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " should teach KMP, sliding-window brute force, Rabin-Karp with verification, "
                        + "Z-algorithm matching, and Boyer-Moore-Horspool bad-character shifts");

        boolean hasKmp = false;
        boolean hasSlidingWindow = false;
        boolean hasRabinKarp = false;
        boolean hasZAlgorithm = false;
        boolean hasBoyerMooreHorspool = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String codeWithoutCommentsOrLiterals = stripJavaCommentsAndLiterals(code);
            String normalizedCode = normalizeCode(codeWithoutCommentsOrLiterals).toLowerCase(Locale.ROOT);

            hasKmp = hasKmp
                    || ((searchable.contains("kmp") || searchable.contains("prefix"))
                    && normalizedCode.contains("int[]lps=newint[n]")
                    && normalizedCode.contains("for(inti=1,len=0;i<n;)")
                    && normalizedCode.contains("len=lps[len-1]")
                    && normalizedCode.contains("for(inti=0,j=0;i<m;)")
                    && normalizedCode.contains("j=lps[j-1]")
                    && normalizedCode.contains("returni-n"));
            hasSlidingWindow = hasSlidingWindow
                    || ((searchable.contains("sliding") || searchable.contains("brute"))
                    && normalizedCode.contains("for(inti=0;i<=m-n;i++)")
                    && normalizedCode.contains("intj=0")
                    && normalizedCode.contains("while(j<n&&haystack.charat(i+j)==needle.charat(j))")
                    && normalizedCode.contains("if(j==n)")
                    && normalizedCode.contains("returni"));
            hasRabinKarp = hasRabinKarp
                    || ((searchable.contains("rabin") || searchable.contains("hash"))
                    && normalizedCode.contains("longneedlehash=0l")
                    && normalizedCode.contains("longwindowhash=0l")
                    && normalizedCode.contains("needlehash=(needlehash*base+needle.charat(i))%mod")
                    && normalizedCode.contains("windowhash=(windowhash-haystack.charat(start)*power)%mod")
                    && normalizedCode.contains("if(windowhash<0)")
                    && normalizedCode.contains("matchesat(haystack,needle,start)"));
            hasZAlgorithm = hasZAlgorithm
                    || ((searchable.contains("z-algorithm") || searchable.contains("z algorithm"))
                    && normalizedCode.contains("stringcombined=needle+\"\"+haystack")
                    && normalizedCode.contains("int[]z=newint[combined.length()]")
                    && normalizedCode.contains("intleft=0")
                    && normalizedCode.contains("intright=0")
                    && normalizedCode.contains("if(i<=right)")
                    && normalizedCode.contains("z[i]=math.min(right-i+1,z[i-left])")
                    && normalizedCode.contains("combined.charat(z[i])==combined.charat(i+z[i])")
                    && normalizedCode.contains("returni-n-1"));
            hasBoyerMooreHorspool = hasBoyerMooreHorspool
                    || ((searchable.contains("boyer") || searchable.contains("horspool"))
                    && normalizedCode.contains("int[]shift=newint[256]")
                    && normalizedCode.contains("arrays.fill(shift,n)")
                    && normalizedCode.contains("for(inti=0;i<n-1;i++)")
                    && normalizedCode.contains("shift[needle.charat(i)]=n-1-i")
                    && normalizedCode.contains("intstart=0")
                    && normalizedCode.contains("intj=n-1")
                    && normalizedCode.contains("while(j>=0&&haystack.charat(start+j)==needle.charat(j))")
                    && normalizedCode.contains("start+=shift[haystack.charat(start+n-1)]"));
        }

        assertTrue(hasKmp,
                filename + " must include the KMP prefix-function route");
        assertTrue(hasSlidingWindow,
                filename + " must include the sliding-window brute-force route");
        assertTrue(hasRabinKarp,
                filename + " must include the Rabin-Karp verified rolling-hash route");
        assertTrue(hasZAlgorithm,
                filename + " must include the Z-algorithm combined-string route");
        assertTrue(hasBoyerMooreHorspool,
                filename + " must include the Boyer-Moore-Horspool bad-character route");
    }

