    private static void assertPascalTriangleIISolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " should teach one-row backward DP, rolling previous row, coefficient recurrence, "
                        + "symmetric coefficient fill, and full-triangle construction");

        boolean hasOneRowBackwardDp = false;
        boolean hasRollingPreviousRow = false;
        boolean hasCoefficientRecurrence = false;
        boolean hasSymmetricCoefficientFill = false;
        boolean hasFullTriangle = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String codeWithoutCommentsOrLiterals = stripJavaCommentsAndLiterals(code);
            String normalizedCode = normalizeCode(codeWithoutCommentsOrLiterals).toLowerCase(Locale.ROOT);

            hasOneRowBackwardDp = hasOneRowBackwardDp
                    || ((searchable.contains("backward") || searchable.contains("one-row"))
                    && normalizedCode.contains("list<integer>row=newarraylist<>()")
                    && normalizedCode.contains("for(inti=0;i<=rowindex;i++)")
                    && normalizedCode.contains("row.add(1)")
                    && normalizedCode.contains("for(intj=i-1;j>0;j--)")
                    && normalizedCode.contains("row.set(j,row.get(j)+row.get(j-1))"));
            hasRollingPreviousRow = hasRollingPreviousRow
                    || ((searchable.contains("rolling") || searchable.contains("previous row"))
                    && normalizedCode.contains("list<integer>previous=newarraylist<>()")
                    && normalizedCode.contains("previous.add(1)")
                    && normalizedCode.contains("for(introw=1;row<=rowindex;row++)")
                    && normalizedCode.contains("list<integer>current=newarraylist<>()")
                    && normalizedCode.contains("current.add(previous.get(col-1)+previous.get(col))")
                    && normalizedCode.contains("previous=current"));
            hasCoefficientRecurrence = hasCoefficientRecurrence
                    || ((searchable.contains("coefficient") || searchable.contains("combinatorial"))
                    && normalizedCode.contains("longvalue=1")
                    && normalizedCode.contains("for(intk=0;k<=rowindex;k++)")
                    && normalizedCode.contains("row.add((int)value)")
                    && normalizedCode.contains("value=value*(rowindex-k)/(k+1)"));
            hasSymmetricCoefficientFill = hasSymmetricCoefficientFill
                    || (searchable.contains("symmetric")
                    && normalizedCode.contains("for(inti=0;i<=rowindex;i++)")
                    && normalizedCode.contains("row.add(0)")
                    && normalizedCode.contains("for(intk=0;k<=rowindex/2;k++)")
                    && normalizedCode.contains("row.set(k,coefficient)")
                    && normalizedCode.contains("row.set(rowindex-k,coefficient)")
                    && normalizedCode.contains("value=value*(rowindex-k)/(k+1)"));
            hasFullTriangle = hasFullTriangle
                    || ((searchable.contains("full triangle") || searchable.contains("definition"))
                    && normalizedCode.contains("list<list<integer>>triangle=newarraylist<>()")
                    && normalizedCode.contains("for(introw=0;row<=rowindex;row++)")
                    && normalizedCode.contains("if(col==0||col==row)")
                    && normalizedCode.contains("triangle.get(row-1).get(col-1)")
                    && normalizedCode.contains("triangle.get(row-1).get(col)")
                    && normalizedCode.contains("returntriangle.get(rowindex)"));
        }

        assertTrue(hasOneRowBackwardDp,
                filename + " must include the one-row backward-DP route");
        assertTrue(hasRollingPreviousRow,
                filename + " must include the rolling previous-row route");
        assertTrue(hasCoefficientRecurrence,
                filename + " must include the coefficient-recurrence route");
        assertTrue(hasSymmetricCoefficientFill,
                filename + " must include the symmetric coefficient-fill route");
        assertTrue(hasFullTriangle,
                filename + " must include the full-triangle construction route");
    }

