    private static void assertBestTimeStockIISolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " should teach positive-adjacent-gain greedy, valley-peak transaction scanning, "
                        + "cash/hold state-machine DP, explicit DP tables, and sentinel run compression");

        boolean hasPositiveAdjacentGainGreedy = false;
        boolean hasValleyPeakScan = false;
        boolean hasCashHoldStateMachine = false;
        boolean hasExplicitDpTable = false;
        boolean hasSentinelRunCompression = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String codeWithoutCommentsOrLiterals = stripJavaCommentsAndLiterals(code);
            String normalizedCode = normalizeCode(codeWithoutCommentsOrLiterals).toLowerCase(Locale.ROOT);

            hasPositiveAdjacentGainGreedy = hasPositiveAdjacentGainGreedy
                    || ((searchable.contains("positive") || searchable.contains("adjacent"))
                    && searchable.contains("gain")
                    && normalizedCode.contains("intprofit=0")
                    && normalizedCode.contains("for(inti=1;i<prices.length;i++)")
                    && normalizedCode.contains("if(prices[i]>prices[i-1])")
                    && normalizedCode.contains("profit+=prices[i]-prices[i-1]"));
            hasValleyPeakScan = hasValleyPeakScan
                    || (searchable.contains("valley")
                    && searchable.contains("peak")
                    && normalizedCode.contains("while(i<prices.length-1&&prices[i]>=prices[i+1])")
                    && normalizedCode.contains("intvalley=prices[i]")
                    && normalizedCode.contains("while(i<prices.length-1&&prices[i]<=prices[i+1])")
                    && normalizedCode.contains("intpeak=prices[i]")
                    && normalizedCode.contains("profit+=peak-valley"));
            hasCashHoldStateMachine = hasCashHoldStateMachine
                    || ((searchable.contains("state") || searchable.contains("cash"))
                    && searchable.contains("hold")
                    && normalizedCode.contains("intcash=0")
                    && normalizedCode.contains("inthold=-prices[0]")
                    && normalizedCode.contains("intprevcash=cash")
                    && normalizedCode.contains("cash=math.max(cash,hold+prices[i])")
                    && normalizedCode.contains("hold=math.max(hold,prevcash-prices[i])"));
            hasExplicitDpTable = hasExplicitDpTable
                    || ((searchable.contains("explicit") || searchable.contains("table"))
                    && normalizedCode.contains("int[]cash=newint[n]")
                    && normalizedCode.contains("int[]hold=newint[n]")
                    && normalizedCode.contains("hold[0]=-prices[0]")
                    && normalizedCode.contains("cash[i]=math.max(cash[i-1],hold[i-1]+prices[i])")
                    && normalizedCode.contains("hold[i]=math.max(hold[i-1],cash[i-1]-prices[i])")
                    && normalizedCode.contains("returncash[n-1]"));
            hasSentinelRunCompression = hasSentinelRunCompression
                    || ((searchable.contains("sentinel") || searchable.contains("run compression"))
                    && normalizedCode.contains("intbuy=prices[0]")
                    && normalizedCode.contains("for(inti=1;i<=prices.length;i++)")
                    && normalizedCode.contains("if(i==prices.length||prices[i]<prices[i-1])")
                    && normalizedCode.contains("profit+=math.max(0,prices[i-1]-buy)")
                    && normalizedCode.contains("buy=prices[i]"));
        }

        assertTrue(hasPositiveAdjacentGainGreedy,
                filename + " must include the positive-adjacent-gain greedy route");
        assertTrue(hasValleyPeakScan,
                filename + " must include the valley-peak transaction-scan route");
        assertTrue(hasCashHoldStateMachine,
                filename + " must include the cash/hold state-machine DP route");
        assertTrue(hasExplicitDpTable,
                filename + " must include the explicit DP-table route");
        assertTrue(hasSentinelRunCompression,
                filename + " must include the sentinel run-compression route");
    }

