    private static void assertExcelColumnTitleSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " should teach reverse-append one-offset conversion, recursive prefix conversion, "
                        + "stack reversal, fixed back-buffer filling, and exact-length back filling");

        boolean hasReverseAppend = false;
        boolean hasRecursivePrefix = false;
        boolean hasStackReversal = false;
        boolean hasFixedBackBuffer = false;
        boolean hasExactLengthBackFill = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String codeWithoutCommentsOrLiterals = stripJavaCommentsAndLiterals(code);
            String normalizedCode = normalizeCode(codeWithoutCommentsOrLiterals).toLowerCase(Locale.ROOT);

            hasReverseAppend = hasReverseAppend
                    || ((searchable.contains("reverse") || searchable.contains("append"))
                    && searchable.contains("one-offset")
                    && normalizedCode.contains("stringbuilderreversed=newstringbuilder()")
                    && normalizedCode.contains("columnnumber--")
                    && normalizedCode.contains("reversed.append((char)(''+columnnumber%26))")
                    && normalizedCode.contains("returnreversed.reverse().tostring()"));
            hasRecursivePrefix = hasRecursivePrefix
                    || ((searchable.contains("recursive") || searchable.contains("prefix"))
                    && normalizedCode.contains("if(columnnumber==0)")
                    && normalizedCode.contains("return\"\"")
                    && normalizedCode.contains("columnnumber--")
                    && normalizedCode.contains("returnconverttotitle(columnnumber/26)+(char)(''+columnnumber%26)"));
            hasStackReversal = hasStackReversal
                    || (searchable.contains("stack")
                    && normalizedCode.contains("deque<character>letters=newarraydeque<>()")
                    && normalizedCode.contains("letters.push((char)(''+columnnumber%26))")
                    && normalizedCode.contains("while(!letters.isempty())")
                    && normalizedCode.contains("result.append(letters.pop())"));
            hasFixedBackBuffer = hasFixedBackBuffer
                    || ((searchable.contains("fixed") || searchable.contains("buffer"))
                    && normalizedCode.contains("char[]buffer=newchar[16]")
                    && normalizedCode.contains("intwrite=buffer.length")
                    && normalizedCode.contains("buffer[--write]=(char)(''+columnnumber%26)")
                    && normalizedCode.contains("returnnewstring(buffer,write,buffer.length-write)"));
            hasExactLengthBackFill = hasExactLengthBackFill
                    || ((searchable.contains("exact") || searchable.contains("length"))
                    && normalizedCode.contains("intcopy=columnnumber")
                    && normalizedCode.contains("while(copy>0)")
                    && normalizedCode.contains("copy--")
                    && normalizedCode.contains("length++")
                    && normalizedCode.contains("char[]answer=newchar[length]")
                    && normalizedCode.contains("intwrite=length-1")
                    && normalizedCode.contains("answer[write--]=(char)(''+columnnumber%26)")
                    && normalizedCode.contains("returnnewstring(answer)"));
        }

        assertTrue(hasReverseAppend,
                filename + " must include the reverse-append one-offset conversion route");
        assertTrue(hasRecursivePrefix,
                filename + " must include the recursive prefix-conversion route");
        assertTrue(hasStackReversal,
                filename + " must include the stack-reversal route");
        assertTrue(hasFixedBackBuffer,
                filename + " must include the fixed back-buffer route");
        assertTrue(hasExactLengthBackFill,
                filename + " must include the exact-length back-fill route");
    }

