    private static void assertReverseStringSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " should teach temporary-variable two pointers, mirror-index iteration, XOR swap, "
                        + "printable ASCII arithmetic swap, and adjacent-pull baseline reversal");

        boolean hasTemporaryTwoPointer = false;
        boolean hasMirrorIndexLoop = false;
        boolean hasXorSwap = false;
        boolean hasArithmeticSwap = false;
        boolean hasAdjacentPullBaseline = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String codeWithoutCommentsOrLiterals = stripJavaCommentsAndLiterals(code);
            String normalizedCode = normalizeCode(codeWithoutCommentsOrLiterals).toLowerCase(Locale.ROOT);

            hasTemporaryTwoPointer = hasTemporaryTwoPointer
                    || ((searchable.contains("two-pointer") || searchable.contains("temporary"))
                    && normalizedCode.contains("intleft=0")
                    && normalizedCode.contains("intright=s.length-1")
                    && normalizedCode.contains("while(left<right)")
                    && normalizedCode.contains("chartemp=s[left]")
                    && normalizedCode.contains("s[left]=s[right]")
                    && normalizedCode.contains("s[right]=temp")
                    && normalizedCode.contains("left++")
                    && normalizedCode.contains("right--"));
            hasMirrorIndexLoop = hasMirrorIndexLoop
                    || ((searchable.contains("mirror") || searchable.contains("half"))
                    && normalizedCode.contains("intn=s.length")
                    && normalizedCode.contains("for(inti=0;i<n/2;i++)")
                    && normalizedCode.contains("intj=n-1-i")
                    && normalizedCode.contains("s[i]=s[j]")
                    && normalizedCode.contains("s[j]=temp"));
            hasXorSwap = hasXorSwap
                    || ((searchable.contains("xor") || searchable.contains("bit"))
                    && normalizedCode.contains("s[left]=(char)(s[left]^s[right])")
                    && normalizedCode.contains("s[right]=(char)(s[left]^s[right])"));
            hasArithmeticSwap = hasArithmeticSwap
                    || ((searchable.contains("arithmetic") || searchable.contains("ascii"))
                    && normalizedCode.contains("s[left]=(char)(s[left]+s[right])")
                    && normalizedCode.contains("s[right]=(char)(s[left]-s[right])"));
            hasAdjacentPullBaseline = hasAdjacentPullBaseline
                    || ((searchable.contains("adjacent") || searchable.contains("baseline"))
                    && normalizedCode.contains("for(intend=s.length-1;end>0;end--)")
                    && normalizedCode.contains("for(inti=0;i<end;i++)")
                    && normalizedCode.contains("s[i]=s[i+1]")
                    && normalizedCode.contains("s[i+1]=temp"));
        }

        assertTrue(hasTemporaryTwoPointer,
                filename + " must include the temporary-variable two-pointer route");
        assertTrue(hasMirrorIndexLoop,
                filename + " must include the mirror-index loop route");
        assertTrue(hasXorSwap,
                filename + " must include the XOR swap route");
        assertTrue(hasArithmeticSwap,
                filename + " must include the printable ASCII arithmetic-swap route");
        assertTrue(hasAdjacentPullBaseline,
                filename + " must include the adjacent-pull baseline route");
    }

