    private static void assertIntersectionTwoArraysSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " should teach HashSet membership scanning, sorted two-pointer merge, "
                        + "sorted-array binary search, fixed-domain boolean presence maps, and BitSet set algebra");

        boolean hasHashSetMembership = false;
        boolean hasSortedTwoPointers = false;
        boolean hasBinarySearch = false;
        boolean hasBooleanPresenceMap = false;
        boolean hasBitSetAlgebra = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String codeWithoutCommentsOrLiterals = stripJavaCommentsAndLiterals(code);
            String normalizedCode = normalizeCode(codeWithoutCommentsOrLiterals).toLowerCase(Locale.ROOT);

            hasHashSetMembership = hasHashSetMembership
                    || ((searchable.contains("hashset") || searchable.contains("hash set"))
                    && normalizedCode.contains("set<integer>seen=newhashset<>()")
                    && normalizedCode.contains("seen.add(value)")
                    && normalizedCode.contains("set<integer>intersection=newhashset<>()")
                    && normalizedCode.contains("if(seen.contains(value))")
                    && normalizedCode.contains("intersection.add(value)"));
            hasSortedTwoPointers = hasSortedTwoPointers
                    || ((searchable.contains("sorted") || searchable.contains("two-pointer"))
                    && normalizedCode.contains("arrays.sort(nums1)")
                    && normalizedCode.contains("arrays.sort(nums2)")
                    && normalizedCode.contains("while(i<nums1.length&&j<nums2.length)")
                    && normalizedCode.contains("if(nums1[i]<nums2[j])")
                    && normalizedCode.contains("elseif(nums1[i]>nums2[j])")
                    && normalizedCode.contains("result.add(nums1[i])"));
            hasBinarySearch = hasBinarySearch
                    || ((searchable.contains("binary") || searchable.contains("search"))
                    && normalizedCode.contains("arrays.sort(nums2)")
                    && normalizedCode.contains("arrays.binarysearch(nums2,value)>=0")
                    && normalizedCode.contains("set<integer>result=newhashset<>()")
                    && normalizedCode.contains("result.add(value)"));
            hasBooleanPresenceMap = hasBooleanPresenceMap
                    || ((searchable.contains("boolean") || searchable.contains("fixed domain"))
                    && normalizedCode.contains("boolean[]infirst=newboolean[1001]")
                    && normalizedCode.contains("infirst[value]=true")
                    && normalizedCode.contains("boolean[]inboth=newboolean[1001]")
                    && normalizedCode.contains("if(infirst[value])")
                    && normalizedCode.contains("inboth[value]=true")
                    && normalizedCode.contains("for(intvalue=0;value<inboth.length;value++)"));
            hasBitSetAlgebra = hasBitSetAlgebra
                    || ((searchable.contains("bitset") || searchable.contains("set algebra"))
                    && normalizedCode.contains("bitsetfirst=newbitset(1001)")
                    && normalizedCode.contains("bitsetsecond=newbitset(1001)")
                    && normalizedCode.contains("first.set(value)")
                    && normalizedCode.contains("second.set(value)")
                    && normalizedCode.contains("second.and(first)")
                    && normalizedCode.contains("second.cardinality()")
                    && normalizedCode.contains("second.nextsetbit(0)"));
        }

        assertTrue(hasHashSetMembership,
                filename + " must include the HashSet membership-scan route");
        assertTrue(hasSortedTwoPointers,
                filename + " must include the sorted two-pointer merge route");
        assertTrue(hasBinarySearch,
                filename + " must include the sorted-array binary-search route");
        assertTrue(hasBooleanPresenceMap,
                filename + " must include the fixed-domain boolean presence-map route");
        assertTrue(hasBitSetAlgebra,
                filename + " must include the BitSet set-algebra route");
    }

