    private static void assertFirstUniqueCharacterSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " should teach frequency-array two-pass scanning, alphabet first-last occurrence sweeping, "
                        + "LinkedHashMap insertion-order counting, candidate-index queues, and active unique linked lists");

        boolean hasFrequencyArray = false;
        boolean hasFirstLastOccurrence = false;
        boolean hasLinkedHashMap = false;
        boolean hasCandidateQueue = false;
        boolean hasActiveUniqueList = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String codeWithoutCommentsOrLiterals = stripJavaCommentsAndLiterals(code);
            String normalizedCode = normalizeCode(codeWithoutCommentsOrLiterals).toLowerCase(Locale.ROOT);

            hasFrequencyArray = hasFrequencyArray
                    || ((searchable.contains("frequency") || searchable.contains("two-pass"))
                    && normalizedCode.contains("int[]freq=newint[26]")
                    && normalizedCode.contains("freq[s.charat(i)-'']++")
                    && normalizedCode.contains("if(freq[s.charat(i)-'']==1)")
                    && normalizedCode.contains("returni"));
            hasFirstLastOccurrence = hasFirstLastOccurrence
                    || ((searchable.contains("first-last") || searchable.contains("occurrence"))
                    && normalizedCode.contains("intanswer=s.length()")
                    && normalizedCode.contains("intfirst=s.indexof(c)")
                    && normalizedCode.contains("first==s.lastindexof(c)")
                    && normalizedCode.contains("answer=math.min(answer,first)")
                    && normalizedCode.contains("returnanswer==s.length()?-1:answer"));
            hasLinkedHashMap = hasLinkedHashMap
                    || ((searchable.contains("linkedhashmap") || searchable.contains("insertion order"))
                    && normalizedCode.contains("map<character,stat>stats=newlinkedhashmap<>()")
                    && normalizedCode.contains("statstat=stats.get(c)")
                    && normalizedCode.contains("stats.put(c,newstat(i))")
                    && normalizedCode.contains("stat.count++")
                    && normalizedCode.contains("for(statstat:stats.values())")
                    && normalizedCode.contains("returnstat.firstindex"));
            hasCandidateQueue = hasCandidateQueue
                    || ((searchable.contains("queue") || searchable.contains("candidate"))
                    && normalizedCode.contains("queue<integer>candidates=newarraydeque<>()")
                    && normalizedCode.contains("freq[letter]++")
                    && normalizedCode.contains("candidates.offer(i)")
                    && normalizedCode.contains("while(!candidates.isempty()")
                    && normalizedCode.contains("candidates.poll()")
                    && normalizedCode.contains("returncandidates.isempty()?-1:candidates.peek()"));
            hasActiveUniqueList = hasActiveUniqueList
                    || ((searchable.contains("linked list") || searchable.contains("active unique"))
                    && normalizedCode.contains("node[]active=newnode[26]")
                    && normalizedCode.contains("boolean[]repeated=newboolean[26]")
                    && normalizedCode.contains("appendbeforetail(tail,node)")
                    && normalizedCode.contains("remove(active[letter])")
                    && normalizedCode.contains("returnhead.next==tail?-1:head.next.index")
                    && normalizedCode.contains("privatestaticclassnode"));
        }

        assertTrue(hasFrequencyArray,
                filename + " must include the frequency-array two-pass route");
        assertTrue(hasFirstLastOccurrence,
                filename + " must include the alphabet first-last occurrence route");
        assertTrue(hasLinkedHashMap,
                filename + " must include the LinkedHashMap insertion-order route");
        assertTrue(hasCandidateQueue,
                filename + " must include the candidate-index queue route");
        assertTrue(hasActiveUniqueList,
                filename + " must include the active unique linked-list route");
    }

