    private static void assertRunningSumSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 4,
                filename + " should teach in-place prefix accumulation, new-array running totals, "
                        + "recursive prefix propagation, and Hillis-Steele prefix scan");

        boolean hasInPlacePrefix = false;
        boolean hasNewArrayRunningTotal = false;
        boolean hasRecursivePropagation = false;
        boolean hasHillisSteeleScan = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasInPlacePrefix = hasInPlacePrefix
                    || ((searchable.contains("in-place") || searchable.contains("mutate")
                    || searchable.contains("inside the input"))
                    && normalizedRawCode.contains("for(inti=1;i<nums.length;i++)")
                    && normalizedRawCode.contains("nums[i]+=nums[i-1]")
                    && normalizedRawCode.contains("returnnums"));
            hasNewArrayRunningTotal = hasNewArrayRunningTotal
                    || ((searchable.contains("new array") || searchable.contains("running total"))
                    && normalizedRawCode.contains("int[]answer=newint[nums.length]")
                    && normalizedRawCode.contains("intrunning=0")
                    && normalizedRawCode.contains("running+=nums[i]")
                    && normalizedRawCode.contains("answer[i]=running"));
            hasRecursivePropagation = hasRecursivePropagation
                    || ((searchable.contains("recursive") || searchable.contains("recurrence"))
                    && normalizedRawCode.contains("int[]answer=nums.clone()")
                    && normalizedRawCode.contains("fill(answer,1)")
                    && normalizedRawCode.contains("privatevoidfill(int[]answer,intindex)")
                    && normalizedRawCode.contains("answer[index]+=answer[index-1]")
                    && normalizedRawCode.contains("fill(answer,index+1)"));
            hasHillisSteeleScan = hasHillisSteeleScan
                    || ((searchable.contains("hillis") || searchable.contains("steele")
                    || searchable.contains("parallel prefix"))
                    && normalizedRawCode.contains("for(intstep=1;step<answer.length;step<<=1)")
                    && normalizedRawCode.contains("int[]previous=answer.clone()")
                    && normalizedRawCode.contains("answer[i]=previous[i]+previous[i-step]"));
        }

        assertTrue(hasInPlacePrefix,
                filename + " must include the in-place prefix-accumulation route");
        assertTrue(hasNewArrayRunningTotal,
                filename + " must include the new-array running-total route");
        assertTrue(hasRecursivePropagation,
                filename + " must include the recursive prefix-propagation route");
        assertTrue(hasHillisSteeleScan,
                filename + " must include the Hillis-Steele prefix-scan route");
    }

