    private static void assertSortingSentenceSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 4,
                filename + " should teach split-and-place, sort-by-trailing-digit, manual token parsing, "
                        + "and streaming builder-slot routes");

        boolean hasSplitPlacement = false;
        boolean hasSortByTrailingDigit = false;
        boolean hasManualParser = false;
        boolean hasStreamingBuilderSlots = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasSplitPlacement = hasSplitPlacement
                    || ((searchable.contains("split") || searchable.contains("place"))
                    && containsNormalizedCode(normalizedRawCode, "String[] tokens = s.split(\" \")")
                    && containsNormalizedCode(normalizedRawCode, "String[] ordered = new String[tokens.length]")
                    && containsNormalizedCode(normalizedRawCode, "int position = token.charAt(token.length() - 1) - '1'")
                    && containsNormalizedCode(normalizedRawCode, "ordered[position] = token.substring(0, token.length() - 1)")
                    && containsNormalizedCode(normalizedRawCode, "return String.join(\" \", ordered)"));
            hasSortByTrailingDigit = hasSortByTrailingDigit
                    || ((searchable.contains("sort") || searchable.contains("trailing digit"))
                    && containsNormalizedCode(normalizedRawCode, "Arrays.sort(tokens")
                    && containsNormalizedCode(
                            normalizedRawCode,
                            "left.charAt(left.length() - 1) - right.charAt(right.length() - 1)")
                    && containsNormalizedCode(normalizedRawCode, "answer.append(tokens[i], 0, tokens[i].length() - 1)"));
            hasManualParser = hasManualParser
                    || ((searchable.contains("manual") || searchable.contains("parser"))
                    && containsNormalizedCode(normalizedRawCode, "String[] slots = new String[9]")
                    && containsNormalizedCode(normalizedRawCode, "for (int i = 0; i <= s.length(); i++)")
                    && containsNormalizedCode(normalizedRawCode, "i == s.length() || s.charAt(i) == ' '")
                    && containsNormalizedCode(normalizedRawCode, "int position = s.charAt(i - 1) - '1'")
                    && containsNormalizedCode(normalizedRawCode, "slots[position] = s.substring(start, i - 1)"));
            hasStreamingBuilderSlots = hasStreamingBuilderSlots
                    || ((searchable.contains("streaming") || searchable.contains("builder"))
                    && containsNormalizedCode(normalizedRawCode, "StringBuilder[] slots = new StringBuilder[9]")
                    && containsNormalizedCode(normalizedRawCode, "StringBuilder current = new StringBuilder()")
                    && containsNormalizedCode(normalizedRawCode, "if (ch == ' ')")
                    && containsNormalizedCode(normalizedRawCode, "else if (ch >= '1' && ch <= '9')")
                    && containsNormalizedCode(normalizedRawCode, "slots[ch - '1'] = new StringBuilder(current)")
                    && containsNormalizedCode(normalizedRawCode, "current.append(ch)"));
        }

        assertTrue(hasSplitPlacement,
                filename + " must include the split-and-place route");
        assertTrue(hasSortByTrailingDigit,
                filename + " must include the sort-by-trailing-digit route");
        assertTrue(hasManualParser,
                filename + " must include the manual token-parser route");
        assertTrue(hasStreamingBuilderSlots,
                filename + " must include the streaming builder-slot route");
    }

