    private static void assertPangramSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 4,
                filename + " should teach boolean seen-array, HashSet, bitmask, and alphabet index-scan routes");

        boolean hasBooleanSeenArray = false;
        boolean hasHashSet = false;
        boolean hasBitmask = false;
        boolean hasAlphabetIndexScan = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasBooleanSeenArray = hasBooleanSeenArray
                    || ((searchable.contains("boolean") || searchable.contains("array"))
                    && containsNormalizedCode(normalizedRawCode, "boolean[] seen = new boolean[26]")
                    && containsNormalizedCode(normalizedRawCode, "int unique = 0")
                    && containsNormalizedCode(normalizedRawCode, "if (!seen[index])")
                    && containsNormalizedCode(normalizedRawCode, "unique++")
                    && containsNormalizedCode(normalizedRawCode, "if (unique == 26)"));
            hasHashSet = hasHashSet
                    || (searchable.contains("hashset")
                    && containsNormalizedCode(normalizedRawCode, "Set<Character> seen = new HashSet<>()")
                    && containsNormalizedCode(normalizedRawCode, "seen.add(sentence.charAt(i))")
                    && containsNormalizedCode(normalizedRawCode, "seen.size() == 26"));
            hasBitmask = hasBitmask
                    || (searchable.contains("mask")
                    && containsNormalizedCode(normalizedRawCode, "int mask = 0")
                    && containsNormalizedCode(normalizedRawCode, "int fullMask = (1 << 26) - 1")
                    && containsNormalizedCode(normalizedRawCode, "mask |= 1 << (sentence.charAt(i) - 'a')")
                    && containsNormalizedCode(normalizedRawCode, "mask == fullMask"));
            hasAlphabetIndexScan = hasAlphabetIndexScan
                    || ((searchable.contains("alphabet") || searchable.contains("index"))
                    && containsNormalizedCode(normalizedRawCode, "for (char letter = 'a'; letter <= 'z'; letter++)")
                    && containsNormalizedCode(normalizedRawCode, "sentence.indexOf(letter) == -1")
                    && containsNormalizedCode(normalizedRawCode, "return false")
                    && containsNormalizedCode(normalizedRawCode, "return true"));
        }

        assertTrue(hasBooleanSeenArray,
                filename + " must include the boolean seen-array route");
        assertTrue(hasHashSet,
                filename + " must include the HashSet unique-letter route");
        assertTrue(hasBitmask,
                filename + " must include the bitmask route");
        assertTrue(hasAlphabetIndexScan,
                filename + " must include the alphabet index-scan route");
    }

