    private static void assertConcatenationArraySolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 4,
                filename + " should teach single-pass dual write, two-pass offset copy, System.arraycopy, "
                        + "and modulo output-index fill routes");

        boolean hasSinglePassDualWrite = false;
        boolean hasTwoPassOffsetCopy = false;
        boolean hasSystemArraycopy = false;
        boolean hasModuloFill = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasSinglePassDualWrite = hasSinglePassDualWrite
                    || ((searchable.contains("single") || searchable.contains("dual"))
                    && containsNormalizedCode(normalizedRawCode, "int[] ans = new int[2 * n]")
                    && containsNormalizedCode(normalizedRawCode, "for (int i = 0; i < n; i++)")
                    && containsNormalizedCode(normalizedRawCode, "ans[i] = nums[i]")
                    && containsNormalizedCode(normalizedRawCode, "ans[i + n] = nums[i]"));
            hasTwoPassOffsetCopy = hasTwoPassOffsetCopy
                    || ((searchable.contains("two") || searchable.contains("offset"))
                    && containsNormalizedCode(normalizedRawCode, """
                            for (int i = 0; i < n; i++) {
                                ans[i] = nums[i];
                            }
                            for (int i = 0; i < n; i++) {
                                ans[i + n] = nums[i];
                            }
                            """));
            hasSystemArraycopy = hasSystemArraycopy
                    || ((searchable.contains("arraycopy") || searchable.contains("system"))
                    && containsNormalizedCode(normalizedRawCode, "System.arraycopy(nums, 0, ans, 0, n)")
                    && containsNormalizedCode(normalizedRawCode, "System.arraycopy(nums, 0, ans, n, n)"));
            hasModuloFill = hasModuloFill
                    || ((searchable.contains("modulo") || searchable.contains("index"))
                    && containsNormalizedCode(normalizedRawCode, "for (int i = 0; i < ans.length; i++)")
                    && containsNormalizedCode(normalizedRawCode, "ans[i] = nums[i % n]"));
        }

        assertTrue(hasSinglePassDualWrite,
                filename + " must include the single-pass dual-write route");
        assertTrue(hasTwoPassOffsetCopy,
                filename + " must include the two-pass offset-copy route");
        assertTrue(hasSystemArraycopy,
                filename + " must include the System.arraycopy route");
        assertTrue(hasModuloFill,
                filename + " must include the modulo output-index fill route");
    }

