    private static void assertCreateTargetArraySolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 4,
                filename + " should teach ArrayList insertion, manual right-shift array insertion, "
                        + "LinkedList insertion, and reverse empty-slot reconstruction routes");

        boolean hasArrayListInsertion = false;
        boolean hasManualShift = false;
        boolean hasLinkedListInsertion = false;
        boolean hasReverseEmptySlot = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasArrayListInsertion = hasArrayListInsertion
                    || ((searchable.contains("arraylist") || searchable.contains("dynamic"))
                    && containsNormalizedCode(normalizedRawCode, "List<Integer> target = new ArrayList<>()")
                    && containsNormalizedCode(normalizedRawCode, "target.add(index[i], nums[i])")
                    && containsNormalizedCode(normalizedRawCode, "int[] ans = new int[target.size()]")
                    && containsNormalizedCode(normalizedRawCode, "ans[i] = target.get(i)"));
            hasManualShift = hasManualShift
                    || ((searchable.contains("manual") || searchable.contains("shift"))
                    && containsNormalizedCode(normalizedRawCode, "int[] target = new int[nums.length]")
                    && containsNormalizedCode(normalizedRawCode, "int size = 0")
                    && containsNormalizedCode(normalizedRawCode, "for (int j = size; j > index[i]; j--)")
                    && containsNormalizedCode(normalizedRawCode, "target[j] = target[j - 1]")
                    && containsNormalizedCode(normalizedRawCode, "target[index[i]] = nums[i]")
                    && containsNormalizedCode(normalizedRawCode, "size++"));
            hasLinkedListInsertion = hasLinkedListInsertion
                    || ((searchable.contains("linkedlist") || searchable.contains("linked list"))
                    && containsNormalizedCode(normalizedRawCode, "LinkedList<Integer> target = new LinkedList<>()")
                    && containsNormalizedCode(normalizedRawCode, "target.add(index[i], nums[i])")
                    && containsNormalizedCode(normalizedRawCode, "answer[i] = target.get(i)"));
            hasReverseEmptySlot = hasReverseEmptySlot
                    || ((searchable.contains("reverse") || searchable.contains("empty-slot"))
                    && containsNormalizedCode(normalizedRawCode, "boolean[] used = new boolean[n]")
                    && containsNormalizedCode(normalizedRawCode, "for (int i = n - 1; i >= 0; i--)")
                    && containsNormalizedCode(normalizedRawCode, "int emptyRank = index[i]")
                    && containsNormalizedCode(normalizedRawCode, "if (used[position])")
                    && containsNormalizedCode(normalizedRawCode, "if (emptyRank == 0)")
                    && containsNormalizedCode(normalizedRawCode, "answer[position] = nums[i]")
                    && containsNormalizedCode(normalizedRawCode, "used[position] = true")
                    && containsNormalizedCode(normalizedRawCode, "emptyRank--"));
        }

        assertTrue(hasArrayListInsertion,
                filename + " must include the ArrayList insertion route");
        assertTrue(hasManualShift,
                filename + " must include the manual right-shift array route");
        assertTrue(hasLinkedListInsertion,
                filename + " must include the LinkedList insertion route");
        assertTrue(hasReverseEmptySlot,
                filename + " must include the reverse empty-slot reconstruction route");
    }

