    private static void assertXorOperationSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 4,
                filename + " should teach direct index simulation, incremental term scanning, "
                        + "array materialization, and prefix-XOR closed-form routes");

        boolean hasDirectIndex = false;
        boolean hasIncrementalTerm = false;
        boolean hasBuildThenReduce = false;
        boolean hasPrefixClosedForm = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasDirectIndex = hasDirectIndex
                    || ((searchable.contains("direct") || searchable.contains("index"))
                    && containsNormalizedCode(normalizedRawCode, "for (int i = 0; i < n; i++)")
                    && containsNormalizedCode(normalizedRawCode, "answer ^= start + 2 * i"));
            hasIncrementalTerm = hasIncrementalTerm
                    || ((searchable.contains("incremental") || searchable.contains("current"))
                    && containsNormalizedCode(normalizedRawCode, "int current = start")
                    && containsNormalizedCode(normalizedRawCode, "int remaining = n")
                    && containsNormalizedCode(normalizedRawCode, "while (remaining > 0)")
                    && containsNormalizedCode(normalizedRawCode, "answer ^= current")
                    && containsNormalizedCode(normalizedRawCode, "current += 2")
                    && containsNormalizedCode(normalizedRawCode, "remaining--"));
            hasBuildThenReduce = hasBuildThenReduce
                    || ((searchable.contains("build") || searchable.contains("materialize"))
                    && containsNormalizedCode(normalizedRawCode, "int[] nums = new int[n]")
                    && containsNormalizedCode(normalizedRawCode, "nums[i] = start + 2 * i")
                    && containsNormalizedCode(normalizedRawCode, "for (int value : nums)")
                    && containsNormalizedCode(normalizedRawCode, "answer ^= value"));
            hasPrefixClosedForm = hasPrefixClosedForm
                    || ((searchable.contains("prefix") || searchable.contains("closed form"))
                    && containsNormalizedCode(normalizedRawCode, "int base = start >> 1")
                    && containsNormalizedCode(normalizedRawCode, "xorPrefix(base - 1) ^ xorPrefix(base + n - 1)")
                    && containsNormalizedCode(normalizedRawCode, "int lowBit = (n % 2) * (start & 1)")
                    && containsNormalizedCode(normalizedRawCode, "return (highBits << 1) | lowBit")
                    && containsNormalizedCode(normalizedRawCode, "int pattern = x & 3"));
        }

        assertTrue(hasDirectIndex,
                filename + " must include the direct index simulation route");
        assertTrue(hasIncrementalTerm,
                filename + " must include the incremental term scan route");
        assertTrue(hasBuildThenReduce,
                filename + " must include the build-then-reduce array route");
        assertTrue(hasPrefixClosedForm,
                filename + " must include the prefix-XOR closed-form route");
    }

