    private static void assertAlternatingSubarraySolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 3,
                filename + " should teach start-each-window, rolling expected-difference, and ending-here DP routes");

        boolean hasStartEachWindow = false;
        boolean hasRollingExpectedDifference = false;
        boolean hasLengthEndingHereDp = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasStartEachWindow = hasStartEachWindow
                    || ((searchable.contains("start") || searchable.contains("brute"))
                    && containsNormalizedCode(normalizedRawCode, "for (int start = 0; start < nums.length - 1; start++)")
                    && containsNormalizedCode(normalizedRawCode, "int expected = 1")
                    && containsNormalizedCode(normalizedRawCode, "for (int end = start + 1; end < nums.length; end++)")
                    && containsNormalizedCode(normalizedRawCode, "if (nums[end] - nums[end - 1] != expected)")
                    && containsNormalizedCode(normalizedRawCode, "break")
                    && containsNormalizedCode(normalizedRawCode, "best = Math.max(best, end - start + 1)")
                    && containsNormalizedCode(normalizedRawCode, "expected *= -1"));
            hasRollingExpectedDifference = hasRollingExpectedDifference
                    || ((searchable.contains("rolling") || searchable.contains("expected"))
                    && containsNormalizedCode(normalizedRawCode, "int start = 0")
                    && containsNormalizedCode(normalizedRawCode, "int expected = 1")
                    && containsNormalizedCode(normalizedRawCode, "int diff = nums[i] - nums[i - 1]")
                    && containsNormalizedCode(normalizedRawCode, "if (diff == expected)")
                    && containsNormalizedCode(normalizedRawCode, "expected *= -1")
                    && containsNormalizedCode(normalizedRawCode, "else if (diff == 1)")
                    && containsNormalizedCode(normalizedRawCode, "start = i - 1")
                    && containsNormalizedCode(normalizedRawCode, "best = Math.max(best, 2)")
                    && containsNormalizedCode(normalizedRawCode, "expected = -1")
                    && containsNormalizedCode(normalizedRawCode, "start = i"));
            hasLengthEndingHereDp = hasLengthEndingHereDp
                    || ((searchable.contains("dp") || searchable.contains("ending"))
                    && containsNormalizedCode(normalizedRawCode, "int length = 1")
                    && containsNormalizedCode(normalizedRawCode, "if (length == 1)")
                    && containsNormalizedCode(normalizedRawCode, "length = diff == 1 ? 2 : 1")
                    && containsNormalizedCode(normalizedRawCode, "int expected = length % 2 == 0 ? -1 : 1")
                    && containsNormalizedCode(normalizedRawCode, "if (diff == expected)")
                    && containsNormalizedCode(normalizedRawCode, "length++")
                    && containsNormalizedCode(normalizedRawCode, "if (length >= 2)")
                    && containsNormalizedCode(normalizedRawCode, "best = Math.max(best, length)"));
        }

        assertTrue(hasStartEachWindow,
                filename + " must include the start-each-window baseline route");
        assertTrue(hasRollingExpectedDifference,
                filename + " must include the rolling expected-difference route");
        assertTrue(hasLengthEndingHereDp,
                filename + " must include the length-ending-here DP route");
    }

