    private static void assertReversePrefixSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 4,
                filename + " should teach StringBuilder reverse, char-array two pointers, manual builder, "
                        + "and stack rebuild routes");

        boolean hasStringBuilderReverse = false;
        boolean hasTwoPointerSwap = false;
        boolean hasManualBuilder = false;
        boolean hasStackRebuild = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasStringBuilderReverse = hasStringBuilderReverse
                    || ((searchable.contains("stringbuilder") || searchable.contains("builder"))
                    && containsNormalizedCode(normalizedRawCode, "int index = word.indexOf(ch)")
                    && containsNormalizedCode(normalizedRawCode, "if (index == -1)")
                    && containsNormalizedCode(
                            normalizedRawCode,
                            "StringBuilder prefix = new StringBuilder(word.substring(0, index + 1))")
                    && containsNormalizedCode(normalizedRawCode, "prefix.reverse()")
                    && containsNormalizedCode(
                            normalizedRawCode, "return prefix.append(word.substring(index + 1)).toString()"));
            hasTwoPointerSwap = hasTwoPointerSwap
                    || ((searchable.contains("two pointer") || searchable.contains("swap"))
                    && containsNormalizedCode(normalizedRawCode, "char[] chars = word.toCharArray()")
                    && containsNormalizedCode(normalizedRawCode, "int end = -1")
                    && containsNormalizedCode(normalizedRawCode, "if (chars[i] == ch)")
                    && containsNormalizedCode(normalizedRawCode, "int left = 0")
                    && containsNormalizedCode(normalizedRawCode, "int right = end")
                    && containsNormalizedCode(normalizedRawCode, "char temp = chars[left]")
                    && containsNormalizedCode(normalizedRawCode, "chars[left++] = chars[right]")
                    && containsNormalizedCode(normalizedRawCode, "chars[right--] = temp")
                    && containsNormalizedCode(normalizedRawCode, "return new String(chars)"));
            hasManualBuilder = hasManualBuilder
                    || ((searchable.contains("manual") || searchable.contains("index"))
                    && containsNormalizedCode(normalizedRawCode, "int end = -1")
                    && containsNormalizedCode(normalizedRawCode, "for (int i = 0; i < word.length(); i++)")
                    && containsNormalizedCode(normalizedRawCode, "if (word.charAt(i) == ch)")
                    && containsNormalizedCode(normalizedRawCode, "StringBuilder answer = new StringBuilder(word.length())")
                    && containsNormalizedCode(normalizedRawCode, "for (int i = end; i >= 0; i--)")
                    && containsNormalizedCode(normalizedRawCode, "answer.append(word.charAt(i))")
                    && containsNormalizedCode(normalizedRawCode, "for (int i = end + 1; i < word.length(); i++)")
                    && containsNormalizedCode(normalizedRawCode, "return answer.toString()"));
            hasStackRebuild = hasStackRebuild
                    || ((searchable.contains("stack") || searchable.contains("rebuild"))
                    && containsNormalizedCode(normalizedRawCode, "Deque<Character> stack = new ArrayDeque<>()")
                    && containsNormalizedCode(normalizedRawCode, "for (int i = 0; i <= end; i++)")
                    && containsNormalizedCode(normalizedRawCode, "stack.push(word.charAt(i))")
                    && containsNormalizedCode(normalizedRawCode, "while (!stack.isEmpty())")
                    && containsNormalizedCode(normalizedRawCode, "answer.append(stack.pop())")
                    && containsNormalizedCode(normalizedRawCode, "answer.append(word.substring(end + 1))"));
        }

        assertTrue(hasStringBuilderReverse,
                filename + " must include the StringBuilder prefix-reverse route");
        assertTrue(hasTwoPointerSwap,
                filename + " must include the char-array two-pointer swap route");
        assertTrue(hasManualBuilder,
                filename + " must include the manual builder-by-index route");
        assertTrue(hasStackRebuild,
                filename + " must include the stack prefix-rebuild route");
    }

