    private static void assertDistinctDifferenceArraySolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 4,
                filename + " should teach prefix/suffix arrays, rolling suffix frequencies, "
                        + "first/last occurrence sweeps, and coordinate-compression counting routes");

        boolean hasPrefixSuffixArrays = false;
        boolean hasRollingSuffixFrequency = false;
        boolean hasOccurrenceSweep = false;
        boolean hasCoordinateCompression = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasPrefixSuffixArrays = hasPrefixSuffixArrays
                    || ((searchable.contains("prefix") || searchable.contains("suffix"))
                    && containsNormalizedCode(normalizedRawCode, "int[] suffixDistinct = new int[n + 1]")
                    && containsNormalizedCode(normalizedRawCode, "for (int i = n - 1; i >= 0; i--)")
                    && containsNormalizedCode(normalizedRawCode, "seen.add(nums[i])")
                    && containsNormalizedCode(normalizedRawCode, "answer[i] = seen.size() - suffixDistinct[i + 1]"));
            hasRollingSuffixFrequency = hasRollingSuffixFrequency
                    || ((searchable.contains("rolling") || searchable.contains("frequency"))
                    && containsNormalizedCode(normalizedRawCode, "Map<Integer, Integer> suffix = new HashMap<>()")
                    && containsNormalizedCode(normalizedRawCode, "suffix.getOrDefault(num, 0) + 1")
                    && containsNormalizedCode(normalizedRawCode, "int suffixDistinct = suffix.size()")
                    && containsNormalizedCode(normalizedRawCode, "suffix.remove(nums[i])")
                    && containsNormalizedCode(normalizedRawCode, "answer[i] = prefix.size() - suffixDistinct"));
            hasOccurrenceSweep = hasOccurrenceSweep
                    || ((searchable.contains("occurrence") || searchable.contains("sweep"))
                    && containsNormalizedCode(normalizedRawCode, "first.putIfAbsent(nums[i], i)")
                    && containsNormalizedCode(normalizedRawCode, "last.put(nums[i], i)")
                    && containsNormalizedCode(normalizedRawCode, "int[] prefixGain = new int[n]")
                    && containsNormalizedCode(normalizedRawCode, "suffixDelta[0]++")
                    && containsNormalizedCode(normalizedRawCode, "suffixDelta[lastIndex]--")
                    && containsNormalizedCode(normalizedRawCode, "answer[i] = prefixDistinct - suffixDistinct"));
            hasCoordinateCompression = hasCoordinateCompression
                    || ((searchable.contains("coordinate") || searchable.contains("compression"))
                    && containsNormalizedCode(normalizedRawCode, "int[] sorted = nums.clone()")
                    && containsNormalizedCode(normalizedRawCode, "Arrays.sort(sorted)")
                    && containsNormalizedCode(normalizedRawCode, "int unique = 0")
                    && containsNormalizedCode(normalizedRawCode, "right[indexOf(sorted, unique, num)]++")
                    && containsNormalizedCode(normalizedRawCode, "private int indexOf(int[] sorted, int unique, int target)")
                    && containsNormalizedCode(normalizedRawCode, "answer[i] = leftDistinct - rightDistinct"));
        }

        assertTrue(hasPrefixSuffixArrays,
                filename + " must include the prefix/suffix distinct-array route");
        assertTrue(hasRollingSuffixFrequency,
                filename + " must include the rolling suffix-frequency route");
        assertTrue(hasOccurrenceSweep,
                filename + " must include the first/last occurrence sweep route");
        assertTrue(hasCoordinateCompression,
                filename + " must include the coordinate-compression counting route");
    }

