    private static void assertCountAllOneSubmatricesSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 4,
                filename + " should teach height expansion, monotonic stack, row-pair compression, "
                        + "and width-DP upward scan routes");

        boolean hasHeightExpansion = false;
        boolean hasMonotonicStack = false;
        boolean hasRowPairCompression = false;
        boolean hasWidthDpUpwardScan = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasHeightExpansion = hasHeightExpansion
                    || ((searchable.contains("height") || searchable.contains("bottom"))
                    && containsNormalizedCode(normalizedRawCode, "int[] height = new int[cols]")
                    && containsNormalizedCode(normalizedRawCode, "height[c] = mat[r][c] == 0 ? 0 : height[c] + 1")
                    && containsNormalizedCode(normalizedRawCode, "for (int right = 0; right < cols; right++)")
                    && containsNormalizedCode(normalizedRawCode, "int minHeight = height[right]")
                    && containsNormalizedCode(normalizedRawCode, "answer += minHeight"));
            hasMonotonicStack = hasMonotonicStack
                    || ((searchable.contains("stack") || searchable.contains("monotonic"))
                    && containsNormalizedCode(normalizedRawCode, "Deque<int[]> stack = new ArrayDeque<>()")
                    && containsNormalizedCode(normalizedRawCode, "while (!stack.isEmpty() && stack.peek()[0] >= height[c])")
                    && containsNormalizedCode(normalizedRawCode, "rowCount -= top[0] * top[1]")
                    && containsNormalizedCode(normalizedRawCode, "stack.push(new int[] {height[c], width})")
                    && containsNormalizedCode(normalizedRawCode, "answer += rowCount"));
            hasRowPairCompression = hasRowPairCompression
                    || ((searchable.contains("row pair") || searchable.contains("compression"))
                    && containsNormalizedCode(normalizedRawCode, "for (int top = 0; top < rows; top++)")
                    && containsNormalizedCode(normalizedRawCode, "Arrays.fill(allOne, 1)")
                    && containsNormalizedCode(normalizedRawCode, "for (int bottom = top; bottom < rows; bottom++)")
                    && containsNormalizedCode(normalizedRawCode, "allOne[c] &= mat[bottom][c]")
                    && containsNormalizedCode(normalizedRawCode, "answer += run"));
            hasWidthDpUpwardScan = hasWidthDpUpwardScan
                    || ((searchable.contains("width") || searchable.contains("upward"))
                    && containsNormalizedCode(normalizedRawCode, "int[][] width = new int[rows][cols]")
                    && containsNormalizedCode(normalizedRawCode, "width[r][c] = (c == 0 ? 0 : width[r][c - 1]) + 1")
                    && containsNormalizedCode(normalizedRawCode, "int minWidth = width[r][c]")
                    && containsNormalizedCode(normalizedRawCode, "for (int up = r; up >= 0 && minWidth > 0; up--)")
                    && containsNormalizedCode(normalizedRawCode, "answer += minWidth"));
        }

        assertTrue(hasHeightExpansion,
                filename + " must include the bottom-row height-expansion route");
        assertTrue(hasMonotonicStack,
                filename + " must include the monotonic-stack histogram route");
        assertTrue(hasRowPairCompression,
                filename + " must include the row-pair column-compression route");
        assertTrue(hasWidthDpUpwardScan,
                filename + " must include the width-DP upward-scan route");
    }

