    private static void assertSwapNodesInPairsSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 4,
                filename + " should teach dummy-node iteration, recursion, no-dummy head/tail iteration, "
                        + "and a two-node stack-buffer route");

        boolean hasDummyIteration = false;
        boolean hasRecursion = false;
        boolean hasNoDummyHeadTail = false;
        boolean hasStackBuffer = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasDummyIteration = hasDummyIteration
                    || ((searchable.contains("dummy") || searchable.contains("iterative"))
                    && containsNormalizedCode(normalizedRawCode, "ListNode dummy = new ListNode(0, head)")
                    && containsNormalizedCode(normalizedRawCode, "ListNode prev = dummy")
                    && containsNormalizedCode(normalizedRawCode, "prev.next = second")
                    && containsNormalizedCode(normalizedRawCode, "second.next = first")
                    && containsNormalizedCode(normalizedRawCode, "first.next = rest")
                    && containsNormalizedCode(normalizedRawCode, "return dummy.next"));
            hasRecursion = hasRecursion
                    || ((searchable.contains("recursive") || searchable.contains("recursion"))
                    && containsNormalizedCode(normalizedRawCode, "if (head == null || head.next == null)")
                    && containsNormalizedCode(normalizedRawCode, "ListNode second = head.next")
                    && containsNormalizedCode(normalizedRawCode, "ListNode rest = second.next")
                    && containsNormalizedCode(normalizedRawCode, "head.next = swapPairs(rest)")
                    && containsNormalizedCode(normalizedRawCode, "return second"));
            hasNoDummyHeadTail = hasNoDummyHeadTail
                    || ((searchable.contains("without dummy") || searchable.contains("head tail"))
                    && containsNormalizedCode(normalizedRawCode, "ListNode newHead = head.next")
                    && containsNormalizedCode(normalizedRawCode, "ListNode previousTail = null")
                    && containsNormalizedCode(normalizedRawCode, "if (previousTail != null)")
                    && containsNormalizedCode(normalizedRawCode, "previousTail.next = second")
                    && containsNormalizedCode(normalizedRawCode, "previousTail = first")
                    && containsNormalizedCode(normalizedRawCode, "return newHead"));
            hasStackBuffer = hasStackBuffer
                    || ((searchable.contains("stack") || searchable.contains("buffer"))
                    && containsNormalizedCode(normalizedRawCode, "Deque<ListNode> stack = new ArrayDeque<>()")
                    && containsNormalizedCode(normalizedRawCode, "current.next = null")
                    && containsNormalizedCode(normalizedRawCode, "stack.push(current)")
                    && containsNormalizedCode(normalizedRawCode, "if (count == 1)")
                    && containsNormalizedCode(normalizedRawCode, "tail.next = stack.pop()")
                    && containsNormalizedCode(normalizedRawCode, "return dummy.next"));
        }

        assertTrue(hasDummyIteration,
                filename + " must include the dummy-node iterative rewire route");
        assertTrue(hasRecursion,
                filename + " must include the recursive pair-swap route");
        assertTrue(hasNoDummyHeadTail,
                filename + " must include the no-dummy head/tail iterative route");
        assertTrue(hasStackBuffer,
                filename + " must include the two-node stack-buffer route");
    }

