    private static void assertLongestValidParenthesesSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 4,
                filename + " should teach stack with sentinel index, dynamic programming, "
                        + "two-pass counter scanning, and matched-pair marking routes");

        boolean hasStackSentinel = false;
        boolean hasDynamicProgramming = false;
        boolean hasTwoPassCounters = false;
        boolean hasMatchedMarking = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasStackSentinel = hasStackSentinel
                    || ((searchable.contains("stack") || searchable.contains("sentinel"))
                    && containsNormalizedCode(normalizedRawCode, "Deque<Integer> stack = new ArrayDeque<>()")
                    && containsNormalizedCode(normalizedRawCode, "stack.push(-1)")
                    && containsNormalizedCode(normalizedRawCode, "if (stack.isEmpty())")
                    && containsNormalizedCode(normalizedRawCode, "stack.push(i)")
                    && containsNormalizedCode(normalizedRawCode, "best = Math.max(best, i - stack.peek())"));
            hasDynamicProgramming = hasDynamicProgramming
                    || ((searchable.contains("dynamic") || searchable.contains("dp"))
                    && containsNormalizedCode(normalizedRawCode, "int[] dp = new int[s.length()]")
                    && containsNormalizedCode(normalizedRawCode, "if (s.charAt(i) != ')')")
                    && containsNormalizedCode(normalizedRawCode, "dp[i] = 2 + (i >= 2 ? dp[i - 2] : 0)")
                    && containsNormalizedCode(normalizedRawCode, "int match = i - dp[i - 1] - 1")
                    && containsNormalizedCode(normalizedRawCode, "dp[i] = dp[i - 1] + 2 + (match >= 1 ? dp[match - 1] : 0)"));
            hasTwoPassCounters = hasTwoPassCounters
                    || ((searchable.contains("two-pass") || searchable.contains("counter"))
                    && containsNormalizedCode(normalizedRawCode, "int left = 0")
                    && containsNormalizedCode(normalizedRawCode, "int right = 0")
                    && containsNormalizedCode(normalizedRawCode, "for (int i = 0; i < s.length(); i++)")
                    && containsNormalizedCode(normalizedRawCode, "else if (right > left)")
                    && containsNormalizedCode(normalizedRawCode, "for (int i = s.length() - 1; i >= 0; i--)")
                    && containsNormalizedCode(normalizedRawCode, "else if (left > right)"));
            hasMatchedMarking = hasMatchedMarking
                    || ((searchable.contains("mark") || searchable.contains("matched"))
                    && containsNormalizedCode(normalizedRawCode, "boolean[] matched = new boolean[s.length()]")
                    && containsNormalizedCode(normalizedRawCode, "Deque<Integer> opens = new ArrayDeque<>()")
                    && containsNormalizedCode(normalizedRawCode, "int open = opens.pop()")
                    && containsNormalizedCode(normalizedRawCode, "matched[open] = true")
                    && containsNormalizedCode(normalizedRawCode, "for (boolean ok : matched)")
                    && containsNormalizedCode(normalizedRawCode, "best = Math.max(best, run)"));
        }

        assertTrue(hasStackSentinel,
                filename + " must include the stack-with-sentinel-index route");
        assertTrue(hasDynamicProgramming,
                filename + " must include the dynamic-programming ending-at-index route");
        assertTrue(hasTwoPassCounters,
                filename + " must include the two-pass counter-scan route");
        assertTrue(hasMatchedMarking,
                filename + " must include the matched-pair marking route");
    }

