    private static void assertMaximumSubmatrixSumNoMoreThanKSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 4,
                filename + " should teach adaptive compression, column compression, row compression "
                        + "with sorted-list lower_bound, and 2D-prefix rectangle enumeration routes");

        boolean hasAdaptiveCompression = false;
        boolean hasColumnCompression = false;
        boolean hasRowCompression = false;
        boolean hasPrefixEnumeration = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasAdaptiveCompression = hasAdaptiveCompression
                    || ((searchable.contains("adaptive") || searchable.contains("smaller"))
                    && containsNormalizedCode(normalizedRawCode, "return cols <= rows ? compressColumns(matrix, k) : compressRows(matrix, k)")
                    && containsNormalizedCode(normalizedRawCode, "private int compressColumns(int[][] matrix, int k)")
                    && containsNormalizedCode(normalizedRawCode, "private int compressRows(int[][] matrix, int k)")
                    && containsNormalizedCode(normalizedRawCode, "TreeSet<Integer> prefixes = new TreeSet<>()"));
            hasColumnCompression = hasColumnCompression
                    || ((searchable.contains("column") || searchable.contains("cols"))
                    && containsNormalizedCode(normalizedRawCode, "for (int left = 0; left < cols; left++)")
                    && containsNormalizedCode(normalizedRawCode, "for (int right = left; right < cols; right++)")
                    && containsNormalizedCode(normalizedRawCode, "rowSums[row] += matrix[row][right]")
                    && containsNormalizedCode(normalizedRawCode, "prefixes.ceiling(prefix - k)"));
            hasRowCompression = hasRowCompression
                    || ((searchable.contains("row") || searchable.contains("rows"))
                    && containsNormalizedCode(normalizedRawCode, "for (int top = 0; top < rows; top++)")
                    && containsNormalizedCode(normalizedRawCode, "for (int bottom = top; bottom < rows; bottom++)")
                    && containsNormalizedCode(normalizedRawCode, "columnSums[col] += matrix[bottom][col]")
                    && containsNormalizedCode(normalizedRawCode, "List<Integer> prefixes = new ArrayList<>()")
                    && containsNormalizedCode(normalizedRawCode, "int targetIndex = lowerBound(prefixes, prefix - k)")
                    && containsNormalizedCode(normalizedRawCode, "prefixes.add(lowerBound(prefixes, prefix), prefix)"));
            hasPrefixEnumeration = hasPrefixEnumeration
                    || ((searchable.contains("prefix") || searchable.contains("enumeration"))
                    && containsNormalizedCode(normalizedRawCode, "int[][] prefix = new int[rows + 1][cols + 1]")
                    && containsNormalizedCode(normalizedRawCode, "prefix[row + 1][col + 1] = matrix[row][col]")
                    && containsNormalizedCode(normalizedRawCode, "for (int bottom = top; bottom < rows; bottom++)")
                    && containsNormalizedCode(normalizedRawCode, "for (int right = left; right < cols; right++)")
                    && containsNormalizedCode(normalizedRawCode, "if (sum <= k)"));
        }

        assertTrue(hasAdaptiveCompression,
                filename + " must include the adaptive smaller-dimension compression route");
        assertTrue(hasColumnCompression,
                filename + " must include the column-compression TreeSet route");
        assertTrue(hasRowCompression,
                filename + " must include the row-compression sorted-list lower_bound route");
        assertTrue(hasPrefixEnumeration,
                filename + " must include the 2D-prefix rectangle-enumeration route");
    }

