    private static void assertNQueensIISolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 4,
                filename + " should teach boolean-array backtracking, bitmask available-position DFS, "
                        + "first-row symmetry pruning, and permutation diagonal scanning routes");

        boolean hasBooleanArrays = false;
        boolean hasBitmaskDfs = false;
        boolean hasSymmetryPruning = false;
        boolean hasPermutationScanner = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasBooleanArrays = hasBooleanArrays
                    || ((searchable.contains("boolean") || searchable.contains("array"))
                    && containsNormalizedCode(normalizedRawCode, "boolean[] columns = new boolean[n]")
                    && containsNormalizedCode(normalizedRawCode, "boolean[] mainDiag = new boolean[2 * n - 1]")
                    && containsNormalizedCode(normalizedRawCode, "boolean[] antiDiag = new boolean[2 * n - 1]")
                    && containsNormalizedCode(normalizedRawCode, "int main = row - col + n - 1")
                    && containsNormalizedCode(normalizedRawCode, "int anti = row + col")
                    && containsNormalizedCode(normalizedRawCode, "columns[col] = true"));
            hasBitmaskDfs = hasBitmaskDfs
                    || (searchable.contains("available-position")
                    && containsNormalizedCode(normalizedRawCode, "fullMask = (1 << n) - 1")
                    && containsNormalizedCode(normalizedRawCode, "return count(0, 0, 0)")
                    && containsNormalizedCode(normalizedRawCode, "if (columns == fullMask)")
                    && containsNormalizedCode(normalizedRawCode, "int available = fullMask & ~(columns | diagonals | antiDiagonals)")
                    && containsNormalizedCode(normalizedRawCode, "int bit = available & -available")
                    && containsNormalizedCode(normalizedRawCode, "(diagonals | bit) << 1")
                    && containsNormalizedCode(normalizedRawCode, "(antiDiagonals | bit) >>> 1"));
            hasSymmetryPruning = hasSymmetryPruning
                    || ((searchable.contains("symmetry") || searchable.contains("first-row"))
                    && containsNormalizedCode(normalizedRawCode, "for (int col = 0; col < n / 2; col++)")
                    && containsNormalizedCode(normalizedRawCode, "total += 2 * countFromRow")
                    && containsNormalizedCode(normalizedRawCode, "if ((n & 1) == 1)")
                    && containsNormalizedCode(normalizedRawCode, "int bit = 1 << (n / 2)")
                    && containsNormalizedCode(normalizedRawCode, "countFromRow(1, bit, bit << 1, bit >>> 1)"));
            hasPermutationScanner = hasPermutationScanner
                    || ((searchable.contains("permutation") || searchable.contains("diagonal scanner"))
                    && containsNormalizedCode(normalizedRawCode, "int[] queenColumn = new int[n]")
                    && containsNormalizedCode(normalizedRawCode, "boolean[] usedColumns = new boolean[n]")
                    && containsNormalizedCode(normalizedRawCode, "hasDiagonalConflict(row, col, queenColumn)")
                    && containsNormalizedCode(normalizedRawCode, "Math.abs(row - prev) == Math.abs(col - queenColumn[prev])")
                    && containsNormalizedCode(normalizedRawCode, "usedColumns[col] = true"));
        }

        assertTrue(hasBooleanArrays,
                filename + " must include the boolean-array backtracking route");
        assertTrue(hasBitmaskDfs,
                filename + " must include the bitmask available-position DFS route");
        assertTrue(hasSymmetryPruning,
                filename + " must include the first-row symmetry-pruning route");
        assertTrue(hasPermutationScanner,
                filename + " must include the permutation diagonal-scanner route");
    }

