    private static void assertPermutationSequenceSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 4,
                filename + " should teach factorial list removal, boolean availability scanning, "
                        + "Fenwick order statistics, and next-permutation baseline routes");

        boolean hasFactorialListRemoval = false;
        boolean hasBooleanAvailabilityScan = false;
        boolean hasFenwickOrderStatistic = false;
        boolean hasNextPermutationBaseline = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasFactorialListRemoval = hasFactorialListRemoval
                    || ((searchable.contains("factorial") || searchable.contains("list removal"))
                    && containsNormalizedCode(normalizedRawCode, "java.util.List<Integer> remaining = new java.util.ArrayList<>()")
                    && containsNormalizedCode(normalizedRawCode, "int index = k - 1")
                    && containsNormalizedCode(normalizedRawCode, "int block = factorial[len - 1]")
                    && containsNormalizedCode(normalizedRawCode, "int pick = index / block")
                    && containsNormalizedCode(normalizedRawCode, "remaining.remove(pick)")
                    && containsNormalizedCode(normalizedRawCode, "index %= block"));
            hasBooleanAvailabilityScan = hasBooleanAvailabilityScan
                    || ((searchable.contains("boolean") || searchable.contains("availability"))
                    && containsNormalizedCode(normalizedRawCode, "boolean[] used = new boolean[n + 1]")
                    && containsNormalizedCode(normalizedRawCode, "int order = index / block + 1")
                    && containsNormalizedCode(normalizedRawCode, "int digit = takeUnused(used, order)")
                    && containsNormalizedCode(normalizedRawCode, "used[digit] = true")
                    && containsNormalizedCode(normalizedRawCode, "return digit"));
            hasFenwickOrderStatistic = hasFenwickOrderStatistic
                    || ((searchable.contains("fenwick") || searchable.contains("order statistic"))
                    && containsNormalizedCode(normalizedRawCode, "int[] bit = new int[n + 1]")
                    && containsNormalizedCode(normalizedRawCode, "add(bit, digit, 1)")
                    && containsNormalizedCode(normalizedRawCode, "findByOrder(bit, order)")
                    && containsNormalizedCode(normalizedRawCode, "add(bit, digit, -1)")
                    && containsNormalizedCode(normalizedRawCode, "i += i & -i")
                    && containsNormalizedCode(normalizedRawCode, "Integer.highestOneBit(bit.length - 1)"));
            hasNextPermutationBaseline = hasNextPermutationBaseline
                    || ((searchable.contains("next permutation") || searchable.contains("baseline"))
                    && containsNormalizedCode(normalizedRawCode, "for (int step = 1; step < k; step++)")
                    && containsNormalizedCode(normalizedRawCode, "nextPermutation(digits)")
                    && containsNormalizedCode(normalizedRawCode, "int pivot = digits.length - 2")
                    && containsNormalizedCode(normalizedRawCode, "digits[pivot] > digits[pivot + 1]")
                    && containsNormalizedCode(normalizedRawCode, "reverse(digits, pivot + 1, digits.length - 1)"));
        }

        assertTrue(hasFactorialListRemoval,
                filename + " must include the factorial list-removal route");
        assertTrue(hasBooleanAvailabilityScan,
                filename + " must include the boolean availability-scan route");
        assertTrue(hasFenwickOrderStatistic,
                filename + " must include the Fenwick order-statistic route");
        assertTrue(hasNextPermutationBaseline,
                filename + " must include the next-permutation baseline route");
    }

