    private static void assertCountSubarraysFixedBoundsSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 4,
                filename + " should teach last-seen contribution counting, shrinking-window counting, "
                        + "segment inclusion-exclusion, and an enumeration baseline");

        boolean hasLastSeenContribution = false;
        boolean hasShrinkingWindowCounts = false;
        boolean hasInclusionExclusion = false;
        boolean hasEnumerationBaseline = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasLastSeenContribution = hasLastSeenContribution
                    || ((searchable.contains("last seen") || searchable.contains("recent")
                    || searchable.contains("contribution"))
                    && containsNormalizedCode(normalizedRawCode, "int lastInvalid = -1")
                    && containsNormalizedCode(normalizedRawCode, "int lastMin = -1")
                    && containsNormalizedCode(normalizedRawCode, "int lastMax = -1")
                    && containsNormalizedCode(normalizedRawCode, "int earliestRequired = Math.min(lastMin, lastMax)")
                    && containsNormalizedCode(normalizedRawCode, "answer += earliestRequired - lastInvalid"));
            hasShrinkingWindowCounts = hasShrinkingWindowCounts
                    || ((searchable.contains("shrinking") || searchable.contains("window"))
                    && containsNormalizedCode(normalizedRawCode, "int segmentStart = 0")
                    && containsNormalizedCode(normalizedRawCode, "int countMin = 0")
                    && containsNormalizedCode(normalizedRawCode, "int countMax = 0")
                    && containsNormalizedCode(normalizedRawCode, "while (countMin > 0 && countMax > 0)")
                    && containsNormalizedCode(normalizedRawCode, "answer += left - segmentStart"));
            hasInclusionExclusion = hasInclusionExclusion
                    || ((searchable.contains("inclusion") || searchable.contains("exclusion"))
                    && containsNormalizedCode(normalizedRawCode, "long allInside = countRunsInRange(nums, minK, maxK)")
                    && containsNormalizedCode(normalizedRawCode,
                    "long missingMin = countRunsInRange(nums, (long) minK + 1L, maxK)")
                    && containsNormalizedCode(normalizedRawCode,
                    "long missingMax = countRunsInRange(nums, minK, (long) maxK - 1L)")
                    && containsNormalizedCode(normalizedRawCode,
                    "return allInside - missingMin - missingMax + missingBoth")
                    && containsNormalizedCode(normalizedRawCode, "private long countRunsInRange"));
            hasEnumerationBaseline = hasEnumerationBaseline
                    || ((searchable.contains("enumerate") || searchable.contains("baseline"))
                    && containsNormalizedCode(normalizedRawCode, "for (int left = 0; left < nums.length; left++)")
                    && containsNormalizedCode(normalizedRawCode, "for (int right = left; right < nums.length; right++)")
                    && containsNormalizedCode(normalizedRawCode, "minimum = Math.min(minimum, value)")
                    && containsNormalizedCode(normalizedRawCode, "if (minimum < minK || maximum > maxK)")
                    && containsNormalizedCode(normalizedRawCode, "answer++"));
        }

        assertTrue(hasLastSeenContribution,
                filename + " must include the last-seen contribution-counting route");
        assertTrue(hasShrinkingWindowCounts,
                filename + " must include the shrinking-window counts route");
        assertTrue(hasInclusionExclusion,
                filename + " must include the segment inclusion-exclusion route");
        assertTrue(hasEnumerationBaseline,
                filename + " must include the enumeration baseline route");
    }

