    private static void assertMaximumScoreMultipliersSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 4,
                filename + " should teach bottom-up table DP, memoized endpoint choice, rolling one-dimensional DP, "
                        + "and forward layer DP routes");

        boolean hasBottomUpTable = false;
        boolean hasMemoizedChoice = false;
        boolean hasRollingDp = false;
        boolean hasForwardLayerDp = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasBottomUpTable = hasBottomUpTable
                    || ((searchable.contains("bottom") || searchable.contains("table"))
                    && containsNormalizedCode(normalizedRawCode, "int[][] dp = new int[m + 1][m + 1]")
                    && containsNormalizedCode(normalizedRawCode,
                    "for (int operation = m - 1; operation >= 0; operation--)")
                    && containsNormalizedCode(normalizedRawCode,
                    "int rightIndex = n - 1 - (operation - leftTaken)")
                    && containsNormalizedCode(normalizedRawCode,
                    "dp[operation][leftTaken] = Math.max(takeLeft, takeRight)"));
            hasMemoizedChoice = hasMemoizedChoice
                    || ((searchable.contains("memoized") || searchable.contains("top-down"))
                    && containsNormalizedCode(normalizedRawCode, "private Integer[][] memo")
                    && containsNormalizedCode(normalizedRawCode, "return dfs(0, 0)")
                    && containsNormalizedCode(normalizedRawCode, "private int dfs(int operation, int leftTaken)")
                    && containsNormalizedCode(normalizedRawCode, "memo[operation][leftTaken] != null")
                    && containsNormalizedCode(normalizedRawCode, "dfs(operation + 1, leftTaken + 1)"));
            hasRollingDp = hasRollingDp
                    || ((searchable.contains("rolling") || searchable.contains("one-dimensional"))
                    && containsNormalizedCode(normalizedRawCode, "int[] next = new int[m + 1]")
                    && containsNormalizedCode(normalizedRawCode, "int[] current = new int[m + 1]")
                    && containsNormalizedCode(normalizedRawCode,
                    "current[leftTaken] = Math.max(takeLeft, takeRight)")
                    && containsNormalizedCode(normalizedRawCode, "next = current"));
            hasForwardLayerDp = hasForwardLayerDp
                    || ((searchable.contains("forward") || searchable.contains("layer"))
                    && containsNormalizedCode(normalizedRawCode, "java.util.Arrays.fill(current, unreachable)")
                    && containsNormalizedCode(normalizedRawCode, "current[0] = 0")
                    && containsNormalizedCode(normalizedRawCode,
                    "for (int operation = 0; operation < m; operation++)")
                    && containsNormalizedCode(normalizedRawCode,
                    "next[leftTaken + 1] = Math.max(next[leftTaken + 1], score + multiplier * nums[leftTaken])")
                    && containsNormalizedCode(normalizedRawCode,
                    "next[leftTaken] = Math.max(next[leftTaken], score + multiplier * nums[rightIndex])"));
        }

        assertTrue(hasBottomUpTable,
                filename + " must include the bottom-up choice-table route");
        assertTrue(hasMemoizedChoice,
                filename + " must include the memoized endpoint-choice route");
        assertTrue(hasRollingDp,
                filename + " must include the rolling one-dimensional DP route");
        assertTrue(hasForwardLayerDp,
                filename + " must include the forward layer-DP route");
    }

