    private static void assertScrambleStringSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 4,
                filename + " should teach bottom-up interval DP, substring memoization, index-prefix DFS, "
                        + "and prefix-pruned bottom-up DP routes");

        boolean hasBottomUpIntervalDp = false;
        boolean hasSubstringMemoization = false;
        boolean hasIndexPrefixDfs = false;
        boolean hasPrefixPrunedBottomUpDp = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasBottomUpIntervalDp = hasBottomUpIntervalDp
                    || ((searchable.contains("3d") || searchable.contains("bottom-up")
                    || searchable.contains("interval dp"))
                    && containsNormalizedCode(normalizedRawCode,
                    "boolean[][][] dp = new boolean[n + 1][n][n]")
                    && containsNormalizedCode(normalizedRawCode,
                    "dp[1][i][j] = s1.charAt(i) == s2.charAt(j)")
                    && containsNormalizedCode(normalizedRawCode,
                    "dp[k][i][j] && dp[len - k][i + k][j + k]")
                    && containsNormalizedCode(normalizedRawCode,
                    "dp[k][i][j + len - k] && dp[len - k][i + k][j]"));
            hasSubstringMemoization = hasSubstringMemoization
                    || ((searchable.contains("recursive") || searchable.contains("memoization"))
                    && containsNormalizedCode(normalizedRawCode, "Map<String, Boolean> memo")
                    && containsNormalizedCode(normalizedRawCode, "String key = s1 + \"#\" + s2")
                    && containsNormalizedCode(normalizedRawCode,
                    "solve(s1.substring(0, i), s2.substring(0, i))")
                    && containsNormalizedCode(normalizedRawCode,
                    "solve(s1.substring(0, i), s2.substring(n - i))"));
            hasIndexPrefixDfs = hasIndexPrefixDfs
                    || ((searchable.contains("prefix") && searchable.contains("dfs"))
                    && containsNormalizedCode(normalizedRawCode, "Boolean[][][] memo")
                    && containsNormalizedCode(normalizedRawCode, "return dfs(0, 0, n)")
                    && containsNormalizedCode(normalizedRawCode, "a.regionMatches(i, b, j, len)")
                    && containsNormalizedCode(normalizedRawCode, "if (!sameCounts(i, j, len))"));
            hasPrefixPrunedBottomUpDp = hasPrefixPrunedBottomUpDp
                    || ((searchable.contains("prefix-pruned") || searchable.contains("prefix")
                    && searchable.contains("bottom-up"))
                    && containsNormalizedCode(normalizedRawCode, "int[][] prefA = buildPrefix(s1)")
                    && containsNormalizedCode(normalizedRawCode, "int[][] prefB = buildPrefix(s2)")
                    && containsNormalizedCode(normalizedRawCode,
                    "if (!sameCounts(prefA, prefB, i, j, len)) continue")
                    && containsNormalizedCode(normalizedRawCode, "for (int split = 1; split < len; split++)")
                    && containsNormalizedCode(normalizedRawCode, "dp[len][i][j] = true"));
        }

        assertTrue(hasBottomUpIntervalDp,
                filename + " must include the bottom-up 3D interval-DP route");
        assertTrue(hasSubstringMemoization,
                filename + " must include the substring memoization route");
        assertTrue(hasIndexPrefixDfs,
                filename + " must include the index-prefix DFS route");
        assertTrue(hasPrefixPrunedBottomUpDp,
                filename + " must include the prefix-pruned bottom-up DP route");
    }

