    private static void assertRecoverBinarySearchTreeSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 4,
                filename + " should teach recursive inorder, Morris inorder, iterative-stack inorder, "
                        + "and materialized inorder-list repair routes");

        boolean hasRecursiveInorder = false;
        boolean hasMorrisInorder = false;
        boolean hasIterativeStackInorder = false;
        boolean hasNodeListRepair = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasRecursiveInorder = hasRecursiveInorder
                    || ((searchable.contains("recursive") || searchable.contains("inorder traversal"))
                    && containsNormalizedCode(normalizedRawCode, "private TreeNode first, second, prev")
                    && containsNormalizedCode(normalizedRawCode, "inorder(node.left)")
                    && containsNormalizedCode(normalizedRawCode, "if (prev != null && prev.val > node.val)")
                    && containsNormalizedCode(normalizedRawCode, "if (first == null) first = prev")
                    && containsNormalizedCode(normalizedRawCode, "second = node")
                    && containsNormalizedCode(normalizedRawCode, "int temp = first.val"));
            hasMorrisInorder = hasMorrisInorder
                    || (searchable.contains("morris")
                    && containsNormalizedCode(normalizedRawCode, "TreeNode curr = root")
                    && containsNormalizedCode(normalizedRawCode, "while (curr != null)")
                    && containsNormalizedCode(normalizedRawCode, "TreeNode pred = curr.left")
                    && containsNormalizedCode(normalizedRawCode,
                    "while (pred.right != null && pred.right != curr)")
                    && containsNormalizedCode(normalizedRawCode, "pred.right = curr")
                    && containsNormalizedCode(normalizedRawCode, "pred.right = null"));
            hasIterativeStackInorder = hasIterativeStackInorder
                    || ((searchable.contains("stack") || searchable.contains("iterative"))
                    && containsNormalizedCode(normalizedRawCode,
                    "java.util.Deque<TreeNode> stack = new java.util.ArrayDeque<>()")
                    && containsNormalizedCode(normalizedRawCode, "while (node != null || !stack.isEmpty())")
                    && containsNormalizedCode(normalizedRawCode, "stack.push(node)")
                    && containsNormalizedCode(normalizedRawCode, "node = stack.pop()")
                    && containsNormalizedCode(normalizedRawCode, "node = node.right"));
            hasNodeListRepair = hasNodeListRepair
                    || ((searchable.contains("list") || searchable.contains("materializing")
                    || searchable.contains("materialized"))
                    && containsNormalizedCode(normalizedRawCode,
                    "java.util.List<TreeNode> nodes = new java.util.ArrayList<>()")
                    && containsNormalizedCode(normalizedRawCode, "inorder(root, nodes)")
                    && containsNormalizedCode(normalizedRawCode, "nodes.add(node)")
                    && containsNormalizedCode(normalizedRawCode, "for (int i = 1; i < nodes.size(); i++)")
                    && containsNormalizedCode(normalizedRawCode, "TreeNode prev = nodes.get(i - 1)")
                    && containsNormalizedCode(normalizedRawCode, "TreeNode cur = nodes.get(i)"));
        }

        assertTrue(hasRecursiveInorder,
                filename + " must include the recursive inorder inversion route");
        assertTrue(hasMorrisInorder,
                filename + " must include the Morris inorder route");
        assertTrue(hasIterativeStackInorder,
                filename + " must include the iterative stack inorder route");
        assertTrue(hasNodeListRepair,
                filename + " must include the materialized inorder node-list repair route");
    }

