    private static void assertBestTimeStockIIISolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 4,
                filename + " should teach four-state compression, left-right split DP, "
                        + "general hold/cash transaction DP, and best-difference transaction DP");

        boolean hasFourState = false;
        boolean hasLeftRight = false;
        boolean hasGeneralHoldCash = false;
        boolean hasBestDifference = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasFourState = hasFourState
                    || ((searchable.contains("four") || searchable.contains("state machine"))
                    && containsNormalizedCode(normalizedRawCode, "int buy1 = Integer.MIN_VALUE, sell1 = 0")
                    && containsNormalizedCode(normalizedRawCode, "int buy2 = Integer.MIN_VALUE, sell2 = 0")
                    && containsNormalizedCode(normalizedRawCode, "buy1 = Math.max(buy1, -price)")
                    && containsNormalizedCode(normalizedRawCode, "sell1 = Math.max(sell1, buy1 + price)")
                    && containsNormalizedCode(normalizedRawCode, "buy2 = Math.max(buy2, sell1 - price)")
                    && containsNormalizedCode(normalizedRawCode, "sell2 = Math.max(sell2, buy2 + price)"));
            hasLeftRight = hasLeftRight
                    || ((searchable.contains("left") || searchable.contains("split"))
                    && containsNormalizedCode(normalizedRawCode, "int[] left = new int[n]")
                    && containsNormalizedCode(normalizedRawCode, "int[] right = new int[n]")
                    && containsNormalizedCode(normalizedRawCode,
                    "minPrice = Math.min(minPrice, prices[i])")
                    && containsNormalizedCode(normalizedRawCode,
                    "left[i] = Math.max(left[i - 1], prices[i] - minPrice)")
                    && containsNormalizedCode(normalizedRawCode,
                    "right[i] = Math.max(right[i + 1], maxPrice - prices[i])")
                    && containsNormalizedCode(normalizedRawCode, "left[i] + right[i]"));
            hasGeneralHoldCash = hasGeneralHoldCash
                    || ((searchable.contains("hold") || searchable.contains("cash")
                    || searchable.contains("general"))
                    && containsNormalizedCode(normalizedRawCode, "int[] hold = new int[3]")
                    && containsNormalizedCode(normalizedRawCode, "int[] cash = new int[3]")
                    && containsNormalizedCode(normalizedRawCode,
                    "java.util.Arrays.fill(hold, Integer.MIN_VALUE / 4)")
                    && containsNormalizedCode(normalizedRawCode, "for (int t = 1; t <= 2; t++)")
                    && containsNormalizedCode(normalizedRawCode,
                    "hold[t] = Math.max(hold[t], cash[t - 1] - price)")
                    && containsNormalizedCode(normalizedRawCode,
                    "cash[t] = Math.max(cash[t], hold[t] + price)"));
            hasBestDifference = hasBestDifference
                    || ((searchable.contains("best difference") || searchable.contains("dp[t][day]"))
                    && containsNormalizedCode(normalizedRawCode, "int[][] dp = new int[3][n]")
                    && containsNormalizedCode(normalizedRawCode, "int bestPrevious = -prices[0]")
                    && containsNormalizedCode(normalizedRawCode,
                    "dp[t][day] = Math.max(dp[t][day - 1], prices[day] + bestPrevious)")
                    && containsNormalizedCode(normalizedRawCode,
                    "bestPrevious = Math.max(bestPrevious, dp[t - 1][day - 1] - prices[day])")
                    && containsNormalizedCode(normalizedRawCode, "return dp[2][n - 1]"));
        }

        assertTrue(hasFourState,
                filename + " must include the four-state compressed transaction route");
        assertTrue(hasLeftRight,
                filename + " must include the left-right split DP route");
        assertTrue(hasGeneralHoldCash,
                filename + " must include the general hold/cash transaction DP route");
        assertTrue(hasBestDifference,
                filename + " must include the best-difference transaction DP route");
    }

