    private static void assertBestTimeStockIVSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 4,
                filename + " should teach buy/sell state arrays, 2D best-difference DP, "
                        + "memoized buy/sell DFS, and local/global profit DP");

        boolean hasBuySellArrays = false;
        boolean hasBestDifferenceTable = false;
        boolean hasMemoizedDfs = false;
        boolean hasLocalGlobal = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasBuySellArrays = hasBuySellArrays
                    || ((searchable.contains("buy") || searchable.contains("state arrays"))
                    && containsNormalizedCode(normalizedRawCode, "if (k >= n / 2)")
                    && containsNormalizedCode(normalizedRawCode, "int[] buy = new int[k]")
                    && containsNormalizedCode(normalizedRawCode, "int[] sell = new int[k]")
                    && containsNormalizedCode(normalizedRawCode,
                    "java.util.Arrays.fill(buy, Integer.MIN_VALUE / 4)")
                    && containsNormalizedCode(normalizedRawCode,
                    "buy[i] = Math.max(buy[i], (i == 0 ? 0 : sell[i - 1]) - price)")
                    && containsNormalizedCode(normalizedRawCode,
                    "sell[i] = Math.max(sell[i], buy[i] + price)"));
            hasBestDifferenceTable = hasBestDifferenceTable
                    || ((searchable.contains("best difference") || searchable.contains("2d dp"))
                    && containsNormalizedCode(normalizedRawCode, "int[][] dp = new int[k + 1][n]")
                    && containsNormalizedCode(normalizedRawCode, "int maxDiff = -prices[0]")
                    && containsNormalizedCode(normalizedRawCode,
                    "dp[t][i] = Math.max(dp[t][i - 1], prices[i] + maxDiff)")
                    && containsNormalizedCode(normalizedRawCode,
                    "maxDiff = Math.max(maxDiff, dp[t - 1][i] - prices[i])")
                    && containsNormalizedCode(normalizedRawCode, "return dp[k][n - 1]"));
            hasMemoizedDfs = hasMemoizedDfs
                    || ((searchable.contains("memo") || searchable.contains("dfs"))
                    && containsNormalizedCode(normalizedRawCode,
                    "Integer[][][] memo = new Integer[prices.length][k + 1][2]")
                    && containsNormalizedCode(normalizedRawCode, "return dfs(0, k, 0, prices, memo)")
                    && containsNormalizedCode(normalizedRawCode, "if (holding == 1)")
                    && containsNormalizedCode(normalizedRawCode,
                    "prices[day] + dfs(day + 1, remaining - 1, 0, prices, memo)")
                    && containsNormalizedCode(normalizedRawCode,
                    "-prices[day] + dfs(day + 1, remaining, 1, prices, memo)")
                    && containsNormalizedCode(normalizedRawCode,
                    "memo[day][remaining][holding] = best"));
            hasLocalGlobal = hasLocalGlobal
                    || ((searchable.contains("local") || searchable.contains("global"))
                    && containsNormalizedCode(normalizedRawCode, "int[] local = new int[k + 1]")
                    && containsNormalizedCode(normalizedRawCode, "int[] global = new int[k + 1]")
                    && containsNormalizedCode(normalizedRawCode,
                    "int diff = prices[day] - prices[day - 1]")
                    && containsNormalizedCode(normalizedRawCode, "for (int t = k; t >= 1; t--)")
                    && containsNormalizedCode(normalizedRawCode,
                    "local[t] = Math.max(global[t - 1] + Math.max(diff, 0), local[t] + diff)")
                    && containsNormalizedCode(normalizedRawCode,
                    "global[t] = Math.max(global[t], local[t])"));
        }

        assertTrue(hasBuySellArrays,
                filename + " must include the buy/sell state-array route");
        assertTrue(hasBestDifferenceTable,
                filename + " must include the 2D best-difference DP table route");
        assertTrue(hasMemoizedDfs,
                filename + " must include the memoized buy/sell DFS route");
        assertTrue(hasLocalGlobal,
                filename + " must include the local/global profit DP route");
    }

