    private static void assertWordPatternBijectionSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 4,
                filename + " should teach two directional maps, mapping plus used-word set, "
                        + "first-occurrence encoding, and unique-pair cardinality routes");

        boolean hasTwoMaps = false;
        boolean hasMapAndSet = false;
        boolean hasFirstPositions = false;
        boolean hasPairCardinality = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasTwoMaps = hasTwoMaps
                    || ((searchable.contains("two") || searchable.contains("directional"))
                    && containsNormalizedCode(normalizedRawCode,
                    "java.util.Map<Character,String> charToWord = new java.util.HashMap<>()")
                    && containsNormalizedCode(normalizedRawCode,
                    "java.util.Map<String,Character> wordToChar = new java.util.HashMap<>()")
                    && containsNormalizedCode(normalizedRawCode,
                    "if (charToWord.containsKey(ch) && !charToWord.get(ch).equals(word)) return false")
                    && containsNormalizedCode(normalizedRawCode,
                    "if (wordToChar.containsKey(word) && wordToChar.get(word) != ch) return false")
                    && containsNormalizedCode(normalizedRawCode, "charToWord.put(ch, word)")
                    && containsNormalizedCode(normalizedRawCode, "wordToChar.put(word, ch)"));
            hasMapAndSet = hasMapAndSet
                    || ((searchable.contains("set") || searchable.contains("used"))
                    && containsNormalizedCode(normalizedRawCode,
                    "java.util.Map<Character,String> mapping = new java.util.HashMap<>()")
                    && containsNormalizedCode(normalizedRawCode,
                    "java.util.Set<String> usedWords = new java.util.HashSet<>()")
                    && containsNormalizedCode(normalizedRawCode, "if (mapping.containsKey(ch))")
                    && containsNormalizedCode(normalizedRawCode,
                    "if (!mapping.get(ch).equals(word)) return false")
                    && containsNormalizedCode(normalizedRawCode,
                    "if (usedWords.contains(word)) return false")
                    && containsNormalizedCode(normalizedRawCode, "usedWords.add(word)"));
            hasFirstPositions = hasFirstPositions
                    || ((searchable.contains("first") || searchable.contains("position"))
                    && containsNormalizedCode(normalizedRawCode,
                    "java.util.Map<Object,Integer> first = new java.util.HashMap<>()")
                    && containsNormalizedCode(normalizedRawCode,
                    "Integer patternFirst = first.putIfAbsent(pattern.charAt(i), i)")
                    && containsNormalizedCode(normalizedRawCode,
                    "Integer wordFirst = first.putIfAbsent(words[i], i)")
                    && containsNormalizedCode(normalizedRawCode,
                    "if (!java.util.Objects.equals(patternFirst, wordFirst)) return false"));
            hasPairCardinality = hasPairCardinality
                    || ((searchable.contains("cardinality") || searchable.contains("pair"))
                    && containsNormalizedCode(normalizedRawCode,
                    "java.util.Set<Character> chars = new java.util.HashSet<>()")
                    && containsNormalizedCode(normalizedRawCode,
                    "java.util.Set<String> seenWords = new java.util.HashSet<>()")
                    && containsNormalizedCode(normalizedRawCode,
                    "java.util.Set<String> pairs = new java.util.HashSet<>()")
                    && containsNormalizedCode(normalizedRawCode, "pairs.add(ch + \"\\u0001\" + words[i])")
                    && containsNormalizedCode(normalizedRawCode,
                    "return chars.size() == seenWords.size() && chars.size() == pairs.size()"));
        }

        assertTrue(hasTwoMaps,
                filename + " must include the two-directional-map route");
        assertTrue(hasMapAndSet,
                filename + " must include the mapping plus used-word set route");
        assertTrue(hasFirstPositions,
                filename + " must include the first-occurrence encoding route");
        assertTrue(hasPairCardinality,
                filename + " must include the unique-pair cardinality route");
    }

