    private static void assertAlternatingDigitSumSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 4,
                filename + " should teach string scanning, numeric divisor scanning, digit buffering, "
                        + "and right-to-left parity correction routes");

        boolean hasStringScan = false;
        boolean hasDivisorScan = false;
        boolean hasDigitBuffer = false;
        boolean hasRightToLeftParity = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasStringScan = hasStringScan
                    || ((searchable.contains("string") || searchable.contains("character"))
                    && containsNormalizedCode(normalizedRawCode, "String digits = String.valueOf(n)")
                    && containsNormalizedCode(normalizedRawCode, "for (int i = 0; i < digits.length(); i++)")
                    && containsNormalizedCode(normalizedRawCode, "int digit = digits.charAt(i) - '0'")
                    && containsNormalizedCode(normalizedRawCode, "ans += (i % 2 == 0 ? digit : -digit)"));
            hasDivisorScan = hasDivisorScan
                    || ((searchable.contains("divisor") || searchable.contains("numeric"))
                    && containsNormalizedCode(normalizedRawCode, "int divisor = 1")
                    && containsNormalizedCode(normalizedRawCode, "while (n / divisor >= 10)")
                    && containsNormalizedCode(normalizedRawCode, "int digit = n / divisor")
                    && containsNormalizedCode(normalizedRawCode, "n %= divisor")
                    && containsNormalizedCode(normalizedRawCode, "divisor /= 10")
                    && containsNormalizedCode(normalizedRawCode, "sign = -sign"));
            hasDigitBuffer = hasDigitBuffer
                    || ((searchable.contains("buffer") || searchable.contains("array"))
                    && containsNormalizedCode(normalizedRawCode, "int[] digits = new int[10]")
                    && containsNormalizedCode(normalizedRawCode, "digits[count++] = n % 10")
                    && containsNormalizedCode(normalizedRawCode, "for (int i = count - 1; i >= 0; i--)")
                    && containsNormalizedCode(normalizedRawCode, "ans += sign * digits[i]"));
            hasRightToLeftParity = hasRightToLeftParity
                    || ((searchable.contains("right") || searchable.contains("parity"))
                    && containsNormalizedCode(normalizedRawCode, "ans += sign * (n % 10)")
                    && containsNormalizedCode(normalizedRawCode, "count++")
                    && containsNormalizedCode(normalizedRawCode, "return count % 2 == 0 ? -ans : ans"));
        }

        assertTrue(hasStringScan,
                filename + " must include the string digit scan route");
        assertTrue(hasDivisorScan,
                filename + " must include the numeric divisor scan route");
        assertTrue(hasDigitBuffer,
                filename + " must include the digit buffer route");
        assertTrue(hasRightToLeftParity,
                filename + " must include the right-to-left parity correction route");
    }

