    private static void assertMaximumGapSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 4,
                filename + " should teach pigeonhole bucket sort, decimal LSD radix sort, "
                        + "base-256 fixed-pass radix sort, and MSD bit-partition gap recursion");

        boolean hasPigeonholeBucket = false;
        boolean hasDecimalRadix = false;
        boolean hasBase256Radix = false;
        boolean hasMsdBitPartition = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasPigeonholeBucket = hasPigeonholeBucket
                    || ((searchable.contains("bucket") || searchable.contains("pigeonhole"))
                    && containsNormalizedCode(normalizedRawCode,
                    "int bucketSize = Math.max(1, (int) Math.ceil((double) (max - min) / (n - 1)))")
                    && containsNormalizedCode(normalizedRawCode,
                    "int bucketCount = (max - min) / bucketSize + 1")
                    && containsNormalizedCode(normalizedRawCode,
                    "boolean[] used = new boolean[bucketCount]")
                    && containsNormalizedCode(normalizedRawCode,
                    "int index = (value - min) / bucketSize")
                    && containsNormalizedCode(normalizedRawCode,
                    "best = Math.max(best, bucketMin[i] - previousMax)"));
            hasDecimalRadix = hasDecimalRadix
                    || ((searchable.contains("decimal") || searchable.contains("lsd"))
                    && containsNormalizedCode(normalizedRawCode, "for (long exp = 1; exp <= max; exp *= 10)")
                    && containsNormalizedCode(normalizedRawCode, "int[] count = new int[10]")
                    && containsNormalizedCode(normalizedRawCode,
                    "count[(int) ((value / exp) % 10)]++")
                    && containsNormalizedCode(normalizedRawCode,
                    "int digit = (int) ((nums[i] / exp) % 10)")
                    && containsNormalizedCode(normalizedRawCode,
                    "System.arraycopy(buffer, 0, nums, 0, n)"));
            hasBase256Radix = hasBase256Radix
                    || ((searchable.contains("256") || searchable.contains("byte"))
                    && containsNormalizedCode(normalizedRawCode,
                    "for (int shift = 0; shift < 32; shift += 8)")
                    && containsNormalizedCode(normalizedRawCode, "int[] count = new int[256]")
                    && containsNormalizedCode(normalizedRawCode,
                    "count[(value >>> shift) & 255]++")
                    && containsNormalizedCode(normalizedRawCode,
                    "buffer[--count[(value >>> shift) & 255]] = value")
                    && containsNormalizedCode(normalizedRawCode, "int[] temp = arr"));
            hasMsdBitPartition = hasMsdBitPartition
                    || ((searchable.contains("msd") || searchable.contains("bit"))
                    && containsNormalizedCode(normalizedRawCode,
                    "return maxGap(nums, 0, nums.length - 1, 30)")
                    && containsNormalizedCode(normalizedRawCode,
                    "private int maxGap(int[] nums, int lo, int hi, int bit)")
                    && containsNormalizedCode(normalizedRawCode,
                    "while (left <= right && ((nums[left] >>> bit) & 1) == 0)")
                    && containsNormalizedCode(normalizedRawCode,
                    "while (left <= right && ((nums[right] >>> bit) & 1) == 1)")
                    && containsNormalizedCode(normalizedRawCode,
                    "int crossGap = rightMin - leftMax")
                    && containsNormalizedCode(normalizedRawCode,
                    "return Math.max(crossGap, Math.max(leftGap, rightGap))"));
        }

        assertTrue(hasPigeonholeBucket,
                filename + " must include the pigeonhole bucket-sort route");
        assertTrue(hasDecimalRadix,
                filename + " must include the decimal LSD radix-sort route");
        assertTrue(hasBase256Radix,
                filename + " must include the base-256 fixed-pass radix-sort route");
        assertTrue(hasMsdBitPartition,
                filename + " must include the MSD bit-partition gap route");
    }

