    private static void assertShortestPalindromeSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 4,
                filename + " should teach KMP failure function, Z-function border search, "
                        + "Manacher prefix radius, and direct palindrome-prefix checking");

        boolean hasKmpFailure = false;
        boolean hasZFunction = false;
        boolean hasManacher = false;
        boolean hasPrefixCheck = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasKmpFailure = hasKmpFailure
                    || ((searchable.contains("kmp") || searchable.contains("failure"))
                    && containsNormalizedCode(normalizedRawCode,
                    "String reversed = new StringBuilder(s).reverse().toString()")
                    && containsNormalizedCode(normalizedRawCode, "String combined = s + \"{\" + reversed")
                    && containsNormalizedCode(normalizedRawCode, "int[] failure = new int[combined.length()]")
                    && containsNormalizedCode(normalizedRawCode, "matched = failure[matched - 1]")
                    && containsNormalizedCode(normalizedRawCode,
                    "int prefixLength = combined.isEmpty() ? 0 : failure[combined.length() - 1]")
                    && containsNormalizedCode(normalizedRawCode,
                    "return reversed.substring(0, s.length() - prefixLength) + s"));
            hasZFunction = hasZFunction
                    || ((searchable.contains("z-function") || searchable.contains("z function"))
                    && containsNormalizedCode(normalizedRawCode, "int[] z = zFunction(combined)")
                    && containsNormalizedCode(normalizedRawCode,
                    "if (i + z[i] == combined.length())")
                    && containsNormalizedCode(normalizedRawCode,
                    "private int[] zFunction(String text)")
                    && containsNormalizedCode(normalizedRawCode,
                    "z[i] = Math.min(right - i + 1, z[i - left])"));
            hasManacher = hasManacher
                    || ((searchable.contains("manacher") || searchable.contains("radius"))
                    && containsNormalizedCode(normalizedRawCode, "String transformed = transform(s)")
                    && containsNormalizedCode(normalizedRawCode, "int[] radius = new int[transformed.length()]")
                    && containsNormalizedCode(normalizedRawCode, "int mirror = 2 * center - i")
                    && containsNormalizedCode(normalizedRawCode, "if (i - radius[i] == 1)")
                    && containsNormalizedCode(normalizedRawCode, "private String transform(String s)"));
            hasPrefixCheck = hasPrefixCheck
                    || ((searchable.contains("prefix") || searchable.contains("baseline"))
                    && containsNormalizedCode(normalizedRawCode,
                    "for (int len = s.length(); len >= 0; len--)")
                    && containsNormalizedCode(normalizedRawCode,
                    "if (isPalindromePrefix(s, len))")
                    && containsNormalizedCode(normalizedRawCode,
                    "return new StringBuilder(s.substring(len)).reverse().toString() + s")
                    && containsNormalizedCode(normalizedRawCode,
                    "private boolean isPalindromePrefix(String s, int len)"));
        }

        assertTrue(hasKmpFailure,
                filename + " must include the KMP failure-function route");
        assertTrue(hasZFunction,
                filename + " must include the Z-function border-search route");
        assertTrue(hasManacher,
                filename + " must include the Manacher prefix-radius route");
        assertTrue(hasPrefixCheck,
                filename + " must include the direct palindrome-prefix checking route");
    }

