    private static void assertRemoveBoxesSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " should teach left-carry memoized 3D DP, right-carry memoized interval DP, "
                        + "bottom-up 3D interval DP, run-length encoded interval DP, and same-color jump-list memoization");

        boolean hasLeftCarryMemo = false;
        boolean hasRightCarryMemo = false;
        boolean hasBottomUpDp = false;
        boolean hasRunLengthEncodedDp = false;
        boolean hasSameColorJumpList = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasLeftCarryMemo = hasLeftCarryMemo
                    || ((searchable.contains("left") || searchable.contains("3d"))
                    && containsNormalizedCode(normalizedRawCode, "return dp(boxes, 0, boxes.length - 1, 0)")
                    && containsNormalizedCode(normalizedRawCode,
                    "while (left + 1 <= right && boxes[left + 1] == boxes[left])")
                    && containsNormalizedCode(normalizedRawCode,
                    "dp(boxes, left + 1, middle - 1, 0) + dp(boxes, middle, right, carry + 1)"));
            hasRightCarryMemo = hasRightCarryMemo
                    || ((searchable.contains("right") || searchable.contains("symmetric"))
                    && containsNormalizedCode(normalizedRawCode, "while (right > left && boxes[right] == boxes[right - 1])")
                    && containsNormalizedCode(normalizedRawCode,
                    "dp(left, mid, carry + 1) + dp(mid + 1, right - 1, 0)")
                    && containsNormalizedCode(normalizedRawCode, "memo[left][originalRight][originalCarry]"));
            hasBottomUpDp = hasBottomUpDp
                    || ((searchable.contains("bottom-up") || searchable.contains("iterative"))
                    && containsNormalizedCode(normalizedRawCode, "int[][][] dp = new int[n][n][n + 2]")
                    && containsNormalizedCode(normalizedRawCode, "for (int length = 1; length <= n; length++)")
                    && containsNormalizedCode(normalizedRawCode, "dp[left][right][carry] = best"));
            hasRunLengthEncodedDp = hasRunLengthEncodedDp
                    || ((searchable.contains("run-length") || searchable.contains("compress"))
                    && containsNormalizedCode(normalizedRawCode, "colors = new int[n]")
                    && containsNormalizedCode(normalizedRawCode, "counts = new int[n]")
                    && containsNormalizedCode(normalizedRawCode, "return solve(0, groups - 1, 0)")
                    && containsNormalizedCode(normalizedRawCode, "int mergedCount = counts[right] + carry"));
            hasSameColorJumpList = hasSameColorJumpList
                    || ((searchable.contains("jump") || searchable.contains("position"))
                    && containsNormalizedCode(normalizedRawCode, "Map<Integer, List<Integer>> positions")
                    && containsNormalizedCode(normalizedRawCode, "for (int middle : positions.get(boxes[left]))")
                    && containsNormalizedCode(normalizedRawCode, "if (middle <= left || middle > right) continue"));
        }

        assertTrue(hasLeftCarryMemo,
                filename + " must include the left-carry memoized 3D DP route");
        assertTrue(hasRightCarryMemo,
                filename + " must include the right-carry memoized interval DP route");
        assertTrue(hasBottomUpDp,
                filename + " must include the bottom-up 3D interval DP route");
        assertTrue(hasRunLengthEncodedDp,
                filename + " must include the run-length encoded interval DP route");
        assertTrue(hasSameColorJumpList,
                filename + " must include the same-color jump-list memoization route");
    }

