    private static void assertSelfCrossingSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " Self Crossing should teach formula cases, segment-history geometry, "
                        + "constant-space ring-buffer geometry, expanding-to-contracting state, and reverse-path scan");

        boolean hasThreeLocalCases = false;
        boolean hasSegmentHistoryGeometry = false;
        boolean hasRingBufferGeometry = false;
        boolean hasExpandingContractingState = false;
        boolean hasReversePathScan = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasThreeLocalCases = hasThreeLocalCases
                    || ((searchable.contains("three") || searchable.contains("local crossing"))
                    && containsNormalizedCode(normalizedRawCode, "crossesFourthWithFirst")
                    && containsNormalizedCode(normalizedRawCode, "touchesFifthWithFirst")
                    && containsNormalizedCode(normalizedRawCode, "crossesSixthWithFirst"));
            hasSegmentHistoryGeometry = hasSegmentHistoryGeometry
                    || ((searchable.contains("segment history") || searchable.contains("geometry"))
                    && containsNormalizedCode(normalizedRawCode, "long[][] segments = new long[n][4]")
                    && containsNormalizedCode(normalizedRawCode,
                    "for (int j = Math.max(0, i - 5); j <= i - 3; j++)")
                    && containsNormalizedCode(normalizedRawCode, "intersects(segments[i], segments[j])"));
            hasRingBufferGeometry = hasRingBufferGeometry
                    || ((searchable.contains("ring buffer") || searchable.contains("six-segment"))
                    && containsNormalizedCode(normalizedRawCode, "long[][] window = new long[6][4]")
                    && containsNormalizedCode(normalizedRawCode, "for (int back = 3; back <= 5; back++)")
                    && containsNormalizedCode(normalizedRawCode, "window[i % 6] = current"));
            hasExpandingContractingState = hasExpandingContractingState
                    || ((searchable.contains("expanding") || searchable.contains("contracting"))
                    && containsNormalizedCode(normalizedRawCode, "while (i < d.length && d[i] > d[i - 2])")
                    && containsNormalizedCode(normalizedRawCode, "d[i - 1] -= d[i - 3]")
                    && containsNormalizedCode(normalizedRawCode, "if (d[i] >= d[i - 2]) return true"));
            hasReversePathScan = hasReversePathScan
                    || ((searchable.contains("reverse") || searchable.contains("path local scan"))
                    && containsNormalizedCode(normalizedRawCode, "int[] reversed = new int[n]")
                    && containsNormalizedCode(normalizedRawCode, "reversed[i] = distance[n - 1 - i]")
                    && containsNormalizedCode(normalizedRawCode, "return hasLocalCrossing(reversed)"));
        }

        assertTrue(hasThreeLocalCases,
                filename + " must include the three local crossing cases route");
        assertTrue(hasSegmentHistoryGeometry,
                filename + " must include the segment-history geometry route");
        assertTrue(hasRingBufferGeometry,
                filename + " must include the constant-space ring-buffer geometry route");
        assertTrue(hasExpandingContractingState,
                filename + " must include the expanding-to-contracting state route");
        assertTrue(hasReversePathScan,
                filename + " must include the reverse-path local scan route");
    }

