    private static void assertDataStreamIntervalsSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " Data Stream as Disjoint Intervals should teach TreeMap interval merge, "
                        + "bounded BitSet scan, TreeSet value scan, boundary maps, and disjoint-set components");

        boolean hasTreeMapIntervalMerge = false;
        boolean hasBoundedBitSetScan = false;
        boolean hasTreeSetValueScan = false;
        boolean hasBoundaryMaps = false;
        boolean hasDisjointSetComponents = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasTreeMapIntervalMerge = hasTreeMapIntervalMerge
                    || ((searchable.contains("treemap") || searchable.contains("interval"))
                    && containsNormalizedCode(normalizedRawCode,
                    "TreeMap<Integer, int[]> intervals = new TreeMap<>()")
                    && containsNormalizedCode(normalizedRawCode,
                    "Map.Entry<Integer, int[]> left = intervals.floorEntry(value)")
                    && containsNormalizedCode(normalizedRawCode, "intervals.ceilingEntry(value)"));
            hasBoundedBitSetScan = hasBoundedBitSetScan
                    || ((searchable.contains("bitset") || searchable.contains("bounded"))
                    && containsNormalizedCode(normalizedRawCode, "BitSet seen = new BitSet(LIMIT + 1)")
                    && containsNormalizedCode(normalizedRawCode, "seen.nextSetBit(0)")
                    && containsNormalizedCode(normalizedRawCode, "seen.nextClearBit(start)"));
            hasTreeSetValueScan = hasTreeSetValueScan
                    || ((searchable.contains("treeset") || searchable.contains("value scan"))
                    && containsNormalizedCode(normalizedRawCode, "TreeSet<Integer> values = new TreeSet<>()")
                    && containsNormalizedCode(normalizedRawCode, "values.add(value)")
                    && containsNormalizedCode(normalizedRawCode, "for (int value : values)"));
            hasBoundaryMaps = hasBoundaryMaps
                    || ((searchable.contains("boundary") || searchable.contains("ordered starts"))
                    && containsNormalizedCode(normalizedRawCode,
                    "Map<Integer, Integer> startToEnd = new HashMap<>()")
                    && containsNormalizedCode(normalizedRawCode,
                    "Map<Integer, Integer> endToStart = new HashMap<>()")
                    && containsNormalizedCode(normalizedRawCode, "endToStart.remove(value - 1)")
                    && containsNormalizedCode(normalizedRawCode, "startToEnd.remove(value + 1)"));
            hasDisjointSetComponents = hasDisjointSetComponents
                    || ((searchable.contains("disjoint") || searchable.contains("component"))
                    && containsNormalizedCode(normalizedRawCode, "boolean[] present = new boolean[LIMIT + 1]")
                    && containsNormalizedCode(normalizedRawCode,
                    "TreeMap<Integer, Integer> componentByStart = new TreeMap<>()")
                    && containsNormalizedCode(normalizedRawCode, "union(value, value - 1)")
                    && containsNormalizedCode(normalizedRawCode, "private int find(int value)"));
        }

        assertTrue(hasTreeMapIntervalMerge,
                filename + " must include the TreeMap interval merge route");
        assertTrue(hasBoundedBitSetScan,
                filename + " must include the bounded BitSet scan route");
        assertTrue(hasTreeSetValueScan,
                filename + " must include the TreeSet value scan route");
        assertTrue(hasBoundaryMaps,
                filename + " must include the boundary maps route");
        assertTrue(hasDisjointSetComponents,
                filename + " must include the disjoint-set components route");
    }

