    private static void assertBasicCalculatorIVSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " Basic Calculator IV should teach recursive polynomial parsing, two-stack evaluation, "
                        + "recursive descent, shunting-yard/RPN evaluation, and precedence climbing");

        boolean hasRecursivePolynomial = false;
        boolean hasTwoStackEvaluator = false;
        boolean hasRecursiveDescent = false;
        boolean hasShuntingYardRpn = false;
        boolean hasPrecedenceClimbing = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasRecursivePolynomial = hasRecursivePolynomial
                    || ((searchable.contains("recursive") || searchable.contains("polynomial class"))
                    && containsNormalizedCode(normalizedRawCode,
                    "parseExpr(expression.trim().split(\"\\\\s+\"), new int[]{0})")
                    && containsNormalizedCode(normalizedRawCode,
                    "private java.util.Map<String, Integer> parseMulExpr")
                    && containsNormalizedCode(normalizedRawCode,
                    "private java.util.Map<String, Integer> parseAtom")
                    && containsNormalizedCode(normalizedRawCode, "java.util.Collections.sort(vars)"));
            hasTwoStackEvaluator = hasTwoStackEvaluator
                    || ((searchable.contains("stack") || searchable.contains("two-stack"))
                    && containsNormalizedCode(normalizedRawCode,
                    "Deque<Map<String, Integer>> operands = new ArrayDeque<>()")
                    && containsNormalizedCode(normalizedRawCode,
                    "Deque<String> ops = new ArrayDeque<>()")
                    && containsNormalizedCode(normalizedRawCode,
                    "while (!ops.peek().equals(\"(\")) apply(operands, ops)")
                    && containsNormalizedCode(normalizedRawCode,
                    "precedence(ops.peek()) >= precedence(token)")
                    && containsNormalizedCode(normalizedRawCode, "private void apply"));
            hasRecursiveDescent = hasRecursiveDescent
                    || ((searchable.contains("recursive descent") || searchable.contains("token stream"))
                    && containsNormalizedCode(normalizedRawCode,
                    "TreeMap<List<String>, Integer> polynomial = parseExpression()")
                    && containsNormalizedCode(normalizedRawCode,
                    "private TreeMap<List<String>, Integer> parseTerm()")
                    && containsNormalizedCode(normalizedRawCode,
                    "private TreeMap<List<String>, Integer> parseFactor()")
                    && containsNormalizedCode(normalizedRawCode,
                    "private TreeMap<List<String>, Integer> newPolynomial()")
                    && containsNormalizedCode(normalizedRawCode, "private int compareTerm"));
            hasShuntingYardRpn = hasShuntingYardRpn
                    || ((searchable.contains("shunting") || searchable.contains("reverse polish"))
                    && containsNormalizedCode(normalizedRawCode,
                    "List<String> rpn = toReversePolish(tokens)")
                    && containsNormalizedCode(normalizedRawCode,
                    "Deque<Polynomial> stack = new ArrayDeque<>()")
                    && containsNormalizedCode(normalizedRawCode,
                    "private List<String> toReversePolish")
                    && containsNormalizedCode(normalizedRawCode, "output.add(operators.pop())")
                    && containsNormalizedCode(normalizedRawCode,
                    "static Polynomial variable(String variable)"));
            hasPrecedenceClimbing = hasPrecedenceClimbing
                    || ((searchable.contains("precedence climbing") || searchable.contains("minimumprecedence"))
                    && containsNormalizedCode(normalizedRawCode,
                    "Poly answer = parseWithMinPrecedence(0)")
                    && containsNormalizedCode(normalizedRawCode,
                    "precedence(tokens[index]) >= minimumPrecedence")
                    && containsNormalizedCode(normalizedRawCode,
                    "parseWithMinPrecedence(precedence(operator) + 1)")
                    && containsNormalizedCode(normalizedRawCode,
                    "private Poly parsePrimary()")
                    && containsNormalizedCode(normalizedRawCode, "coefficientByKey"));
        }

        assertTrue(hasRecursivePolynomial,
                filename + " must include the recursive polynomial-class parser route");
        assertTrue(hasTwoStackEvaluator,
                filename + " must include the two-stack expression evaluator route");
        assertTrue(hasRecursiveDescent,
                filename + " must include the token-stream recursive descent route");
        assertTrue(hasShuntingYardRpn,
                filename + " must include the shunting-yard to RPN polynomial route");
        assertTrue(hasPrecedenceClimbing,
                filename + " must include the precedence-climbing parser route");
    }

