    private static void assertLeastOperatorsSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " Least Operators to Express Number should teach remainder DP, iterative carry DP, "
                        + "largest-power overshoot recursion, explicit carry-state memoization, and a digit-carry shortest path");

        boolean hasTopDownRemainderDp = false;
        boolean hasIterativeCarryDp = false;
        boolean hasLargestPowerOvershoot = false;
        boolean hasMemoizedCarryState = false;
        boolean hasDigitCarryDijkstra = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasTopDownRemainderDp = hasTopDownRemainderDp
                    || ((searchable.contains("remainder") || searchable.contains("余数"))
                    && containsNormalizedCode(normalizedRawCode, "return dfs(target, 0) - 1")
                    && containsNormalizedCode(normalizedRawCode, "int digit = target % base")
                    && containsNormalizedCode(normalizedRawCode, "int rest = target / base")
                    && containsNormalizedCode(normalizedRawCode, "dfs(rest + 1, pos + 1)"));
            hasIterativeCarryDp = hasIterativeCarryDp
                    || ((searchable.contains("iterative") || searchable.contains("carry dp"))
                    && containsNormalizedCode(normalizedRawCode, "while (target > 0)")
                    && containsNormalizedCode(normalizedRawCode, "int nextNoCarry = Math.min")
                    && containsNormalizedCode(normalizedRawCode, "int nextCarry = Math.min")
                    && containsNormalizedCode(normalizedRawCode, "return Math.min(noCarry, carry + pos) - 1"));
            hasLargestPowerOvershoot = hasLargestPowerOvershoot
                    || ((searchable.contains("overshoot") || searchable.contains("largest power"))
                    && containsNormalizedCode(normalizedRawCode, "while (power * x <= target)")
                    && containsNormalizedCode(normalizedRawCode, "if (target < x)")
                    && containsNormalizedCode(normalizedRawCode, "nextPower - target < target")
                    && containsNormalizedCode(normalizedRawCode,
                    "exponent + 1 + solve((int) (nextPower - target))"));
            hasMemoizedCarryState = hasMemoizedCarryState
                    || ((searchable.contains("carry-state") || searchable.contains("explicit carry"))
                    && containsNormalizedCode(normalizedRawCode, "List<Integer> digits")
                    && containsNormalizedCode(normalizedRawCode, "private int dp(int pos, int carry)")
                    && containsNormalizedCode(normalizedRawCode, "int digit = digits.get(pos) + carry")
                    && containsNormalizedCode(normalizedRawCode, "dp(pos + 1, 1)"));
            hasDigitCarryDijkstra = hasDigitCarryDijkstra
                    || ((searchable.contains("dijkstra") || searchable.contains("shortest path"))
                    && containsNormalizedCode(normalizedRawCode, "PriorityQueue<int[]> pq")
                    && containsNormalizedCode(normalizedRawCode, "Comparator.comparingInt")
                    && containsNormalizedCode(normalizedRawCode,
                    "int total = cost + (carry == 0 ? 0 : costOfPower(pos))")
                    && containsNormalizedCode(normalizedRawCode, "relax(dist, pq"));
        }

        assertTrue(hasTopDownRemainderDp,
                filename + " must include the top-down remainder DP route");
        assertTrue(hasIterativeCarryDp,
                filename + " must include the iterative carry DP route");
        assertTrue(hasLargestPowerOvershoot,
                filename + " must include the largest-power overshoot recursion route");
        assertTrue(hasMemoizedCarryState,
                filename + " must include the explicit carry-state memoized DP route");
        assertTrue(hasDigitCarryDijkstra,
                filename + " must include the digit-carry shortest path route");
    }

