    private static void assertTallestBillboardSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " Tallest Billboard should teach HashMap difference DP, shorter-height array DP, "
                        + "signed offset DP, top-down signed-difference memoization, and meet-in-the-middle");

        boolean hasHashMapDifferenceDp = false;
        boolean hasShorterHeightArrayDp = false;
        boolean hasSignedOffsetDp = false;
        boolean hasTopDownMemo = false;
        boolean hasMeetInTheMiddle = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasHashMapDifferenceDp = hasHashMapDifferenceDp
                    || ((searchable.contains("hashmap") || searchable.contains("taller"))
                    && containsNormalizedCode(normalizedRawCode, "Map<Integer, Integer> dp = new HashMap<>()")
                    && containsNormalizedCode(normalizedRawCode,
                    "int newTaller = taller + Math.max(0, rod - diff)")
                    && containsNormalizedCode(normalizedRawCode, "dp.merge(newDiff, newTaller, Math::max)"));
            hasShorterHeightArrayDp = hasShorterHeightArrayDp
                    || ((searchable.contains("shorter") || searchable.contains("array dp"))
                    && containsNormalizedCode(normalizedRawCode, "Arrays.fill(dp, -1)")
                    && containsNormalizedCode(normalizedRawCode,
                    "int newShorter = previous[diff] + Math.min(diff, rod)")
                    && containsNormalizedCode(normalizedRawCode, "return dp[0]"));
            hasSignedOffsetDp = hasSignedOffsetDp
                    || ((searchable.contains("signed") || searchable.contains("offset"))
                    && containsNormalizedCode(normalizedRawCode, "int offset = sum")
                    && containsNormalizedCode(normalizedRawCode, "int[] dp = new int[2 * sum + 1]")
                    && containsNormalizedCode(normalizedRawCode, "next[offset + diff - rod]"));
            hasTopDownMemo = hasTopDownMemo
                    || ((searchable.contains("top-down") || searchable.contains("memo"))
                    && containsNormalizedCode(normalizedRawCode, "private Map<Long, Integer> memo = new HashMap<>()")
                    && containsNormalizedCode(normalizedRawCode,
                    "int useLeft = rod + dfs(index + 1, diff + rod)")
                    && containsNormalizedCode(normalizedRawCode, "int useRight = dfs(index + 1, diff - rod)"));
            hasMeetInTheMiddle = hasMeetInTheMiddle
                    || ((searchable.contains("meet") || searchable.contains("middle"))
                    && containsNormalizedCode(normalizedRawCode,
                    "Map<Integer, Integer> left = enumerate(rods, 0, half)")
                    && containsNormalizedCode(normalizedRawCode, "right.get(-diff)")
                    && containsNormalizedCode(normalizedRawCode,
                    "next.merge(diff - rod, leftHeight, Math::max)"));
        }

        assertTrue(hasHashMapDifferenceDp,
                filename + " must include the HashMap difference DP with taller-height route");
        assertTrue(hasShorterHeightArrayDp,
                filename + " must include the shorter-height array DP route");
        assertTrue(hasSignedOffsetDp,
                filename + " must include the signed offset DP route");
        assertTrue(hasTopDownMemo,
                filename + " must include the top-down signed-difference memoization route");
        assertTrue(hasMeetInTheMiddle,
                filename + " must include the meet-in-the-middle ternary enumeration route");
    }

