    private static void assertDesignHashSetSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " Design HashSet should teach direct boolean addressing, BitSet addressing, "
                        + "lazy paged bitsets, separate chaining, and linear probing");

        boolean hasDirectBoolean = false;
        boolean hasBitSet = false;
        boolean hasLazyPagedBitset = false;
        boolean hasSeparateChaining = false;
        boolean hasLinearProbing = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasDirectBoolean = hasDirectBoolean
                    || (searchable.contains("direct") && searchable.contains("boolean")
                    && containsNormalizedCode(normalizedRawCode, "boolean[] present")
                    && (containsNormalizedCode(normalizedRawCode, "new boolean[MAX_KEY + 1]")
                    || containsNormalizedCode(normalizedRawCode, "new boolean[1000001]"))
                    && containsNormalizedCode(normalizedRawCode, "present[key] = true")
                    && containsNormalizedCode(normalizedRawCode, "present[key] = false"));
            hasBitSet = hasBitSet
                    || (searchable.contains("bitset")
                    && containsNormalizedCode(normalizedRawCode, "new BitSet(MAX_KEY + 1)")
                    && containsNormalizedCode(normalizedRawCode, "bits.set(key)")
                    && containsNormalizedCode(normalizedRawCode, "bits.clear(key)")
                    && containsNormalizedCode(normalizedRawCode, "bits.get(key)"));
            hasLazyPagedBitset = hasLazyPagedBitset
                    || ((searchable.contains("paged") || searchable.contains("page"))
                    && containsNormalizedCode(normalizedRawCode, "long[][] pages")
                    && containsNormalizedCode(normalizedRawCode, "ensurePage(key)")
                    && containsNormalizedCode(normalizedRawCode, "key / PAGE_BITS")
                    && containsNormalizedCode(normalizedRawCode, "1L << (offset % WORD_BITS)"));
            hasSeparateChaining = hasSeparateChaining
                    || ((searchable.contains("chaining") || searchable.contains("linked"))
                    && containsNormalizedCode(normalizedRawCode, "Node[] buckets")
                    && containsNormalizedCode(normalizedRawCode, "private static class Node")
                    && containsNormalizedCode(normalizedRawCode, "node.next")
                    && containsNormalizedCode(normalizedRawCode, "key % BUCKET_COUNT"));
            hasLinearProbing = hasLinearProbing
                    || (searchable.contains("linear probing")
                    && containsNormalizedCode(normalizedRawCode, "byte[] state")
                    && containsNormalizedCode(normalizedRawCode, "(hash + step) % CAPACITY")
                    && containsNormalizedCode(normalizedRawCode, "state[slot] = 2")
                    && containsNormalizedCode(normalizedRawCode, "firstDeleted"));
        }

        assertTrue(hasDirectBoolean,
                filename + " must include the direct-address boolean-array route");
        assertTrue(hasBitSet,
                filename + " must include the direct-address BitSet route");
        assertTrue(hasLazyPagedBitset,
                filename + " must include the lazy paged bitset route");
        assertTrue(hasSeparateChaining,
                filename + " must include the separate-chaining linked-node route");
        assertTrue(hasLinearProbing,
                filename + " must include the linear-probing tombstone route");
    }

