            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasArrayPointer = hasArrayPointer
                    || (searchable.contains("array") && searchable.contains("pointer")
                    && containsNormalizedCode(normalizedRawCode, "String[] values")
                    && containsNormalizedCode(normalizedRawCode, "values[idKey] = value")
                    && containsNormalizedCode(normalizedRawCode, "values[ptr] != null")
                    && containsNormalizedCode(normalizedRawCode, "ptr++"));
            hasHashMapPointer = hasHashMapPointer
                    || (searchable.contains("hashmap") && searchable.contains("pointer")
                    && containsNormalizedCode(normalizedRawCode, "Map<Integer, String> pending")
                    && containsNormalizedCode(normalizedRawCode, "pending.put(idKey, value)")
                    && containsNormalizedCode(normalizedRawCode, "pending.containsKey(ptr)")
                    && containsNormalizedCode(normalizedRawCode, "pending.remove(ptr)"));
            hasBitSetReadiness = hasBitSetReadiness
                    || (searchable.contains("bitset") && searchable.contains("readiness")
                    && containsNormalizedCode(normalizedRawCode, "BitSet ready")
                    && containsNormalizedCode(normalizedRawCode, "ready.set(idKey)")
                    && containsNormalizedCode(normalizedRawCode, "ready.get(ptr)")
                    && containsNormalizedCode(normalizedRawCode, "values[ptr]"));
            hasTreeMapPending = hasTreeMapPending
                    || (searchable.contains("treemap") && searchable.contains("pending")
                    && containsNormalizedCode(normalizedRawCode, "TreeMap<Integer, String> pending")
                    && containsNormalizedCode(normalizedRawCode, "pending.put(idKey, value)")
                    && containsNormalizedCode(normalizedRawCode, "pending.firstEntry()")
                    && containsNormalizedCode(normalizedRawCode, "pending.pollFirstEntry()"));
            hasMinHeap = hasMinHeap
                    || (searchable.contains("min-heap") && searchable.contains("buffered")
                    && containsNormalizedCode(normalizedRawCode, "PriorityQueue<Integer> readyIds")
                    && containsNormalizedCode(normalizedRawCode, "readyIds.add(idKey)")
                    && containsNormalizedCode(normalizedRawCode, "readyIds.peek() == ptr")
                    && containsNormalizedCode(normalizedRawCode, "readyIds.poll()"));
