    private static void assertDesignBitsetSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " Design Bitset should teach dual char views, raw boolean XOR flags, Java BitSet, "
                        + "complementary ones/zeros sets, and lazy segment tree range flips");

        boolean hasDualCharViews = false;
        boolean hasRawBooleanXor = false;
        boolean hasJavaBitSet = false;
        boolean hasComplementarySets = false;
        boolean hasLazySegmentTree = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasDualCharViews = hasDualCharViews
                    || (searchable.contains("char") && searchable.contains("view")
                    && containsNormalizedCode(normalizedRawCode, "char[] bits")
                    && containsNormalizedCode(normalizedRawCode, "char[] flippedBits")
                    && containsNormalizedCode(normalizedRawCode, "Arrays.fill(flippedBits, '1')")
                    && containsNormalizedCode(normalizedRawCode, "new String(flipped ? flippedBits : bits)"));
            hasRawBooleanXor = hasRawBooleanXor
                    || (searchable.contains("boolean") && searchable.contains("xor")
                    && containsNormalizedCode(normalizedRawCode, "boolean[] raw")
                    && containsNormalizedCode(normalizedRawCode, "raw[idx] ^ flipped")
                    && containsNormalizedCode(normalizedRawCode, "raw[idx] = !flipped")
                    && containsNormalizedCode(normalizedRawCode, "raw[idx] = flipped"));
            hasJavaBitSet = hasJavaBitSet
                    || (searchable.contains("bitset") && searchable.contains("global")
                    && containsNormalizedCode(normalizedRawCode, "BitSet raw")
                    && containsNormalizedCode(normalizedRawCode, "raw.get(idx) ^ flipped")
                    && containsNormalizedCode(normalizedRawCode, "raw.set(idx, !flipped)")
                    && containsNormalizedCode(normalizedRawCode, "raw.set(idx, flipped)"));
            hasComplementarySets = hasComplementarySets
                    || (searchable.contains("complement") || searchable.contains("ones") && searchable.contains("zeros"))
                    && containsNormalizedCode(normalizedRawCode, "Set<Integer> ones")
                    && containsNormalizedCode(normalizedRawCode, "Set<Integer> zeros")
                    && containsNormalizedCode(normalizedRawCode, "zeros.remove(idx)")
                    && containsNormalizedCode(normalizedRawCode, "Set<Integer> temp = ones")
                    && containsNormalizedCode(normalizedRawCode, "ones = zeros")
                    && containsNormalizedCode(normalizedRawCode, "zeros = temp");
            hasLazySegmentTree = hasLazySegmentTree
                    || (searchable.contains("segment") && searchable.contains("lazy")
                    && containsNormalizedCode(normalizedRawCode, "int[] treeOnes")
                    && containsNormalizedCode(normalizedRawCode, "boolean[] lazyFlip")
                    && containsNormalizedCode(normalizedRawCode, "applyFlip(1, 0, size - 1)")
                    && containsNormalizedCode(normalizedRawCode, "pointSet(1, 0, size - 1, idx, 1)")
                    && containsNormalizedCode(normalizedRawCode, "writeString(1, 0, size - 1, chars)")
                    && containsNormalizedCode(normalizedRawCode,
                    "treeOnes[node] = (right - left + 1) - treeOnes[node]"));
        }

        assertTrue(hasDualCharViews,
                filename + " must include the dual char views with flip flag route");
        assertTrue(hasRawBooleanXor,
                filename + " must include the raw boolean array with XOR flag route");
        assertTrue(hasJavaBitSet,
                filename + " must include the Java BitSet with global flip flag route");
        assertTrue(hasComplementarySets,
                filename + " must include the complementary ones/zeros sets route");
        assertTrue(hasLazySegmentTree,
                filename + " must include the lazy segment tree range flip route");
    }

