    private static void assertDesignMemoryAllocatorSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " Design Memory Allocator should teach direct cell scanning, BitSet free-run search, "
                        + "allocated-interval TreeMap gaps, coalescing free intervals, and a segment tree");

        boolean hasDirectCellArray = false;
        boolean hasBitSetFreeRun = false;
        boolean hasAllocatedIntervalTreeMap = false;
        boolean hasFreeIntervalTreeMap = false;
        boolean hasSegmentTreeLeftmost = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasDirectCellArray = hasDirectCellArray
                    || (searchable.contains("array") && searchable.contains("first-fit")
                    && containsNormalizedCode(normalizedRawCode, "int[] memory")
                    && containsNormalizedCode(normalizedRawCode, "memory[i] == 0")
                    && containsNormalizedCode(normalizedRawCode, "memory[j] = mID")
                    && containsNormalizedCode(normalizedRawCode, "memory[i] = 0"));
            hasBitSetFreeRun = hasBitSetFreeRun
                    || (searchable.contains("bitset") && searchable.contains("free")
                    && containsNormalizedCode(normalizedRawCode, "BitSet used")
                    && containsNormalizedCode(normalizedRawCode, "used.nextClearBit(0)")
                    && containsNormalizedCode(normalizedRawCode, "used.nextSetBit(start)")
                    && containsNormalizedCode(normalizedRawCode, "Arrays.fill(owner, start, start + size, mID)")
                    && containsNormalizedCode(normalizedRawCode, "used.clear(i)"));
            hasAllocatedIntervalTreeMap = hasAllocatedIntervalTreeMap
                    || (searchable.contains("allocated") && searchable.contains("treemap")
                    && containsNormalizedCode(normalizedRawCode, "TreeMap<Integer, Block> allocatedByStart")
                    && containsNormalizedCode(normalizedRawCode, "allocatedByStart.entrySet()")
                    && containsNormalizedCode(normalizedRawCode, "startsById.computeIfAbsent")
                    && containsNormalizedCode(normalizedRawCode, "allocatedByStart.remove(start)"));
            hasFreeIntervalTreeMap = hasFreeIntervalTreeMap
                    || (searchable.contains("free") && searchable.contains("coalescing")
                    && containsNormalizedCode(normalizedRawCode, "TreeMap<Integer, Integer> freeByStart")
                    && containsNormalizedCode(normalizedRawCode, "freeByStart.floorEntry(start)")
                    && containsNormalizedCode(normalizedRawCode, "freeByStart.ceilingEntry(start)")
                    && containsNormalizedCode(normalizedRawCode, "rangesById.computeIfAbsent"));
            hasSegmentTreeLeftmost = hasSegmentTreeLeftmost
                    || (searchable.contains("segment tree") && searchable.contains("leftmost")
                    && containsNormalizedCode(normalizedRawCode, "int[] prefix")
                    && containsNormalizedCode(normalizedRawCode, "int[] suffix")
                    && containsNormalizedCode(normalizedRawCode, "int[] best")
                    && containsNormalizedCode(normalizedRawCode, "firstFit(1, 0, n - 1, size)")
                    && containsNormalizedCode(normalizedRawCode, "suffix[child] + prefix[child + 1]"));
        }

        assertTrue(hasDirectCellArray,
                filename + " must include the direct cell-array first-fit route");
        assertTrue(hasBitSetFreeRun,
                filename + " must include the BitSet free-run search route");
        assertTrue(hasAllocatedIntervalTreeMap,
                filename + " must include the allocated-interval TreeMap gap route");
        assertTrue(hasFreeIntervalTreeMap,
                filename + " must include the coalescing free-interval TreeMap route");
        assertTrue(hasSegmentTreeLeftmost,
                filename + " must include the segment-tree leftmost free-block route");
    }

