    private static void assertDesignSqlSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " Design SQL should teach sparse row maps, tombstone row arrays, flattened cell maps, "
                        + "nested row arrays, and column-oriented storage");

        boolean hasSparseRowMap = false;
        boolean hasTombstoneRowArray = false;
        boolean hasFlattenedCellMap = false;
        boolean hasNestedRowArrayMap = false;
        boolean hasColumnOrientedTable = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasSparseRowMap = hasSparseRowMap
                    || searchable.contains("sparse")
                    && containsNormalizedCode(normalizedRawCode, "Map<Integer, List<String>> rowsById")
                    && containsNormalizedCode(normalizedRawCode, "rowsById.put(nextRowId++")
                    && containsNormalizedCode(normalizedRawCode, "rowsById.remove(rowId)");
            hasTombstoneRowArray = hasTombstoneRowArray
                    || searchable.contains("tombstone")
                    && containsNormalizedCode(normalizedRawCode, "List<List<String>> rows")
                    && containsNormalizedCode(normalizedRawCode, "rows.add(new ArrayList<>(row))")
                    && containsNormalizedCode(normalizedRawCode, "rows.set(rowId - 1, null)")
                    && containsNormalizedCode(normalizedRawCode, "rows.get(rowId - 1).get(columnId - 1)");
            hasFlattenedCellMap = hasFlattenedCellMap
                    || searchable.contains("flattened")
                    && containsNormalizedCode(normalizedRawCode, "Map<String, String> cells")
                    && containsNormalizedCode(normalizedRawCode, "columnsByName.get(name)")
                    && containsNormalizedCode(normalizedRawCode, "cells.remove(key(name, rowId, column))");
            hasNestedRowArrayMap = hasNestedRowArrayMap
                    || searchable.contains("nested")
                    && containsNormalizedCode(normalizedRawCode, "Map<String, Map<Integer, String[]>> rowsByTable")
                    && containsNormalizedCode(normalizedRawCode, "row.toArray(new String[0])")
                    && containsNormalizedCode(normalizedRawCode, "rowsByTable.get(name).remove(rowId)");
            hasColumnOrientedTable = hasColumnOrientedTable
                    || searchable.contains("column")
                    && containsNormalizedCode(normalizedRawCode, "List<Map<Integer, String>> columns")
                    && containsNormalizedCode(normalizedRawCode, "columns.get(column).put(rowId, row.get(column))")
                    && containsNormalizedCode(normalizedRawCode, "columns.get(columnId - 1).get(rowId)");
        }

        assertTrue(hasSparseRowMap,
                filename + " must include the sparse row-map route");
        assertTrue(hasTombstoneRowArray,
                filename + " must include the tombstone row-array route");
        assertTrue(hasFlattenedCellMap,
                filename + " must include the flattened cell-map route");
        assertTrue(hasNestedRowArrayMap,
                filename + " must include the nested row-array map route");
        assertTrue(hasColumnOrientedTable,
                filename + " must include the column-oriented table route");
    }

