    private static void assertMinimumCommonValueSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " Minimum Common Value should teach merge-style two pointers, duplicate-block "
                        + "skipping, hash set lookup, binary search over shorter candidates, and alternating "
                        + "lower-bound jumps");

        boolean hasMergeTwoPointers = false;
        boolean hasDuplicateBlockSkipping = false;
        boolean hasHashSetLookup = false;
        boolean hasBinarySearchCandidates = false;
        boolean hasLowerBoundJumps = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);
            String normalizedName = name.toLowerCase(Locale.ROOT);

            hasMergeTwoPointers = hasMergeTwoPointers
                    || searchable.contains("two pointer")
                    && containsNormalizedCode(normalizedRawCode, "while (i < nums1.length && j < nums2.length)")
                    && containsNormalizedCode(normalizedRawCode, "if (nums1[i] == nums2[j])")
                    && containsNormalizedCode(normalizedRawCode, "return nums1[i]")
                    && containsNormalizedCode(normalizedRawCode, "if (nums1[i] < nums2[j])");
            hasDuplicateBlockSkipping = hasDuplicateBlockSkipping
                    || normalizedName.contains("duplicate")
                    && containsNormalizedCode(normalizedRawCode, "int value = nums1[i]")
                    && containsNormalizedCode(normalizedRawCode, "while (i < nums1.length && nums1[i] == value)")
                    && containsNormalizedCode(normalizedRawCode, "int value = nums2[j]")
                    && containsNormalizedCode(normalizedRawCode, "while (j < nums2.length && nums2[j] == value)");
            hasHashSetLookup = hasHashSetLookup
                    || normalizedName.contains("hash set")
                    && containsNormalizedCode(normalizedRawCode, "Set<Integer> seen = new HashSet<>()")
                    && containsNormalizedCode(normalizedRawCode, "seen.add(value)")
                    && containsNormalizedCode(normalizedRawCode, "seen.contains(value)")
                    && containsNormalizedCode(normalizedRawCode, "return value");
            hasBinarySearchCandidates = hasBinarySearchCandidates
                    || normalizedName.contains("binary search")
                    && containsNormalizedCode(normalizedRawCode, "int[] candidates")
                    && containsNormalizedCode(normalizedRawCode, "contains(searched, value)")
                    && containsNormalizedCode(normalizedRawCode, "while (left <= right)")
                    && containsNormalizedCode(normalizedRawCode, "nums[mid] == target");
            hasLowerBoundJumps = hasLowerBoundJumps
                    || normalizedName.contains("lower-bound")
                    && containsNormalizedCode(normalizedRawCode, "i = lowerBound(nums1, i + 1, nums2[j])")
                    && containsNormalizedCode(normalizedRawCode, "j = lowerBound(nums2, j + 1, nums1[i])")
                    && containsNormalizedCode(normalizedRawCode, "private int lowerBound")
                    && containsNormalizedCode(normalizedRawCode, "while (left < right)");
        }

        assertTrue(hasMergeTwoPointers,
                filename + " must include the merge-style two-pointer route");
        assertTrue(hasDuplicateBlockSkipping,
                filename + " must include the duplicate-block skipping route");
        assertTrue(hasHashSetLookup,
                filename + " must include the hash-set lookup route");
        assertTrue(hasBinarySearchCandidates,
                filename + " must include the binary-search shorter-candidates route");
        assertTrue(hasLowerBoundJumps,
                filename + " must include the alternating lower-bound jumps route");
    }

