    private static void assertMaximumNumberOfPairsSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " Maximum Number of Pairs should teach bounded frequency arrays, HashMap "
                        + "frequency counts, toggle sets, sorting adjacent values, and bounded parity tables");

        boolean hasBoundedFrequencyArray = false;
        boolean hasHashMapFrequencyCounts = false;
        boolean hasToggleSet = false;
        boolean hasSortAdjacentPairs = false;
        boolean hasBoundedParityTable = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);
            String normalizedName = name.toLowerCase(Locale.ROOT);

            hasBoundedFrequencyArray = hasBoundedFrequencyArray
                    || normalizedName.contains("bounded frequency")
                    && containsNormalizedCode(normalizedRawCode, "int[] count = new int[101]")
                    && containsNormalizedCode(normalizedRawCode, "count[value]++")
                    && containsNormalizedCode(normalizedRawCode, "pairs += frequency / 2")
                    && containsNormalizedCode(normalizedRawCode, "leftovers += frequency % 2");
            hasHashMapFrequencyCounts = hasHashMapFrequencyCounts
                    || normalizedName.contains("hashmap")
                    && containsNormalizedCode(normalizedRawCode, "Map<Integer, Integer> counts = new HashMap<>()")
                    && containsNormalizedCode(normalizedRawCode, "counts.getOrDefault(value, 0) + 1")
                    && containsNormalizedCode(normalizedRawCode, "counts.values()")
                    && containsNormalizedCode(normalizedRawCode, "leftovers += frequency % 2");
            hasToggleSet = hasToggleSet
                    || searchable.contains("toggle")
                    && containsNormalizedCode(normalizedRawCode, "Set<Integer> waiting = new HashSet<>()")
                    && containsNormalizedCode(normalizedRawCode, "waiting.contains(value)")
                    && containsNormalizedCode(normalizedRawCode, "waiting.remove(value)")
                    && containsNormalizedCode(normalizedRawCode, "waiting.size()");
            hasSortAdjacentPairs = hasSortAdjacentPairs
                    || normalizedName.contains("sort")
                    && containsNormalizedCode(normalizedRawCode, "Arrays.sort(nums)")
                    && containsNormalizedCode(normalizedRawCode, "index + 1 < nums.length")
                    && containsNormalizedCode(normalizedRawCode, "nums[index] == nums[index + 1]")
                    && containsNormalizedCode(normalizedRawCode, "index += 2");
            hasBoundedParityTable = hasBoundedParityTable
                    || normalizedName.contains("parity")
                    && containsNormalizedCode(normalizedRawCode, "boolean[] waiting = new boolean[101]")
                    && containsNormalizedCode(normalizedRawCode, "if (waiting[value])")
                    && containsNormalizedCode(normalizedRawCode, "waiting[value] = false")
                    && containsNormalizedCode(normalizedRawCode, "nums.length - pairs * 2");
        }

        assertTrue(hasBoundedFrequencyArray,
                filename + " must include the bounded frequency-array route");
        assertTrue(hasHashMapFrequencyCounts,
                filename + " must include the HashMap frequency-count route");
        assertTrue(hasToggleSet,
                filename + " must include the toggle-set route");
        assertTrue(hasSortAdjacentPairs,
                filename + " must include the sort-adjacent-values route");
        assertTrue(hasBoundedParityTable,
                filename + " must include the bounded parity-table route");
    }

