    private static void assertLongestUnequalAdjacentGroupsSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " Longest Unequal Adjacent Groups should teach run-boundary greedy, explicit "
                        + "run compression, two-state DP, quadratic subsequence DP, and recursive memoized choice");

        boolean hasRunBoundaryGreedy = false;
        boolean hasExplicitRunCompression = false;
        boolean hasTwoStateDp = false;
        boolean hasQuadraticSubsequenceDp = false;
        boolean hasRecursiveMemoizedChoice = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasRunBoundaryGreedy = hasRunBoundaryGreedy
                    || searchable.contains("run boundary")
                    && containsNormalizedCode(normalizedRawCode, "groups[i] != groups[i - 1]")
                    && containsNormalizedCode(normalizedRawCode, "answer++")
                    && containsNormalizedCode(normalizedRawCode, "return answer");
            hasExplicitRunCompression = hasExplicitRunCompression
                    || searchable.contains("run compression")
                    && containsNormalizedCode(normalizedRawCode, "List<Integer> runs = new ArrayList<>()")
                    && containsNormalizedCode(normalizedRawCode, "runs.get(runs.size() - 1) != group")
                    && containsNormalizedCode(normalizedRawCode, "runs.add(group)")
                    && containsNormalizedCode(normalizedRawCode, "return runs.size()");
            hasTwoStateDp = hasTwoStateDp
                    || searchable.contains("two-state")
                    && containsNormalizedCode(normalizedRawCode, "int zero = 0")
                    && containsNormalizedCode(normalizedRawCode, "int one = 0")
                    && containsNormalizedCode(normalizedRawCode, "zero = Math.max(zero, one + 1)")
                    && containsNormalizedCode(normalizedRawCode, "one = Math.max(one, zero + 1)");
            hasQuadraticSubsequenceDp = hasQuadraticSubsequenceDp
                    || searchable.contains("quadratic")
                    && containsNormalizedCode(normalizedRawCode, "int[] dp = new int[groups.length]")
                    && containsNormalizedCode(normalizedRawCode, "java.util.Arrays.fill(dp, 1)")
                    && containsNormalizedCode(normalizedRawCode, "for (int j = 0; j < i; j++)")
                    && containsNormalizedCode(normalizedRawCode, "groups[i] != groups[j]")
                    && containsNormalizedCode(normalizedRawCode, "dp[i] = Math.max(dp[i], dp[j] + 1)");
            hasRecursiveMemoizedChoice = hasRecursiveMemoizedChoice
                    || searchable.contains("recursive")
                    && containsNormalizedCode(normalizedRawCode, "memo = new int[groups.length][3]")
                    && containsNormalizedCode(normalizedRawCode, "return dfs(0, 2)")
                    && containsNormalizedCode(normalizedRawCode, "int best = dfs(index + 1, previous)")
                    && containsNormalizedCode(normalizedRawCode, "previous == 2 || groups[index] != previous")
                    && containsNormalizedCode(normalizedRawCode, "memo[index][previous] = best");
        }

        assertTrue(hasRunBoundaryGreedy,
                filename + " must include the run-boundary greedy route");
        assertTrue(hasExplicitRunCompression,
                filename + " must include the explicit run-compression route");
        assertTrue(hasTwoStateDp,
                filename + " must include the two-state DP route");
        assertTrue(hasQuadraticSubsequenceDp,
                filename + " must include the quadratic subsequence-DP route");
        assertTrue(hasRecursiveMemoizedChoice,
                filename + " must include the recursive memoized-choice route");
    }

