    private static void assertCircularSentenceCheckSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " Circular Sentence Check should teach split word-boundary comparison, "
                        + "space-boundary scan, delimiter-jump scan, boundary-character arrays, and "
                        + "recursive word-link checking");

        boolean hasSplitWordBoundary = false;
        boolean hasSpaceBoundaryScan = false;
        boolean hasDelimiterJumpScan = false;
        boolean hasBoundaryCharacterArrays = false;
        boolean hasRecursiveWordLinkCheck = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasSplitWordBoundary = hasSplitWordBoundary
                    || searchable.contains("split")
                    && searchable.contains("boundary")
                    && containsNormalizedCode(normalizedRawCode, "String[] words = sentence.split(\" \")")
                    && containsNormalizedCode(normalizedRawCode, "for (int i = 0; i < words.length; i++)")
                    && containsNormalizedCode(normalizedRawCode, "String next = words[(i + 1) % words.length]")
                    && containsNormalizedCode(normalizedRawCode,
                    "current.charAt(current.length() - 1) != next.charAt(0)");
            hasSpaceBoundaryScan = hasSpaceBoundaryScan
                    || searchable.contains("space boundary")
                    && containsNormalizedCode(normalizedRawCode, "sentence.charAt(i) == ' '")
                    && containsNormalizedCode(normalizedRawCode,
                    "sentence.charAt(i - 1) != sentence.charAt(i + 1)")
                    && containsNormalizedCode(normalizedRawCode,
                    "return sentence.charAt(0) == sentence.charAt(sentence.length() - 1)");
            hasDelimiterJumpScan = hasDelimiterJumpScan
                    || searchable.contains("delimiter")
                    && containsNormalizedCode(normalizedRawCode, "int boundary = sentence.indexOf(' ')")
                    && containsNormalizedCode(normalizedRawCode, "while (boundary != -1)")
                    && containsNormalizedCode(normalizedRawCode,
                    "sentence.charAt(boundary - 1) != sentence.charAt(boundary + 1)")
                    && containsNormalizedCode(normalizedRawCode,
                    "boundary = sentence.indexOf(' ', boundary + 1)");
            hasBoundaryCharacterArrays = hasBoundaryCharacterArrays
                    || searchable.contains("boundary-character")
                    && containsNormalizedCode(normalizedRawCode, "char[] first = new char[words.length]")
                    && containsNormalizedCode(normalizedRawCode, "char[] last = new char[words.length]")
                    && containsNormalizedCode(normalizedRawCode, "first[i] = words[i].charAt(0)")
                    && containsNormalizedCode(normalizedRawCode,
                    "last[i] = words[i].charAt(words[i].length() - 1)")
                    && containsNormalizedCode(normalizedRawCode, "last[i] != first[(i + 1) % words.length]");
            hasRecursiveWordLinkCheck = hasRecursiveWordLinkCheck
                    || searchable.contains("recursive")
                    && containsNormalizedCode(normalizedRawCode, "return check(words, 0)")
                    && containsNormalizedCode(normalizedRawCode,
                    "private boolean check(String[] words, int index)")
                    && containsNormalizedCode(normalizedRawCode, "if (index == words.length)")
                    && containsNormalizedCode(normalizedRawCode,
                    "String next = words[(index + 1) % words.length]")
                    && containsNormalizedCode(normalizedRawCode, "return check(words, index + 1)");
        }

        assertTrue(hasSplitWordBoundary,
                filename + " must include the split word-boundary route");
        assertTrue(hasSpaceBoundaryScan,
                filename + " must include the space-boundary scan route");
        assertTrue(hasDelimiterJumpScan,
                filename + " must include the delimiter-jump scan route");
        assertTrue(hasBoundaryCharacterArrays,
                filename + " must include the boundary-character arrays route");
        assertTrue(hasRecursiveWordLinkCheck,
                filename + " must include the recursive word-link route");
    }

