    private static void assertCountPairsBelowTargetSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " Count Pairs Below Target should teach sorted two pointers, sorted binary search, "
                        + "online Fenwick compression, merge-sort pair counting, and brute-force baseline routes");

        boolean hasSortedTwoPointers = false;
        boolean hasSortedBinarySearch = false;
        boolean hasOnlineFenwick = false;
        boolean hasMergeSortCounting = false;
        boolean hasBruteForcePairs = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasSortedTwoPointers = hasSortedTwoPointers
                    || searchable.contains("sorted two pointers")
                    && containsNormalizedCode(normalizedRawCode, "List<Integer> sorted = new ArrayList<>(nums)")
                    && containsNormalizedCode(normalizedRawCode, "Collections.sort(sorted)")
                    && containsNormalizedCode(normalizedRawCode, "answer += right - left")
                    && containsNormalizedCode(normalizedRawCode, "left++")
                    && containsNormalizedCode(normalizedRawCode, "right--");
            hasSortedBinarySearch = hasSortedBinarySearch
                    || searchable.contains("binary search")
                    && containsNormalizedCode(normalizedRawCode, "int boundary = lowerBound")
                    && containsNormalizedCode(normalizedRawCode, "(long) target - sorted.get(left)")
                    && containsNormalizedCode(normalizedRawCode, "answer += boundary - left - 1")
                    && containsNormalizedCode(normalizedRawCode, "if (nums.get(mid) < value)");
            hasOnlineFenwick = hasOnlineFenwick
                    || searchable.contains("fenwick")
                    && containsNormalizedCode(normalizedRawCode, "int[] bit = new int[unique.size() + 1]")
                    && containsNormalizedCode(normalizedRawCode, "answer += sum(bit, countLessThan)")
                    && containsNormalizedCode(normalizedRawCode, "add(bit, index, 1)")
                    && containsNormalizedCode(normalizedRawCode, "index += index & -index")
                    && containsNormalizedCode(normalizedRawCode, "index -= index & -index");
            hasMergeSortCounting = hasMergeSortCounting
                    || searchable.contains("merge sort")
                    && containsNormalizedCode(normalizedRawCode, "sortAndCount(values, temp, 0, values.length, target)")
                    && containsNormalizedCode(normalizedRawCode, "while (j < right && (long) values[i] + values[j] < target)")
                    && containsNormalizedCode(normalizedRawCode, "answer += j - mid")
                    && containsNormalizedCode(normalizedRawCode, "merge(values, temp, left, mid, right)")
                    && containsNormalizedCode(normalizedRawCode, "System.arraycopy(temp, left, values, left, right - left)");
            hasBruteForcePairs = hasBruteForcePairs
                    || searchable.contains("brute force")
                    && containsNormalizedCode(normalizedRawCode, "for (int i = 0; i < nums.size(); i++)")
                    && containsNormalizedCode(normalizedRawCode, "for (int j = i + 1; j < nums.size(); j++)")
                    && containsNormalizedCode(normalizedRawCode, "(long) nums.get(i) + nums.get(j) < target")
                    && containsNormalizedCode(normalizedRawCode, "answer++");
        }

        assertTrue(hasSortedTwoPointers,
                filename + " must include the sorted two-pointer batch-count route");
        assertTrue(hasSortedBinarySearch,
                filename + " must include the sorted binary-search boundary route");
        assertTrue(hasOnlineFenwick,
                filename + " must include the online Fenwick compression route");
        assertTrue(hasMergeSortCounting,
                filename + " must include the merge-sort pair-counting route");
        assertTrue(hasBruteForcePairs,
                filename + " must include the brute-force pair baseline route");
    }

