    private static void assertOriginalArrayFromDoubledValuesSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " Original Array From Doubled Values should teach sorted count-map matching, "
                        + "bounded counting-array matching, sorted demand queues, TreeMap frequency greedy, "
                        + "and used-index baseline routes");

        boolean hasSortedCountMap = false;
        boolean hasCountingArray = false;
        boolean hasDemandQueue = false;
        boolean hasTreeMapFrequency = false;
        boolean hasUsedIndexBaseline = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasSortedCountMap = hasSortedCountMap
                    || searchable.contains("count map")
                    && containsNormalizedCode(normalizedRawCode, "Map<Integer, Integer> count = new HashMap<>()")
                    && containsNormalizedCode(normalizedRawCode, "int[] values = changed.clone()")
                    && containsNormalizedCode(normalizedRawCode, "Arrays.sort(values)")
                    && containsNormalizedCode(normalizedRawCode, "count.getOrDefault(doubled, 0)")
                    && containsNormalizedCode(normalizedRawCode, "original[size++] = x");
            hasCountingArray = hasCountingArray
                    || searchable.contains("counting array")
                    && containsNormalizedCode(normalizedRawCode, "int[] count = new int[max + 1]")
                    && containsNormalizedCode(normalizedRawCode, "if (count[0] % 2 == 1)")
                    && containsNormalizedCode(normalizedRawCode, "doubled > max || count[doubled] == 0")
                    && containsNormalizedCode(normalizedRawCode, "count[doubled]--");
            hasDemandQueue = hasDemandQueue
                    || searchable.contains("demand queue")
                    && containsNormalizedCode(normalizedRawCode, "ArrayDeque<Integer> neededDoubles = new ArrayDeque<>()")
                    && containsNormalizedCode(normalizedRawCode, "neededDoubles.peek() == value")
                    && containsNormalizedCode(normalizedRawCode, "neededDoubles.peek() < value")
                    && containsNormalizedCode(normalizedRawCode, "neededDoubles.offer(value * 2)")
                    && containsNormalizedCode(normalizedRawCode, "neededDoubles.isEmpty()");
            hasTreeMapFrequency = hasTreeMapFrequency
                    || searchable.contains("treemap")
                    && containsNormalizedCode(normalizedRawCode, "TreeMap<Integer, Integer> count = new TreeMap<>()")
                    && containsNormalizedCode(normalizedRawCode, "int x = count.firstKey()")
                    && containsNormalizedCode(normalizedRawCode, "int occurrences = count.remove(x)")
                    && containsNormalizedCode(normalizedRawCode, "doubledCount < occurrences")
                    && containsNormalizedCode(normalizedRawCode, "count.put(doubled, doubledCount - occurrences)");
            hasUsedIndexBaseline = hasUsedIndexBaseline
                    || searchable.contains("used-index")
                    && containsNormalizedCode(normalizedRawCode, "boolean[] used = new boolean[values.length]")
                    && containsNormalizedCode(normalizedRawCode, "while (match < values.length && (used[match] || values[match] != doubled))")
                    && containsNormalizedCode(normalizedRawCode, "used[match] = true")
                    && containsNormalizedCode(normalizedRawCode, "original[size++] = values[i]");
        }

        assertTrue(hasSortedCountMap,
                filename + " must include the sorted count-map matching route");
        assertTrue(hasCountingArray,
                filename + " must include the bounded counting-array route");
        assertTrue(hasDemandQueue,
                filename + " must include the sorted demand-queue route");
        assertTrue(hasTreeMapFrequency,
                filename + " must include the TreeMap frequency-greedy route");
        assertTrue(hasUsedIndexBaseline,
                filename + " must include the used-index baseline route");
    }

