    private static void assertAppendCharactersToMakeSubsequenceSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " Append Characters to Make Subsequence should teach two-pointer prefix scan, "
                        + "IndexOf search, position-list binary search, character index queues, and "
                        + "next-occurrence table routes");

        boolean hasTwoPointerPrefixScan = false;
        boolean hasIndexOfSearch = false;
        boolean hasPositionListsBinarySearch = false;
        boolean hasCharacterIndexQueues = false;
        boolean hasNextOccurrenceTable = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasTwoPointerPrefixScan = hasTwoPointerPrefixScan
                    || searchable.contains("two pointer")
                    && containsNormalizedCode(normalizedRawCode, "int matched = 0")
                    && containsNormalizedCode(normalizedRawCode, "matched < t.length()")
                    && containsNormalizedCode(normalizedRawCode, "s.charAt(i) == t.charAt(matched)")
                    && containsNormalizedCode(normalizedRawCode, "return t.length() - matched");
            hasIndexOfSearch = hasIndexOfSearch
                    || searchable.contains("indexof")
                    && containsNormalizedCode(normalizedRawCode, "int position = -1")
                    && containsNormalizedCode(normalizedRawCode, "s.indexOf(t.charAt(matched), position + 1)")
                    && containsNormalizedCode(normalizedRawCode, "if (position == -1)")
                    && containsNormalizedCode(normalizedRawCode, "return t.length() - matched");
            hasPositionListsBinarySearch = hasPositionListsBinarySearch
                    || searchable.contains("position lists")
                    && searchable.contains("binary search")
                    && containsNormalizedCode(normalizedRawCode, "List<Integer>[] positions = new ArrayList[26]")
                    && containsNormalizedCode(normalizedRawCode, "int index = firstGreaterThan(list, previous)")
                    && containsNormalizedCode(normalizedRawCode, "if (list.get(mid) <= value)")
                    && containsNormalizedCode(normalizedRawCode, "previous = list.get(index)");
            hasCharacterIndexQueues = hasCharacterIndexQueues
                    || searchable.contains("queue")
                    && containsNormalizedCode(normalizedRawCode, "ArrayDeque<Integer>[] positions = new ArrayDeque[26]")
                    && containsNormalizedCode(normalizedRawCode, "ArrayDeque<Integer> queue = positions[t.charAt(matched) - 'a']")
                    && containsNormalizedCode(normalizedRawCode, "queue.peek() <= previous")
                    && containsNormalizedCode(normalizedRawCode, "previous = queue.poll()");
            hasNextOccurrenceTable = hasNextOccurrenceTable
                    || searchable.contains("next occurrence")
                    && containsNormalizedCode(normalizedRawCode, "int[][] next = new int[n + 1][26]")
                    && containsNormalizedCode(normalizedRawCode, "Arrays.fill(next[n], -1)")
                    && containsNormalizedCode(normalizedRawCode, "System.arraycopy(next[i + 1], 0, next[i], 0, 26)")
                    && containsNormalizedCode(normalizedRawCode, "int found = next[position][t.charAt(matched) - 'a']");
        }

        assertTrue(hasTwoPointerPrefixScan,
                filename + " must include the two-pointer prefix-scan route");
        assertTrue(hasIndexOfSearch,
                filename + " must include the IndexOf-from-previous-match route");
        assertTrue(hasPositionListsBinarySearch,
                filename + " must include the position-list binary-search route");
        assertTrue(hasCharacterIndexQueues,
                filename + " must include the character index-queue route");
        assertTrue(hasNextOccurrenceTable,
                filename + " must include the next-occurrence table route");
    }

