    private static void assertRandomizedSetSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " RandomizedSet should teach ArrayList+map, dynamic int-array+map, dense-slot maps, "
                        + "entry-object dense arrays, and primitive open-addressing index-map routes");

        boolean hasArrayListIndexMap = false;
        boolean hasDynamicIntArray = false;
        boolean hasDenseSlotHashMaps = false;
        boolean hasEntryObjectDenseArray = false;
        boolean hasPrimitiveOpenAddressing = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasArrayListIndexMap = hasArrayListIndexMap
                    || searchable.contains("arraylist")
                    && searchable.contains("index map")
                    && containsNormalizedCode(normalizedRawCode, "ArrayList<Integer> values")
                    && containsNormalizedCode(normalizedRawCode, "Map<Integer, Integer> indexes")
                    && containsNormalizedCode(normalizedRawCode, "values.get(random.nextInt(values.size()))");
            hasDynamicIntArray = hasDynamicIntArray
                    || searchable.contains("dynamic int array")
                    && containsNormalizedCode(normalizedRawCode, "int[] values = new int[4]")
                    && containsNormalizedCode(normalizedRawCode, "ensureCapacity()")
                    && containsNormalizedCode(normalizedRawCode,
                    "values = java.util.Arrays.copyOf(values, values.length * 2)")
                    && containsNormalizedCode(normalizedRawCode, "values[random.nextInt(size)]");
            hasDenseSlotHashMaps = hasDenseSlotHashMaps
                    || searchable.contains("dense slot")
                    && searchable.contains("hashmaps")
                    && containsNormalizedCode(normalizedRawCode, "Map<Integer, Integer> indexToValue")
                    && containsNormalizedCode(normalizedRawCode, "Map<Integer, Integer> valueToIndex")
                    && containsNormalizedCode(normalizedRawCode, "indexToValue.get(random.nextInt(size))");
            hasEntryObjectDenseArray = hasEntryObjectDenseArray
                    || searchable.contains("entry object")
                    && searchable.contains("dense array")
                    && containsNormalizedCode(normalizedRawCode, "private static class Entry")
                    && containsNormalizedCode(normalizedRawCode, "int index")
                    && containsNormalizedCode(normalizedRawCode, "Entry last = dense.remove(dense.size() - 1)")
                    && containsNormalizedCode(normalizedRawCode, "last.index = index");
            hasPrimitiveOpenAddressing = hasPrimitiveOpenAddressing
                    || searchable.contains("open addressing")
                    && containsNormalizedCode(normalizedRawCode, "byte[] states")
                    && containsNormalizedCode(normalizedRawCode, "findKey(int key)")
                    && containsNormalizedCode(normalizedRawCode, "findInsertSlot(int key)")
                    && containsNormalizedCode(normalizedRawCode, "states[slot] = 2")
                    && containsNormalizedCode(normalizedRawCode, "indexes[lastSlot] = index");
        }

        assertTrue(hasArrayListIndexMap,
                filename + " must include the ArrayList index-map route");
        assertTrue(hasDynamicIntArray,
                filename + " must include the dynamic int-array index-map route");
        assertTrue(hasDenseSlotHashMaps,
                filename + " must include the dense-slot HashMaps route");
        assertTrue(hasEntryObjectDenseArray,
                filename + " must include the entry-object dense-array route");
        assertTrue(hasPrimitiveOpenAddressing,
                filename + " must include the primitive open-addressing index-map route");
    }

