    private static void assertAllOneDataStructureSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " AllOne should teach key-to-bucket lists, count-bucket indexes, circular sentinels, "
                        + "intrusive key-node bucket lists, and bounded count-bucket arrays");

        boolean hasKeyToBucketList = false;
        boolean hasCountBucketIndex = false;
        boolean hasCircularKeyRecords = false;
        boolean hasIntrusiveKeyNodes = false;
        boolean hasBoundedCountArray = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasKeyToBucketList = hasKeyToBucketList
                    || searchable.contains("key-to-bucket")
                    && containsNormalizedCode(normalizedRawCode, "Map<String, Bucket> keyBucket")
                    && containsNormalizedCode(normalizedRawCode, "java.util.LinkedHashSet<String> keys")
                    && containsNormalizedCode(normalizedRawCode, "move(key, current, target)")
                    && containsNormalizedCode(normalizedRawCode, "tail.prev.keys.iterator().next()");
            hasCountBucketIndex = hasCountBucketIndex
                    || searchable.contains("count map")
                    && searchable.contains("bucket index")
                    && containsNormalizedCode(normalizedRawCode, "Map<String, Integer> keyCount")
                    && containsNormalizedCode(normalizedRawCode, "Map<Integer, Bucket> countBucket")
                    && containsNormalizedCode(normalizedRawCode, "countBucket.put(bucket.count, bucket)")
                    && containsNormalizedCode(normalizedRawCode, "countBucket.remove(bucket.count)");
            hasCircularKeyRecords = hasCircularKeyRecords
                    || searchable.contains("circular")
                    && searchable.contains("key records")
                    && containsNormalizedCode(normalizedRawCode, "private static class Entry")
                    && containsNormalizedCode(normalizedRawCode, "Map<String, Entry> entries")
                    && containsNormalizedCode(normalizedRawCode, "root.prev = root")
                    && containsNormalizedCode(normalizedRawCode, "entry.bucket = to");
            hasIntrusiveKeyNodes = hasIntrusiveKeyNodes
                    || searchable.contains("intrusive")
                    && searchable.contains("key nodes")
                    && containsNormalizedCode(normalizedRawCode, "Entry head = new Entry(\"\")")
                    && containsNormalizedCode(normalizedRawCode, "Entry tail = new Entry(\"\")")
                    && containsNormalizedCode(normalizedRawCode, "detachEntry(entry)")
                    && containsNormalizedCode(normalizedRawCode, "addEntry(target, entry)")
                    && containsNormalizedCode(normalizedRawCode, "entry.bucket = bucket");
            hasBoundedCountArray = hasBoundedCountArray
                    || searchable.contains("bounded")
                    && searchable.contains("count bucket array")
                    && containsNormalizedCode(normalizedRawCode, "MAX_CALLS = 50000")
                    && containsNormalizedCode(normalizedRawCode, "Bucket[] countBuckets")
                    && containsNormalizedCode(normalizedRawCode, "countBuckets[bucket.count] = bucket")
                    && containsNormalizedCode(normalizedRawCode, "countBuckets[bucket.count] = null");
        }

        assertTrue(hasKeyToBucketList,
                filename + " must include the key-to-bucket doubly linked-list route");
        assertTrue(hasCountBucketIndex,
                filename + " must include the count-map bucket-index route");
        assertTrue(hasCircularKeyRecords,
                filename + " must include the circular bucket list with key records route");
        assertTrue(hasIntrusiveKeyNodes,
                filename + " must include the intrusive key-node bucket-list route");
        assertTrue(hasBoundedCountArray,
                filename + " must include the bounded count-bucket array route");
    }

