    private static String atmTestCaseKey(String input, String output) {
        return compactOutsideDoubleQuotedText(input) + "|" + output.replaceAll("\\s+", "");
    }

    private static void assertDesignAtmMachineSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " ATM should teach a fixed-array greedy plan, temporary inventory copy, in-place "
                        + "rollback, recursive denomination planning, and denomination-object ledger");

        boolean hasFixedArrayPlan = false;
        boolean hasTemporaryCopy = false;
        boolean hasInPlaceRollback = false;
        boolean hasRecursivePlanner = false;
        boolean hasObjectLedger = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasFixedArrayPlan = hasFixedArrayPlan
                    || (searchable.contains("fixed array")
                    && searchable.contains("plan")
                    && containsNormalizedCode(normalizedRawCode, "private final long[] stock = new long[5]")
                    && containsNormalizedCode(normalizedRawCode, "int[] plan = new int[VALUES.length]")
                    && containsNormalizedCode(normalizedRawCode, "stock[i] -= plan[i]"));
            hasTemporaryCopy = hasTemporaryCopy
                    || (searchable.contains("temporary")
                    && searchable.contains("copy")
                    && containsNormalizedCode(normalizedRawCode, "private long[] inventory = new long[5]")
                    && containsNormalizedCode(normalizedRawCode, "long[] trial = inventory.clone()")
                    && containsNormalizedCode(normalizedRawCode, "inventory = trial"));
            hasInPlaceRollback = hasInPlaceRollback
                    || (searchable.contains("rollback")
                    && containsNormalizedCode(normalizedRawCode, "private final long[] cash = new long[5]")
                    && containsNormalizedCode(normalizedRawCode, "cash[i] -= take")
                    && containsNormalizedCode(normalizedRawCode, "cash[i] += used[i]"));
            hasRecursivePlanner = hasRecursivePlanner
                    || (searchable.contains("recursive")
                    && containsNormalizedCode(normalizedRawCode, "fillPlan(VALUES.length - 1, amount, plan)")
                    && containsNormalizedCode(normalizedRawCode, "private boolean fillPlan")
                    && containsNormalizedCode(normalizedRawCode, "return fillPlan(index - 1"));
            hasObjectLedger = hasObjectLedger
                    || (searchable.contains("object ledger")
                    && containsNormalizedCode(normalizedRawCode, "private static class Cassette")
                    && containsNormalizedCode(normalizedRawCode, "final int value")
                    && containsNormalizedCode(normalizedRawCode, "long count")
                    && containsNormalizedCode(normalizedRawCode, "cassettes[i].count += banknotesCount[i]")
                    && containsNormalizedCode(normalizedRawCode, "Cassette cassette = cassettes[i]"));
        }

        assertTrue(hasFixedArrayPlan,
                filename + " must include the fixed-array greedy-plan route");
        assertTrue(hasTemporaryCopy,
                filename + " must include the temporary-inventory-copy route");
        assertTrue(hasInPlaceRollback,
                filename + " must include the in-place greedy rollback route");
        assertTrue(hasRecursivePlanner,
                filename + " must include the recursive denomination-planner route");
        assertTrue(hasObjectLedger,
                filename + " must include the denomination-object ledger route");
    }

