    private static void assertDesignFoodRatingSystemSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " FoodRatings should teach ordered sets, lazy heaps, rating buckets, indexed heaps, "
                        + "and square-root cuisine blocks");

        boolean hasOrderedSet = false;
        boolean hasLazyHeap = false;
        boolean hasRatingBuckets = false;
        boolean hasIndexedHeap = false;
        boolean hasSqrtBlocks = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasOrderedSet = hasOrderedSet
                    || (searchable.contains("ordered set")
                    && searchable.contains("cuisine")
                    && containsNormalizedCode(normalizedRawCode, "TreeSet<String>")
                    && containsNormalizedCode(normalizedRawCode, "set.remove(food)")
                    && containsNormalizedCode(normalizedRawCode, "set.add(food)")
                    && containsNormalizedCode(normalizedRawCode, "first()"));
            hasLazyHeap = hasLazyHeap
                    || (searchable.contains("lazy")
                    && searchable.contains("heap")
                    && containsNormalizedCode(normalizedRawCode, "PriorityQueue<Entry>")
                    && containsNormalizedCode(normalizedRawCode, "top.rating == foodRating.get(top.food)")
                    && containsNormalizedCode(normalizedRawCode, "heap.poll()"));
            hasRatingBuckets = hasRatingBuckets
                    || (searchable.contains("bucket")
                    && containsNormalizedCode(normalizedRawCode, "java.util.TreeMap<Integer, java.util.TreeSet<String>>")
                    && containsNormalizedCode(normalizedRawCode, "lastEntry()")
                    && containsNormalizedCode(normalizedRawCode, "removeFromBucket"));
            hasIndexedHeap = hasIndexedHeap
                    || (searchable.contains("indexed")
                    && searchable.contains("heap")
                    && containsNormalizedCode(normalizedRawCode, "private class FoodHeap")
                    && containsNormalizedCode(normalizedRawCode, "private final java.util.Map<String, Integer> position")
                    && containsNormalizedCode(normalizedRawCode, "siftUp")
                    && containsNormalizedCode(normalizedRawCode, "siftDown")
                    && containsNormalizedCode(normalizedRawCode, "swap"));
            hasSqrtBlocks = hasSqrtBlocks
                    || (searchable.contains("square-root")
                    && searchable.contains("block")
                    && containsNormalizedCode(normalizedRawCode, "private class CuisineBlock")
                    && containsNormalizedCode(normalizedRawCode, "blockBest")
                    && containsNormalizedCode(normalizedRawCode, "blockSize = (int) Math.sqrt")
                    && containsNormalizedCode(normalizedRawCode, "recompute"));
        }

        assertTrue(hasOrderedSet,
                filename + " must include the ordered-set per cuisine route");
        assertTrue(hasLazyHeap,
                filename + " must include the lazy-heap current-rating route");
        assertTrue(hasRatingBuckets,
                filename + " must include the rating-buckets per cuisine route");
        assertTrue(hasIndexedHeap,
                filename + " must include the indexed binary-heap route");
        assertTrue(hasSqrtBlocks,
                filename + " must include the square-root cuisine-blocks route");
    }

