    private static void assertDesignTextEditorSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 5,
                filename + " TextEditor should teach two halves, cursor-index StringBuilder, linked-list cursor, "
                        + "gap buffer, and implicit Treap rope routes");

        boolean hasTwoHalves = false;
        boolean hasStringBuilderCursor = false;
        boolean hasLinkedListCursor = false;
        boolean hasGapBuffer = false;
        boolean hasTreapRope = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasTwoHalves = hasTwoHalves
                    || (searchable.contains("two")
                    && searchable.contains("halves")
                    && containsNormalizedCode(normalizedRawCode,
                    "private final StringBuilder left = new StringBuilder()")
                    && containsNormalizedCode(normalizedRawCode,
                    "private final StringBuilder rightReversed = new StringBuilder()")
                    && containsNormalizedCode(normalizedRawCode,
                    "rightReversed.append(left.charAt(left.length() - 1))")
                    && containsNormalizedCode(normalizedRawCode,
                    "left.append(rightReversed.charAt(rightReversed.length() - 1))"));
            hasStringBuilderCursor = hasStringBuilderCursor
                    || (searchable.contains("cursor index")
                    && containsNormalizedCode(normalizedRawCode,
                    "private final StringBuilder text = new StringBuilder()")
                    && containsNormalizedCode(normalizedRawCode, "private int cursor = 0")
                    && containsNormalizedCode(normalizedRawCode, "text.insert(cursor, value)")
                    && containsNormalizedCode(normalizedRawCode, "text.delete(start, cursor)"));
            hasLinkedListCursor = hasLinkedListCursor
                    || (searchable.contains("linked list")
                    && searchable.contains("cursor")
                    && containsNormalizedCode(normalizedRawCode, "private static class Node")
                    && containsNormalizedCode(normalizedRawCode, "Node prev")
                    && containsNormalizedCode(normalizedRawCode, "Node next")
                    && containsNormalizedCode(normalizedRawCode, "private final Node head")
                    && containsNormalizedCode(normalizedRawCode, "insertAfter(cursor, node)")
                    && containsNormalizedCode(normalizedRawCode, "unlink(remove)"));
            hasGapBuffer = hasGapBuffer
                    || (searchable.contains("gap buffer")
                    && containsNormalizedCode(normalizedRawCode, "private char[] buffer = new char[64]")
                    && containsNormalizedCode(normalizedRawCode, "private int gapStart = 0")
                    && containsNormalizedCode(normalizedRawCode, "private int gapEnd = buffer.length")
                    && containsNormalizedCode(normalizedRawCode, "ensureGap(text.length())")
                    && containsNormalizedCode(normalizedRawCode, "buffer[--gapEnd] = buffer[--gapStart]")
                    && containsNormalizedCode(normalizedRawCode, "buffer[gapStart++] = buffer[gapEnd++]"));
            hasTreapRope = hasTreapRope
                    || (searchable.contains("treap")
                    && searchable.contains("rope")
                    && containsNormalizedCode(normalizedRawCode, "int priority")
                    && containsNormalizedCode(normalizedRawCode, "int size = 1")
                    && containsNormalizedCode(normalizedRawCode, "Node[] split = split(root, cursor)")
                    && containsNormalizedCode(normalizedRawCode, "root = merge(merge(split[0], build(text)), split[1])")
                    && containsNormalizedCode(normalizedRawCode, "private Node[] split")
                    && containsNormalizedCode(normalizedRawCode, "private Node merge"));
        }

        assertTrue(hasTwoHalves,
                filename + " must include the two StringBuilder halves route");
        assertTrue(hasStringBuilderCursor,
                filename + " must include the single StringBuilder cursor-index route");
        assertTrue(hasLinkedListCursor,
                filename + " must include the doubly linked-list cursor route");
        assertTrue(hasGapBuffer,
                filename + " must include the gap-buffer route");
        assertTrue(hasTreapRope,
                filename + " must include the implicit Treap rope route");
    }

