    private static void assertFindMissingObservationsSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 4,
                filename + " Find Missing Observations should teach quotient-remainder distribution, "
                        + "ones plus greedy top-up, lower-bound feasibility fill, and upper-reserve fill");

        boolean hasQuotientRemainder = false;
        boolean hasOnesTopUp = false;
        boolean hasLowerBoundFill = false;
        boolean hasUpperReserveFill = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasQuotientRemainder = hasQuotientRemainder
                    || ((searchable.contains("quotient") || searchable.contains("remainder"))
                    && containsNormalizedCode(normalizedRawCode, "int base = missingSum / n")
                    && containsNormalizedCode(normalizedRawCode, "int extra = missingSum % n")
                    && containsNormalizedCode(normalizedRawCode, "result[i] = base + (i < extra ? 1 : 0)"));
            hasOnesTopUp = hasOnesTopUp
                    || ((searchable.contains("ones") || searchable.contains("top-up"))
                    && containsNormalizedCode(normalizedRawCode, "java.util.Arrays.fill(result, 1)")
                    && containsNormalizedCode(normalizedRawCode, "int remaining = missingSum - n")
                    && containsNormalizedCode(normalizedRawCode, "int add = Math.min(5, remaining)")
                    && containsNormalizedCode(normalizedRawCode, "result[i] += add"));
            hasLowerBoundFill = hasLowerBoundFill
                    || ((searchable.contains("lower bound") || searchable.contains("feasibility"))
                    && containsNormalizedCode(normalizedRawCode, "int remainingSlots = n - i - 1")
                    && containsNormalizedCode(normalizedRawCode, "int value = Math.max(1, missingSum - 6 * remainingSlots)")
                    && containsNormalizedCode(normalizedRawCode, "missingSum -= value"));
            hasUpperReserveFill = hasUpperReserveFill
                    || ((searchable.contains("upper") || searchable.contains("reserve"))
                    && containsNormalizedCode(normalizedRawCode, "int remainingSlots = n - i - 1")
                    && containsNormalizedCode(normalizedRawCode, "int value = Math.min(6, missingSum - remainingSlots)")
                    && containsNormalizedCode(normalizedRawCode, "missingSum -= value"));
        }

        assertTrue(hasQuotientRemainder,
                filename + " must include the quotient-remainder distribution route");
        assertTrue(hasOnesTopUp,
                filename + " must include the ones plus greedy top-up route");
        assertTrue(hasLowerBoundFill,
                filename + " must include the lower-bound feasibility fill route");
        assertTrue(hasUpperReserveFill,
                filename + " must include the upper-reserve fill route");
    }

