    private static void assertBinaryTreeTiltSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 4,
                filename + " Binary Tree Tilt should teach recursive accumulator, pair-return recursion, "
                        + "two-stack postorder, and visited-flag postorder");

        boolean hasRecursiveAccumulator = false;
        boolean hasRecursivePair = false;
        boolean hasTwoStackPostorder = false;
        boolean hasVisitedFlagPostorder = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasRecursiveAccumulator = hasRecursiveAccumulator
                    || ((searchable.contains("accumulator") || searchable.contains("postorder"))
                    && containsNormalizedCode(normalizedRawCode, "private int totalTilt = 0")
                    && containsNormalizedCode(normalizedRawCode, "int leftSum = subtreeSum(node.left)")
                    && containsNormalizedCode(normalizedRawCode, "totalTilt += Math.abs(leftSum - rightSum)")
                    && containsNormalizedCode(normalizedRawCode, "return node.val + leftSum + rightSum"));
            hasRecursivePair = hasRecursivePair
                    || (searchable.contains("pair")
                    && containsNormalizedCode(normalizedRawCode, "return solve(root)[1]")
                    && containsNormalizedCode(normalizedRawCode, "int[] left = solve(node.left)")
                    && containsNormalizedCode(normalizedRawCode,
                    "int subtreeSum = node.val + left[0] + right[0]")
                    && containsNormalizedCode(normalizedRawCode,
                    "int tiltTotal = left[1] + right[1] + Math.abs(left[0] - right[0])"));
            hasTwoStackPostorder = hasTwoStackPostorder
                    || ((searchable.contains("two-stack") || searchable.contains("two stack"))
                    && containsNormalizedCode(normalizedRawCode,
                    "java.util.ArrayDeque<TreeNode> stack = new java.util.ArrayDeque<>()")
                    && containsNormalizedCode(normalizedRawCode,
                    "java.util.ArrayDeque<TreeNode> postorder = new java.util.ArrayDeque<>()")
                    && containsNormalizedCode(normalizedRawCode, "postorder.push(node)")
                    && containsNormalizedCode(normalizedRawCode,
                    "subtreeSums.put(node, node.val + leftSum + rightSum)"));
            hasVisitedFlagPostorder = hasVisitedFlagPostorder
                    || ((searchable.contains("visited") || searchable.contains("flag"))
                    && containsNormalizedCode(normalizedRawCode,
                    "java.util.ArrayDeque<TreeNode> nodeStack = new java.util.ArrayDeque<>()")
                    && containsNormalizedCode(normalizedRawCode,
                    "java.util.ArrayDeque<Boolean> visitedStack = new java.util.ArrayDeque<>()")
                    && containsNormalizedCode(normalizedRawCode, "visitedStack.push(false)")
                    && containsNormalizedCode(normalizedRawCode, "visitedStack.push(true)")
                    && containsNormalizedCode(normalizedRawCode,
                    "subtreeSums.put(node, node.val + leftSum + rightSum)"));
        }

        assertTrue(hasRecursiveAccumulator,
                filename + " must include the recursive postorder accumulator route");
        assertTrue(hasRecursivePair,
                filename + " must include the recursive sum-and-tilt pair route");
        assertTrue(hasTwoStackPostorder,
                filename + " must include the two-stack iterative postorder route");
        assertTrue(hasVisitedFlagPostorder,
                filename + " must include the visited-flag iterative postorder route");
    }

