    private static void assertReshapeMatrixSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 4,
                filename + " Reshape the Matrix should teach linear index mapping, source-scan target counter, "
                        + "array flattening, and queue flattening");

        boolean hasLinearIndexMapping = false;
        boolean hasSourceScanCounter = false;
        boolean hasFlattenArray = false;
        boolean hasFlattenQueue = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasLinearIndexMapping = hasLinearIndexMapping
                    || ((searchable.contains("linear") || searchable.contains("index"))
                    && containsNormalizedCode(normalizedRawCode,
                    "for (int index = 0; index < rows * cols; index++)")
                    && containsNormalizedCode(normalizedRawCode,
                    "reshaped[index / c][index % c] = mat[index / cols][index % cols]"));
            hasSourceScanCounter = hasSourceScanCounter
                    || ((searchable.contains("source") || searchable.contains("counter"))
                    && containsNormalizedCode(normalizedRawCode, "int targetRow = 0")
                    && containsNormalizedCode(normalizedRawCode, "int targetCol = 0")
                    && containsNormalizedCode(normalizedRawCode, "reshaped[targetRow][targetCol] = mat[i][j]")
                    && containsNormalizedCode(normalizedRawCode, "if (targetCol == c)"));
            hasFlattenArray = hasFlattenArray
                    || ((searchable.contains("flat") || searchable.contains("array"))
                    && containsNormalizedCode(normalizedRawCode, "int[] flat = new int[rows * cols]")
                    && containsNormalizedCode(normalizedRawCode, "flat[write++] = mat[i][j]")
                    && containsNormalizedCode(normalizedRawCode, "reshaped[i][j] = flat[read++]"));
            hasFlattenQueue = hasFlattenQueue
                    || ((searchable.contains("queue") || searchable.contains("flatten"))
                    && containsNormalizedCode(
                    normalizedRawCode, "java.util.ArrayDeque<Integer> values = new java.util.ArrayDeque<>()")
                    && containsNormalizedCode(normalizedRawCode, "values.addLast(mat[i][j])")
                    && containsNormalizedCode(normalizedRawCode, "values.removeFirst()"));
        }

        assertTrue(hasLinearIndexMapping,
                filename + " must include the linear index mapping route");
        assertTrue(hasSourceScanCounter,
                filename + " must include the source-scan target-counter route");
        assertTrue(hasFlattenArray,
                filename + " must include the array flatten-and-rebuild route");
        assertTrue(hasFlattenQueue,
                filename + " must include the queue flatten-and-fill route");
    }

