    private static void assertMinimumFallingPathSumIISolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 4,
                filename + " Minimum Falling Path Sum II should teach full-table two-minimum DP, "
                        + "prefix/suffix minima DP, rolling two-minimum optimization, "
                        + "and in-place two-minimum optimization");

        boolean hasFullTableTwoMinimums = false;
        boolean hasPrefixSuffixMinima = false;
        boolean hasRollingTwoMinimums = false;
        boolean hasInPlaceTwoMinimums = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasFullTableTwoMinimums = hasFullTableTwoMinimums
                    || ((searchable.contains("full table") || searchable.contains("table"))
                    && containsNormalizedCode(normalizedRawCode, "int[][] dp = new int[n][n]")
                    && containsNormalizedCode(normalizedRawCode, "dp[0][col] = grid[0][col]")
                    && containsNormalizedCode(normalizedRawCode,
                    "int bestPrevious = col == minCol ? dp[row - 1][secondMinCol] : dp[row - 1][minCol]")
                    && containsNormalizedCode(normalizedRawCode,
                    "dp[row][col] = grid[row][col] + bestPrevious"));
            hasPrefixSuffixMinima = hasPrefixSuffixMinima
                    || ((searchable.contains("prefix") || searchable.contains("suffix"))
                    && containsNormalizedCode(normalizedRawCode, "int[] prefixMin = new int[n]")
                    && containsNormalizedCode(normalizedRawCode, "int[] suffixMin = new int[n]")
                    && containsNormalizedCode(normalizedRawCode,
                    "prefixMin[col] = Math.min(prefixMin[col - 1], previous[col])")
                    && containsNormalizedCode(normalizedRawCode,
                    "suffixMin[col] = Math.min(suffixMin[col + 1], previous[col])")
                    && containsNormalizedCode(normalizedRawCode, "suffixMin[col + 1]"));
            hasRollingTwoMinimums = hasRollingTwoMinimums
                    || ((searchable.contains("rolling") || searchable.contains("two minimum"))
                    && containsNormalizedCode(normalizedRawCode, "int[] previous = grid[0].clone()")
                    && containsNormalizedCode(normalizedRawCode, "int minCol = -1")
                    && containsNormalizedCode(normalizedRawCode, "int secondMinCol = -1")
                    && containsNormalizedCode(normalizedRawCode, "int[] current = new int[n]")
                    && containsNormalizedCode(normalizedRawCode, "previous = current"));
            hasInPlaceTwoMinimums = hasInPlaceTwoMinimums
                    || ((searchable.contains("in-place") || searchable.contains("in place"))
                    && containsNormalizedCode(normalizedRawCode,
                    "grid[row - 1][col] < grid[row - 1][minCol]")
                    && containsNormalizedCode(normalizedRawCode,
                    "int bestPrevious = col == minCol ? grid[row - 1][secondMinCol] : grid[row - 1][minCol]")
                    && containsNormalizedCode(normalizedRawCode, "grid[row][col] += bestPrevious")
                    && containsNormalizedCode(normalizedRawCode, "for (int value : grid[n - 1])"));
        }

        assertTrue(hasFullTableTwoMinimums,
                filename + " must include the full-table two-minimum DP route");
        assertTrue(hasPrefixSuffixMinima,
                filename + " must include the prefix/suffix minima DP route");
        assertTrue(hasRollingTwoMinimums,
                filename + " must include the rolling two-minimum DP route");
        assertTrue(hasInPlaceTwoMinimums,
                filename + " must include the in-place two-minimum DP route");
    }

