    private static void assertMergeTwoBinaryTreesSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 3,
                filename + " Merge Two Binary Trees should teach recursive new-tree construction, "
                        + "recursive in-place DFS, and iterative BFS in-place merging");

        boolean hasRecursiveNewTreeMerge = false;
        boolean hasRecursiveInPlaceDfsMerge = false;
        boolean hasIterativeBfsInPlaceMerge = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasRecursiveNewTreeMerge = hasRecursiveNewTreeMerge
                    || ((searchable.contains("new tree") || searchable.contains("fresh result")
                    || searchable.contains("clone"))
                    && containsNormalizedCode(normalizedRawCode, "TreeNode merged = new TreeNode(root1.val + root2.val)")
                    && containsNormalizedCode(normalizedRawCode, "merged.left = mergeTrees(root1.left, root2.left)")
                    && containsNormalizedCode(normalizedRawCode, "merged.right = mergeTrees(root1.right, root2.right)")
                    && containsNormalizedCode(normalizedRawCode, "return cloneTree(root2)")
                    && containsNormalizedCode(normalizedRawCode, "private TreeNode cloneTree(TreeNode node)"));
            hasRecursiveInPlaceDfsMerge = hasRecursiveInPlaceDfsMerge
                    || ((searchable.contains("in-place") || searchable.contains("dfs"))
                    && !containsNormalizedCode(normalizedRawCode, "java.util.Queue")
                    && containsNormalizedCode(normalizedRawCode, "root1.val += root2.val")
                    && containsNormalizedCode(normalizedRawCode, "root1.left = mergeTrees(root1.left, root2.left)")
                    && containsNormalizedCode(normalizedRawCode, "root1.right = mergeTrees(root1.right, root2.right)")
                    && containsNormalizedCode(normalizedRawCode, "return root1"));
            hasIterativeBfsInPlaceMerge = hasIterativeBfsInPlaceMerge
                    || ((searchable.contains("bfs") || searchable.contains("queue"))
                    && containsNormalizedCode(normalizedRawCode,
                    "java.util.Queue<TreeNode[]> queue = new java.util.ArrayDeque<>()")
                    && containsNormalizedCode(normalizedRawCode, "queue.offer(new TreeNode[]{root1, root2})")
                    && containsNormalizedCode(normalizedRawCode, "TreeNode[] pair = queue.poll()")
                    && containsNormalizedCode(normalizedRawCode, "first.val += second.val")
                    && containsNormalizedCode(normalizedRawCode, "first.left = second.left")
                    && containsNormalizedCode(normalizedRawCode, "first.right = second.right"));
        }

        assertTrue(hasRecursiveNewTreeMerge,
                filename + " must include the recursive new-tree merge route");
        assertTrue(hasRecursiveInPlaceDfsMerge,
                filename + " must include the recursive in-place DFS merge route");
        assertTrue(hasIterativeBfsInPlaceMerge,
                filename + " must include the iterative BFS in-place merge route");
    }

