    private static void assertMaximumDistanceInArraysSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 3,
                filename + " Maximum Distance in Arrays should teach update-order global endpoints, "
                        + "sorted endpoint candidates, and prefix/suffix exclusion arrays");

        boolean hasGlobalEndpointScan = false;
        boolean hasSortedEndpointCandidates = false;
        boolean hasPrefixSuffixExtremes = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasGlobalEndpointScan = hasGlobalEndpointScan
                    || ((searchable.contains("global") && searchable.contains("before updating"))
                    && containsNormalizedCode(normalizedRawCode, "int globalMin = arrays.get(0).get(0)")
                    && containsNormalizedCode(normalizedRawCode, "int globalMax = arrays.get(0).get(arrays.get(0).size() - 1)")
                    && containsNormalizedCode(normalizedRawCode, "result = Math.max(result, curMax - globalMin)")
                    && containsNormalizedCode(normalizedRawCode, "result = Math.max(result, globalMax - curMin)")
                    && containsNormalizedCode(normalizedRawCode, "globalMin = Math.min(globalMin, curMin)")
                    && containsNormalizedCode(normalizedRawCode, "globalMax = Math.max(globalMax, curMax)"));
            hasSortedEndpointCandidates = hasSortedEndpointCandidates
                    || ((searchable.contains("sort") && searchable.contains("candidate"))
                    && containsNormalizedCode(normalizedRawCode, "int[][] minArr = new int[m][2]")
                    && containsNormalizedCode(normalizedRawCode, "int[][] maxArr = new int[m][2]")
                    && containsNormalizedCode(normalizedRawCode, "java.util.Arrays.sort(minArr")
                    && containsNormalizedCode(normalizedRawCode, "java.util.Arrays.sort(maxArr")
                    && containsNormalizedCode(normalizedRawCode, "if (minArr[0][1] != maxArr[0][1])")
                    && containsNormalizedCode(normalizedRawCode,
                    "return Math.max(maxArr[0][0] - minArr[1][0], maxArr[1][0] - minArr[0][0])"));
            hasPrefixSuffixExtremes = hasPrefixSuffixExtremes
                    || ((searchable.contains("prefix") && searchable.contains("suffix"))
                    && containsNormalizedCode(normalizedRawCode, "int[] prefixMin = new int[m]")
                    && containsNormalizedCode(normalizedRawCode, "int[] prefixMax = new int[m]")
                    && containsNormalizedCode(normalizedRawCode, "int[] suffixMin = new int[m]")
                    && containsNormalizedCode(normalizedRawCode, "int[] suffixMax = new int[m]")
                    && containsNormalizedCode(normalizedRawCode, "best = Math.max(best, last - prefixMin[i - 1])")
                    && containsNormalizedCode(normalizedRawCode, "best = Math.max(best, suffixMax[i + 1] - first)"));
        }

        assertTrue(hasGlobalEndpointScan,
                filename + " must include the update-order global endpoint scan route");
        assertTrue(hasSortedEndpointCandidates,
                filename + " must include the sorted endpoint-candidate route");
        assertTrue(hasPrefixSuffixExtremes,
                filename + " must include the prefix/suffix exclusion route");
    }

