    private static void assertCountCompleteSubarraysSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 3,
                filename + " Count Complete Subarrays should teach HashMap sliding window, "
                        + "enumeration baseline, and bounded frequency-array sliding window");

        boolean hasHashMapSlidingWindow = false;
        boolean hasEnumerationBaseline = false;
        boolean hasFrequencyArraySlidingWindow = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasHashMapSlidingWindow = hasHashMapSlidingWindow
                    || ((searchable.contains("hashmap") || searchable.contains("frequency map"))
                    && containsNormalizedCode(normalizedRawCode,
                    "java.util.Map<Integer, Integer> window = new java.util.HashMap<>()")
                    && containsNormalizedCode(normalizedRawCode, "int requiredDistinct = allValues.size()")
                    && containsNormalizedCode(normalizedRawCode, "while (window.size() == requiredDistinct)")
                    && containsNormalizedCode(normalizedRawCode, "answer += nums.length - right")
                    && containsNormalizedCode(normalizedRawCode, "window.remove(leaving)"));
            hasEnumerationBaseline = hasEnumerationBaseline
                    || ((searchable.contains("enumerate") || searchable.contains("baseline"))
                    && containsNormalizedCode(normalizedRawCode, "for (int left = 0; left < nums.length; left++)")
                    && containsNormalizedCode(normalizedRawCode, "for (int right = left; right < nums.length; right++)")
                    && containsNormalizedCode(normalizedRawCode, "seen.add(nums[right])")
                    && containsNormalizedCode(normalizedRawCode, "if (seen.size() == requiredDistinct)")
                    && containsNormalizedCode(normalizedRawCode, "answer++"));
            hasFrequencyArraySlidingWindow = hasFrequencyArraySlidingWindow
                    || ((searchable.contains("frequency array") || searchable.contains("value domain"))
                    && containsNormalizedCode(normalizedRawCode, "boolean[] exists = new boolean[2001]")
                    && containsNormalizedCode(normalizedRawCode, "int[] freq = new int[2001]")
                    && containsNormalizedCode(normalizedRawCode, "if (freq[nums[right]]++ == 0)")
                    && containsNormalizedCode(normalizedRawCode, "while (inside == totalDistinct)")
                    && containsNormalizedCode(normalizedRawCode, "answer += nums.length - right"));
        }

        assertTrue(hasHashMapSlidingWindow,
                filename + " must include the HashMap sliding-window route");
        assertTrue(hasEnumerationBaseline,
                filename + " must include the enumeration baseline route");
        assertTrue(hasFrequencyArraySlidingWindow,
                filename + " must include the frequency-array sliding-window route");
    }

