    private static void assertTwoKeysKeyboardSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 4,
                filename + " 2 Keys Keyboard should teach prime factorization, largest-divisor recurrence, "
                        + "bottom-up divisor DP, and top-down memoized divisor DP routes");

        boolean hasPrimeFactorization = false;
        boolean hasLargestDivisorRecurrence = false;
        boolean hasBottomUpDivisorDp = false;
        boolean hasTopDownMemoizedDp = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasPrimeFactorization = hasPrimeFactorization
                    || ((searchable.contains("prime") || searchable.contains("factorization"))
                    && containsNormalizedCode(normalizedRawCode, "int answer = 0")
                    && containsNormalizedCode(normalizedRawCode, "for (int factor = 2; factor * factor <= n; factor++)")
                    && containsNormalizedCode(normalizedRawCode, "while (n % factor == 0)")
                    && containsNormalizedCode(normalizedRawCode, "answer += factor")
                    && containsNormalizedCode(normalizedRawCode, "n /= factor"));
            hasLargestDivisorRecurrence = hasLargestDivisorRecurrence
                    || ((searchable.contains("largest") || searchable.contains("recurrence"))
                    && containsNormalizedCode(normalizedRawCode, "for (int base = target / 2; base >= 1; base--)")
                    && containsNormalizedCode(normalizedRawCode, "if (target % base == 0)")
                    && containsNormalizedCode(normalizedRawCode, "return solve(base) + target / base"));
            hasBottomUpDivisorDp = hasBottomUpDivisorDp
                    || ((searchable.contains("bottom") || searchable.contains("divisor dp"))
                    && containsNormalizedCode(normalizedRawCode, "int[] dp = new int[n + 1]")
                    && containsNormalizedCode(normalizedRawCode, "for (int i = 2; i <= n; i++)")
                    && containsNormalizedCode(normalizedRawCode, "dp[i] = i")
                    && containsNormalizedCode(normalizedRawCode, "dp[i] = Math.min(dp[i], dp[d] + i / d)")
                    && containsNormalizedCode(normalizedRawCode, "dp[i] = Math.min(dp[i], dp[i / d] + d)"));
            hasTopDownMemoizedDp = hasTopDownMemoizedDp
                    || ((searchable.contains("top") || searchable.contains("memo"))
                    && containsNormalizedCode(normalizedRawCode, "private int[] memo")
                    && containsNormalizedCode(normalizedRawCode, "if (memo[target] != 0)")
                    && containsNormalizedCode(normalizedRawCode, "best = Math.min(best, solve(d) + target / d)")
                    && containsNormalizedCode(normalizedRawCode, "best = Math.min(best, solve(target / d) + d)")
                    && containsNormalizedCode(normalizedRawCode, "memo[target] = best"));
        }

        assertTrue(hasPrimeFactorization,
                filename + " must include the prime-factorization route");
        assertTrue(hasLargestDivisorRecurrence,
                filename + " must include the largest-divisor recurrence route");
        assertTrue(hasBottomUpDivisorDp,
                filename + " must include the bottom-up divisor DP route");
        assertTrue(hasTopDownMemoizedDp,
                filename + " must include the top-down memoized divisor DP route");
    }

