        boolean hasDualIterators = false;
        boolean hasComplementSearch = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasDfsHashSet = hasDfsHashSet
                    || (searchable.contains("dfs")
                    && (searchable.contains("hashset") || searchable.contains("hash set"))
                    && containsNormalizedCode(normalizedRawCode,
                    "java.util.Set<Integer> seen = new java.util.HashSet<>()")
                    && containsNormalizedCode(normalizedRawCode, "seen.contains(k - node.val)")
                    && containsNormalizedCode(normalizedRawCode, "seen.add(node.val)")
                    && containsNormalizedCode(normalizedRawCode,
                    "return dfs(node.left, k) || dfs(node.right, k)"));
            hasBfsHashSet = hasBfsHashSet
                    || (searchable.contains("bfs")
                    && (searchable.contains("queue") || searchable.contains("level"))
                    && containsNormalizedCode(normalizedRawCode,
                    "java.util.Queue<TreeNode> queue = new java.util.ArrayDeque<>()")
                    && containsNormalizedCode(normalizedRawCode, "queue.add(root)")
                    && containsNormalizedCode(normalizedRawCode, "TreeNode node = queue.remove()")
                    && containsNormalizedCode(normalizedRawCode, "seen.contains(k - node.val)"));
            hasInorderTwoPointers = hasInorderTwoPointers
                    || (searchable.contains("inorder") && searchable.contains("two-pointer")
                    && containsNormalizedCode(normalizedRawCode, "inorder(root, values)")
                    && containsNormalizedCode(normalizedRawCode, "values.add(node.val)")
                    && containsNormalizedCode(normalizedRawCode, "while (left < right)")
                    && containsNormalizedCode(normalizedRawCode, "sum < k")
                    && containsNormalizedCode(normalizedRawCode, "left++")
                    && containsNormalizedCode(normalizedRawCode, "right--"));
            hasDualIterators = hasDualIterators
                    || (searchable.contains("iterator")
                    && containsNormalizedCode(normalizedRawCode, "BstIterator low = new BstIterator(root, false)")
                    && containsNormalizedCode(normalizedRawCode, "BstIterator high = new BstIterator(root, true)")
                    && containsNormalizedCode(normalizedRawCode, "while (left != right)")
                    && containsNormalizedCode(normalizedRawCode, "java.util.Deque<TreeNode> stack")
                    && containsNormalizedCode(normalizedRawCode, "reverse ? node.right : node.left"));
            hasComplementSearch = hasComplementSearch
                    || (searchable.contains("complement") && searchable.contains("search")
                    && containsNormalizedCode(normalizedRawCode,
                    "containsDifferentNode(root, k - node.val, node)")
                    && containsNormalizedCode(normalizedRawCode, "node != excluded")
                    && containsNormalizedCode(normalizedRawCode, "target < node.val")
                    && containsNormalizedCode(normalizedRawCode, "target > node.val"));
        }

        assertTrue(hasDfsHashSet,
                filename + " must include the DFS hash-set complement route");
        assertTrue(hasBfsHashSet,
                filename + " must include the BFS hash-set complement route");
        assertTrue(hasInorderTwoPointers,
                filename + " must include the inorder-list two-pointer route");
        assertTrue(hasDualIterators,
                filename + " must include the dual BST iterator route");
