    private static void assertMaximumBinaryTreeSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 4,
                filename + " Maximum Binary Tree should teach recursive max split, monotonic stack Cartesian tree, "
                        + "segment-tree RMQ, and sparse-table RMQ");

        boolean hasRecursiveSplit = false;
        boolean hasMonotonicStack = false;
        boolean hasSegmentTree = false;
        boolean hasSparseTable = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasRecursiveSplit = hasRecursiveSplit
                    || ((searchable.contains("recursive") || searchable.contains("split"))
                    && containsNormalizedCode(normalizedRawCode,
                    "return build(nums, 0, nums.length - 1)")
                    && containsNormalizedCode(normalizedRawCode,
                    "for (int i = left + 1; i <= right; i++)")
                    && containsNormalizedCode(normalizedRawCode, "nums[i] > nums[maxIndex]")
                    && containsNormalizedCode(normalizedRawCode,
                    "root.left = build(nums, left, maxIndex - 1)")
                    && containsNormalizedCode(normalizedRawCode,
                    "root.right = build(nums, maxIndex + 1, right)"));
            hasMonotonicStack = hasMonotonicStack
                    || ((searchable.contains("monotonic") || searchable.contains("cartesian"))
                    && containsNormalizedCode(normalizedRawCode,
                    "java.util.Deque<TreeNode> stack = new java.util.ArrayDeque<>()")
                    && containsNormalizedCode(normalizedRawCode,
                    "while (!stack.isEmpty() && stack.peek().val < value)")
                    && containsNormalizedCode(normalizedRawCode, "node.left = stack.pop()")
                    && containsNormalizedCode(normalizedRawCode, "stack.peek().right = node")
                    && containsNormalizedCode(normalizedRawCode, "stack.push(node)"));
            hasSegmentTree = hasSegmentTree
                    || (searchable.contains("segment")
                    && containsNormalizedCode(normalizedRawCode, "int[] tree")
                    && containsNormalizedCode(normalizedRawCode,
                    "buildIndexTree(1, 0, nums.length - 1)")
                    && containsNormalizedCode(normalizedRawCode,
                    "query(1, 0, nums.length - 1, left, right)")
                    && containsNormalizedCode(normalizedRawCode,
                    "return nums[first] >= nums[second] ? first : second"));
            hasSparseTable = hasSparseTable
                    || (searchable.contains("sparse")
                    && containsNormalizedCode(normalizedRawCode, "int[][] table")
                    && containsNormalizedCode(normalizedRawCode,
                    "logs[i] = logs[i / 2] + 1")
                    && containsNormalizedCode(normalizedRawCode,
                    "table[level][start] = better")
                    && containsNormalizedCode(normalizedRawCode, "queryMaxIndex(left, right)")
                    && containsNormalizedCode(normalizedRawCode, "right - span + 1"));
        }

        assertTrue(hasRecursiveSplit,
                filename + " must include the recursive maximum-split route");
        assertTrue(hasMonotonicStack,
                filename + " must include the monotonic-stack Cartesian-tree route");
        assertTrue(hasSegmentTree,
                filename + " must include the segment-tree RMQ route");
        assertTrue(hasSparseTable,
                filename + " must include the sparse-table RMQ route");
    }

