    private static void assertPrintBinaryTreeSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 4,
                filename + " Print Binary Tree should teach DFS offset placement, BFS coordinate queues, "
                        + "column-interval recursion, and coordinate collection before materialization");

        boolean hasDfsOffset = false;
        boolean hasBfsCoordinates = false;
        boolean hasIntervalRecursion = false;
        boolean hasCoordinateCollection = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasDfsOffset = hasDfsOffset
                    || ((searchable.contains("dfs") || searchable.contains("offset"))
                    && containsNormalizedCode(normalizedRawCode, "int height = getHeight(root) - 1")
                    && containsNormalizedCode(normalizedRawCode, "int cols = (1 << (height + 1)) - 1")
                    && containsNormalizedCode(normalizedRawCode,
                    "fill(res, root, 0, (cols - 1) / 2, height)")
                    && containsNormalizedCode(normalizedRawCode,
                    "res.get(r).set(c, String.valueOf(node.val))")
                    && containsNormalizedCode(normalizedRawCode,
                    "int offset = 1 << (height - r - 1)"));
            hasBfsCoordinates = hasBfsCoordinates
                    || ((searchable.contains("bfs") || searchable.contains("queue"))
                    && containsNormalizedCode(normalizedRawCode,
                    "java.util.Queue<TreeNode> nodeQ = new java.util.ArrayDeque<>()")
                    && containsNormalizedCode(normalizedRawCode,
                    "java.util.Queue<int[]> posQ = new java.util.ArrayDeque<>()")
                    && containsNormalizedCode(normalizedRawCode,
                    "posQ.offer(new int[]{0, (cols - 1) / 2})")
                    && containsNormalizedCode(normalizedRawCode, "nodeQ.offer(node.left)")
                    && containsNormalizedCode(normalizedRawCode, "nodeQ.offer(node.right)"));
            hasIntervalRecursion = hasIntervalRecursion
                    || ((searchable.contains("interval") || searchable.contains("midpoint"))
                    && containsNormalizedCode(normalizedRawCode, "place(root, 0, 0, cols - 1, answer)")
                    && containsNormalizedCode(normalizedRawCode, "int mid = (left + right) >>> 1")
                    && containsNormalizedCode(normalizedRawCode,
                    "place(node.left, row + 1, left, mid - 1, answer)")
                    && containsNormalizedCode(normalizedRawCode,
                    "place(node.right, row + 1, mid + 1, right, answer)"));
            hasCoordinateCollection = hasCoordinateCollection
                    || ((searchable.contains("coordinate") || searchable.contains("materialize"))
                    && containsNormalizedCode(normalizedRawCode, "java.util.List<Placement> placements")
                    && containsNormalizedCode(normalizedRawCode,
                    "collect(root, 0, (cols - 1) / 2, height, placements)")
                    && containsNormalizedCode(normalizedRawCode,
                    "placements.add(new Placement(row, col, String.valueOf(node.val)))")
                    && containsNormalizedCode(normalizedRawCode, "private static final class Placement")
                    && containsNormalizedCode(normalizedRawCode,
                    "res.get(placement.row).set(placement.col, placement.value)"));
        }

        assertTrue(hasDfsOffset,
                filename + " must include the DFS height-and-offset placement route");
        assertTrue(hasBfsCoordinates,
                filename + " must include the BFS coordinate-queue route");
        assertTrue(hasIntervalRecursion,
                filename + " must include the column-interval recursion route");
        assertTrue(hasCoordinateCollection,
                filename + " must include the coordinate-collection materialization route");
    }

