    private static void assertFindKClosestElementsSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 4,
                filename + " Find K Closest Elements should teach left-bound binary search, shrink window, "
                        + "insertion-point expansion, and bounded max-heap ranking");

        boolean hasBinarySearchLeftBound = false;
        boolean hasTwoPointerShrink = false;
        boolean hasInsertionExpansion = false;
        boolean hasBoundedMaxHeap = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasBinarySearchLeftBound = hasBinarySearchLeftBound
                    || ((searchable.contains("binary") || searchable.contains("left bound"))
                    && containsNormalizedCode(normalizedRawCode, "int hi = arr.length - k")
                    && containsNormalizedCode(normalizedRawCode, "arr[mid + k]")
                    && containsNormalizedCode(normalizedRawCode, "lo = mid + 1")
                    && containsNormalizedCode(normalizedRawCode, "hi = mid"));
            hasTwoPointerShrink = hasTwoPointerShrink
                    || ((searchable.contains("shrink") || searchable.contains("two pointer"))
                    && containsNormalizedCode(normalizedRawCode, "while (right - left + 1 > k)")
                    && containsNormalizedCode(normalizedRawCode, "leftDistance <= rightDistance")
                    && containsNormalizedCode(normalizedRawCode, "right--")
                    && containsNormalizedCode(normalizedRawCode, "left++"));
            hasInsertionExpansion = hasInsertionExpansion
                    || ((searchable.contains("insertion") || searchable.contains("expand"))
                    && containsNormalizedCode(normalizedRawCode, "int right = lo")
                    && containsNormalizedCode(normalizedRawCode, "while (right - left - 1 < k)")
                    && containsNormalizedCode(normalizedRawCode, "x - arr[left] <= arr[right] - x")
                    && containsNormalizedCode(normalizedRawCode, "left--")
                    && containsNormalizedCode(normalizedRawCode, "right++"));
            hasBoundedMaxHeap = hasBoundedMaxHeap
                    || (searchable.contains("heap")
                    && containsNormalizedCode(normalizedRawCode,
                    "java.util.PriorityQueue<Integer> heap = new java.util.PriorityQueue<>")
                    && containsNormalizedCode(normalizedRawCode, "heap.size() > k")
                    && containsNormalizedCode(normalizedRawCode, "heap.poll()")
                    && containsNormalizedCode(normalizedRawCode, "java.util.Collections.sort(result)"));
        }

        assertTrue(hasBinarySearchLeftBound,
                filename + " must include the left-bound binary search route");
        assertTrue(hasTwoPointerShrink,
                filename + " must include the two-pointer shrink-window route");
        assertTrue(hasInsertionExpansion,
                filename + " must include the insertion-point expansion route");
        assertTrue(hasBoundedMaxHeap,
                filename + " must include the bounded max-heap route");
    }

