    private static void assertImageSmootherSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 4,
                filename + " Image Smoother should teach neighbor enumeration, 2D prefix sums, rolling column sums, "
                        + "and in-place encoding");

        boolean hasNeighborEnumeration = false;
        boolean hasPrefixSums = false;
        boolean hasRollingColumnSums = false;
        boolean hasInPlaceEncoding = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasNeighborEnumeration = hasNeighborEnumeration
                    || ((searchable.contains("neighbor") || searchable.contains("brute"))
                    && containsNormalizedCode(normalizedRawCode, "for (int dr = -1; dr <= 1; dr++)")
                    && containsNormalizedCode(normalizedRawCode, "for (int dc = -1; dc <= 1; dc++)")
                    && containsNormalizedCode(normalizedRawCode, "sum += img[nr][nc]")
                    && containsNormalizedCode(normalizedRawCode, "result[r][c] = sum / count"));
            hasPrefixSums = hasPrefixSums
                    || ((searchable.contains("prefix") || searchable.contains("2d"))
                    && containsNormalizedCode(normalizedRawCode, "int[][] prefix = new int[rows + 1][cols + 1]")
                    && containsNormalizedCode(normalizedRawCode, "prefix[r][c] = img[r - 1][c - 1]")
                    && containsNormalizedCode(normalizedRawCode, "prefix[bottom + 1][right + 1]")
                    && containsNormalizedCode(normalizedRawCode, "prefix[top][left]"));
            hasRollingColumnSums = hasRollingColumnSums
                    || ((searchable.contains("rolling") || searchable.contains("column"))
                    && containsNormalizedCode(normalizedRawCode, "int[] columnSums = new int[cols]")
                    && containsNormalizedCode(normalizedRawCode, "int[] columnCounts = new int[cols]")
                    && containsNormalizedCode(normalizedRawCode, "addRow(img, rowToAdd, columnSums, columnCounts)")
                    && containsNormalizedCode(normalizedRawCode, "windowSum += columnSums[rightColumn]"));
            hasInPlaceEncoding = hasInPlaceEncoding
                    || ((searchable.contains("in-place") || searchable.contains("encoded"))
                    && containsNormalizedCode(normalizedRawCode, "sum += img[nr][nc] & 255")
                    && containsNormalizedCode(normalizedRawCode, "img[r][c] |= (sum / count) << 8")
                    && containsNormalizedCode(normalizedRawCode, "img[r][c] >>= 8"));
        }

        assertTrue(hasNeighborEnumeration,
                filename + " must include the neighbor-enumeration route");
        assertTrue(hasPrefixSums,
                filename + " must include the 2D prefix-sum route");
        assertTrue(hasRollingColumnSums,
                filename + " must include the rolling column-sum route");
        assertTrue(hasInPlaceEncoding,
                filename + " must include the in-place encoding route");
    }

