    private static void assertMaximumWidthBinaryTreeSolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 4,
                filename + " Maximum Width of Binary Tree should teach BFS normalization, recursive DFS, "
                        + "iterative DFS, and level-boundary lists");

        boolean hasBfsNormalization = false;
        boolean hasRecursiveDfs = false;
        boolean hasIterativeDfs = false;
        boolean hasLevelBoundaryLists = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasBfsNormalization = hasBfsNormalization
                    || ((searchable.contains("bfs") || searchable.contains("level"))
                    && containsNormalizedCode(normalizedRawCode, "java.util.ArrayDeque<Entry> queue")
                    && containsNormalizedCode(normalizedRawCode, "long levelBase = queue.peekFirst().index")
                    && containsNormalizedCode(normalizedRawCode, "long normalized = entry.index - levelBase")
                    && containsNormalizedCode(normalizedRawCode, "queue.offer(new Entry(node.right, normalized * 2 + 1))"));
            hasRecursiveDfs = hasRecursiveDfs
                    || ((searchable.contains("recursive") || searchable.contains("dfs"))
                    && containsNormalizedCode(normalizedRawCode, "private final java.util.List<Long> firstIndexAtDepth")
                    && containsNormalizedCode(normalizedRawCode, "dfs(node.left, depth + 1, normalized * 2)")
                    && containsNormalizedCode(normalizedRawCode, "dfs(node.right, depth + 1, normalized * 2 + 1)"));
            hasIterativeDfs = hasIterativeDfs
                    || ((searchable.contains("iterative") || searchable.contains("stack"))
                    && containsNormalizedCode(normalizedRawCode, "java.util.ArrayDeque<Frame> stack")
                    && containsNormalizedCode(normalizedRawCode, "stack.push(new Frame(root, 0, 0L))")
                    && containsNormalizedCode(normalizedRawCode, "Frame frame = stack.pop()")
                    && containsNormalizedCode(normalizedRawCode, "stack.push(new Frame(frame.node.right, frame.depth + 1, normalized * 2 + 1))"));
            hasLevelBoundaryLists = hasLevelBoundaryLists
                    || ((searchable.contains("level") || searchable.contains("boundary"))
                    && containsNormalizedCode(normalizedRawCode, "java.util.List<TreeNode> levelNodes")
                    && containsNormalizedCode(normalizedRawCode, "java.util.List<Long> levelIndices")
                    && containsNormalizedCode(normalizedRawCode, "long last = levelIndices.get(levelIndices.size() - 1)")
                    && containsNormalizedCode(normalizedRawCode, "nextIndices.add(normalized * 2 + 1)"));
        }

        assertTrue(hasBfsNormalization,
                filename + " must include the BFS normalized-index route");
        assertTrue(hasRecursiveDfs,
                filename + " must include the recursive DFS first-index route");
        assertTrue(hasIterativeDfs,
                filename + " must include the iterative DFS stack route");
        assertTrue(hasLevelBoundaryLists,
                filename + " must include the level-boundary-list route");
    }

