    private static void assertBeautifulArrangementIISolutionSet(JsonArray solutions, String filename) {
        assertTrue(solutions.size() >= 4,
                filename + " Beautiful Arrangement II should teach prefix zigzag, tail zigzag, direct difference walk, "
                        + "and global-extreme shrinking");

        boolean hasPrefixZigzag = false;
        boolean hasTailZigzag = false;
        boolean hasDifferenceWalk = false;
        boolean hasGlobalExtremes = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = requireObject(solutions.get(i), filename + " solutions[" + i + "]");
            String name = requireNonBlankString(solution, "name", filename + " solutions[" + i + "]");
            String description = requireNonBlankString(solution, "description", filename + " solutions[" + i + "]");
            String code = requireNonBlankString(solution, "code", filename + " solutions[" + i + "]");
            String searchable = (name + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasPrefixZigzag = hasPrefixZigzag
                    || ((searchable.contains("prefix") || searchable.contains("zigzag"))
                    && containsNormalizedCode(normalizedRawCode, "int hi = k + 1")
                    && containsNormalizedCode(normalizedRawCode, "answer[i] = (i % 2 == 0) ? lo++ : hi--")
                    && containsNormalizedCode(normalizedRawCode, "for (int i = k + 1; i < n; i++)"));
            hasTailZigzag = hasTailZigzag
                    || ((searchable.contains("tail") || searchable.contains("prefix"))
                    && containsNormalizedCode(normalizedRawCode, "int prefixEnd = n - k")
                    && containsNormalizedCode(normalizedRawCode, "for (int value = 1; value < prefixEnd; value++)")
                    && containsNormalizedCode(normalizedRawCode, "int low = prefixEnd")
                    && containsNormalizedCode(normalizedRawCode, "answer[index++] = high--"));
            hasDifferenceWalk = hasDifferenceWalk
                    || ((searchable.contains("difference") || searchable.contains("walk"))
                    && containsNormalizedCode(normalizedRawCode, "for (int diff = k, index = 1; diff >= 1; diff--, index++)")
                    && containsNormalizedCode(normalizedRawCode, "value += diff")
                    && containsNormalizedCode(normalizedRawCode, "value -= diff"));
            hasGlobalExtremes = hasGlobalExtremes
                    || ((searchable.contains("global") || searchable.contains("extreme"))
                    && containsNormalizedCode(normalizedRawCode, "int remaining = k")
                    && containsNormalizedCode(normalizedRawCode, "if (remaining > 1)")
                    && containsNormalizedCode(normalizedRawCode, "answer[index] = high--")
                    && containsNormalizedCode(normalizedRawCode, "answer[index] = low++"));
        }

        assertTrue(hasPrefixZigzag,
                filename + " must include the prefix zigzag route");
        assertTrue(hasTailZigzag,
                filename + " must include the increasing-prefix tail-zigzag route");
        assertTrue(hasDifferenceWalk,
                filename + " must include the descending-difference walk route");
        assertTrue(hasGlobalExtremes,
                filename + " must include the global-extremes shrinking route");
    }

